#[derive(Debug, Clone, Serialize)]
enum Asset {
    List(Vec<Asset>),
    Ref {
        #[serde(default)]
        id: Option<String>,
        #[serde(default)]
        path: Option<String>,
    },
    #[serde(rename = "file")]
    File {
        path: String,
        #[serde(default)]
        sha256: Option<String>,
        #[serde(default)]
        length: Option<u64>,
    },
    #[serde(rename = "inline_bytes")]
    InlineBytes {
        encoding: String,
        #[serde(default)]
        value: Option<String>,
        #[serde(default)]
        data: Option<String>,
    },
    Other(Value),
}

impl<'de> Deserialize<'de> for Asset {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        Ok(asset_from_value(Value::deserialize(deserializer)?))
    }
}

fn asset_from_value(value: Value) -> Asset {
    if let Some(items) = value.as_array() {
        return Asset::List(items.iter().cloned().map(asset_from_value).collect());
    }
    let Some(object) = value.as_object() else {
        return Asset::Other(value);
    };
    match object.get("kind").and_then(Value::as_str) {
        Some("file") => {
            let Some(path) = object.get("path").and_then(Value::as_str) else {
                return Asset::Other(value);
            };
            Asset::File {
                path: path.to_string(),
                sha256: object
                    .get("sha256")
                    .and_then(Value::as_str)
                    .map(ToString::to_string),
                length: object.get("length").and_then(Value::as_u64),
            }
        }
        Some("ref") => Asset::Ref {
            id: object
                .get("id")
                .and_then(Value::as_str)
                .map(ToString::to_string),
            path: object
                .get("path")
                .and_then(Value::as_str)
                .map(ToString::to_string),
        },
        Some("inline_bytes") => {
            let Some(encoding) = object.get("encoding").and_then(Value::as_str) else {
                return Asset::Other(value);
            };
            Asset::InlineBytes {
                encoding: encoding.to_string(),
                value: object
                    .get("value")
                    .and_then(Value::as_str)
                    .map(ToString::to_string),
                data: object
                    .get("data")
                    .and_then(Value::as_str)
                    .map(ToString::to_string),
            }
        }
        _ => Asset::Other(value),
    }
}

