fn rust_get_kerning_optional(face: Option<&FT_Face>, params: &Value) -> Result<RunOutput, String> {
    let rows = kerning_rows(params)?
        .into_iter()
        .map(|row| {
            let (left_glyph, right_glyph) = if let Some(face) = face {
                (
                    rust_glyph_selector_index(face, &row.left)?,
                    rust_glyph_selector_index(face, &row.right)?,
                )
            } else {
                (0, 0)
            };
            let mut vector = FT_Vector::default();
            let status = FT_Get_Kerning(
                face,
                left_glyph,
                right_glyph,
                row.mode,
                (!kerning_akerning_is_null(params)).then_some(&mut vector),
            );
            Ok(KerningOutputRow {
                input: row,
                left_glyph,
                right_glyph,
                status,
                x: vector.x,
                y: vector.y,
            })
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok(kerning_output(rows))
}

fn c_get_kerning_with_face(face: c_abi::FT_Face, params: &Value) -> Result<RunOutput, String> {
    c_get_kerning_optional(Some(face), params)
}

fn c_get_kerning_optional(
    face: Option<c_abi::FT_Face>,
    params: &Value,
) -> Result<RunOutput, String> {
    let rows = kerning_rows(params)?
        .into_iter()
        .map(|row| {
            let (left_glyph, right_glyph) = if let Some(face) = face {
                (
                    c_glyph_selector_index(face, &row.left)?,
                    c_glyph_selector_index(face, &row.right)?,
                )
            } else {
                (0, 0)
            };
            let mut vector = c_abi::FT_Vector::default();
            let out = if kerning_akerning_is_null(params) {
                std::ptr::null_mut()
            } else {
                &mut vector
            };
            let status = c_abi::FT_Get_Kerning(
                face.unwrap_or(std::ptr::null_mut()),
                left_glyph,
                right_glyph,
                row.mode,
                out,
            );
            Ok(KerningOutputRow {
                input: row,
                left_glyph,
                right_glyph,
                status,
                x: vector.x,
                y: vector.y,
            })
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok(kerning_output(rows))
}

fn wasm_get_kerning_with_face(handle: usize, params: &Value) -> Result<RunOutput, String> {
    wasm_get_kerning_optional(Some(handle), params)
}

fn wasm_get_kerning_optional(handle: Option<usize>, params: &Value) -> Result<RunOutput, String> {
    let rows = kerning_rows(params)?
        .into_iter()
        .map(|row| {
            let (left_glyph, right_glyph) = if let Some(handle) = handle {
                (
                    wasm_glyph_selector_index(handle, &row.left)?,
                    wasm_glyph_selector_index(handle, &row.right)?,
                )
            } else {
                (0, 0)
            };
            let mut vector = wasm_abi::FontdoneWasmVector::default();
            let out = if kerning_akerning_is_null(params) {
                std::ptr::null_mut()
            } else {
                &mut vector
            };
            let status = wasm_abi::fontdone_wasm_get_kerning(
                handle.unwrap_or(0),
                left_glyph,
                right_glyph,
                row.mode,
                out,
            );
            Ok(KerningOutputRow {
                input: row,
                left_glyph,
                right_glyph,
                status,
                x: vector.x,
                y: vector.y,
            })
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok(kerning_output(rows))
}

fn kerning_output(rows: Vec<KerningOutputRow>) -> RunOutput {
    let first_error = rows
        .iter()
        .find_map(|row| (row.status != FT_Err_Ok).then_some(row.status))
        .unwrap_or(FT_Err_Ok);
    let (first_x, first_y) = rows.first().map_or((0, 0), |row| (row.x, row.y));
    let kerning_vectors = rows
        .iter()
        .map(|row| {
            json!({
                "left": &row.input.left,
                "right": &row.input.right,
                "mode": row.input.mode,
                "left_glyph": row.left_glyph,
                "right_glyph": row.right_glyph,
                "status": row.status,
                "akerning": {"x": row.x, "y": row.y},
                "kerning": {"x": row.x, "y": row.y},
                "x_26_6": row.x,
                "y_26_6": row.y,
                "units": kerning_units(row.input.mode),
            })
        })
        .collect::<Vec<_>>();
    let glyph_indexes = rows
        .iter()
        .map(|row| json!({"left": row.left_glyph, "right": row.right_glyph}))
        .collect::<Vec<_>>();
    let output = json!({
        "status": first_error,
        "kerning_vectors": kerning_vectors,
        "glyph_indexes": glyph_indexes,
        "akerning": {"x": first_x, "y": first_y},
        "kerning": {"x": first_x, "y": first_y}
    });
    if first_error == FT_Err_Ok {
        ok(output)
    } else {
        error_with_output(first_error, output)
    }
}

fn kerning_units(mode: u32) -> &'static str {
    match mode {
        mode if mode == FT_KERNING_UNFITTED as u32 => "unfitted_26_6_pixels",
        mode if mode == FT_KERNING_UNSCALED as u32 => "font_units",
        _ => "grid_fitted_26_6_pixels",
    }
}

fn assert_font_getkerning_agrees(case: &InputCase, output: &RunOutput) -> Result<(), String> {
    if !bool_param(&case.inputs.params, "assert_font_getkerning_agrees", false)? {
        return Ok(());
    }
    let data = font_bytes(case)?;
    let (_, pixel_height) = pixel_size_param(&case.inputs.params)?;
    let font = Font::truetype(data.as_ref(), pixel_height as f32)
        .map_err(|err| format!("{} Font::truetype returned {err}", case.case_id))?;
    let rows = output
        .output
        .get("kerning_vectors")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            format!(
                "{} assert_font_getkerning_agrees requires kerning_vectors output",
                case.case_id
            )
        })?;
    let mut checked = 0usize;
    for row in rows {
        if row.get("mode").and_then(Value::as_i64) != Some(i64::from(FT_KERNING_UNFITTED)) {
            continue;
        }
        let left = font_kerning_char_selector(row, "left")?;
        let right = font_kerning_char_selector(row, "right")?;
        let expected_x = row
            .pointer("/akerning/x")
            .and_then(Value::as_i64)
            .ok_or_else(|| format!("{} kerning row missing akerning.x", case.case_id))?;
        let expected_y = row
            .pointer("/akerning/y")
            .and_then(Value::as_i64)
            .ok_or_else(|| format!("{} kerning row missing akerning.y", case.case_id))?;
        let actual_x = i64::from(font.getkerning(left, right));
        if actual_x != expected_x || expected_y != 0 {
            return Err(format!(
                "{} Font::getkerning disagrees with FT_Get_Kerning(UNFITTED): pair={left}/{right} font=({}, 0) ffi=({}, {})",
                case.case_id, actual_x, expected_x, expected_y
            ));
        }
        checked += 1;
    }
    if checked == 0 {
        return Err(format!(
            "{} assert_font_getkerning_agrees found no FT_KERNING_UNFITTED rows",
            case.case_id
        ));
    }
    Ok(())
}

fn rust_get_advance_with_face(face: &FT_Face, case: &InputCase) -> Result<RunOutput, String> {
    if get_advance_probe_labels(&case.inputs.params).is_ok() {
        return get_advance_probe_output(&case.inputs.params, |probe, advance| match probe {
            // The safe Rust FFI takes `&FT_Face` and returns the advance by
            // value.  These branches represent the corresponding public C
            // argument validation from FreeType `src/base/ftadvanc.c:116-120`.
            "null_face" => FT_Err_Invalid_Face_Handle as FT_Error,
            "null_padvance" => {
                let _ = face;
                let _ = advance;
                FT_Err_Invalid_Argument
            }
            _ => FT_Err_Invalid_Argument,
        });
    }
    let output = match FT_Get_Advance(
        face,
        glyph_index_param(&case.inputs.params)?,
        load_flags_param(&case.inputs.params)?,
    ) {
        Ok(advance) => ok(advance_json(advance)),
        Err(err) => error(err),
    };
    assert_font_hori_advance_agrees(case, &output)?;
    Ok(output)
}

fn get_advance_probe_output<F>(params: &Value, mut run: F) -> Result<RunOutput, String>
where
    F: FnMut(&str, &mut FT_Fixed) -> FT_Error,
{
    let probes = get_advance_probe_labels(params)?;
    let sentinel = i64_param(params, "sentinel_padvance")?;
    let mut first_error = FT_Err_Ok;
    let mut rows = Vec::with_capacity(probes.len());
    for probe in probes {
        let mut advance = sentinel;
        let error = run(&probe, &mut advance);
        if first_error == FT_Err_Ok && error != FT_Err_Ok {
            first_error = error;
        }
        rows.push(json!({
            "probe": probe,
            "status": error,
            "error": error,
            "padvance": advance,
            "padvance_preserved": advance == sentinel
        }));
    }
    Ok(error_with_output(first_error, json!({"rows": rows})))
}

fn get_advance_probe_labels(params: &Value) -> Result<Vec<String>, String> {
    string_array_param(params, "probes")
}

fn get_advances_probe_output<F>(params: &Value, mut run: F) -> Result<RunOutput, String>
where
    F: FnMut(&str, &mut [FT_Fixed]) -> FT_Error,
{
    let probes = get_advances_probe_labels(params)?;
    let sentinel = i64_param(params, "sentinel_array")?;
    let (_, count) = advance_range_param(params)?;
    let out_len = usize::try_from(count).map_err(|err| err.to_string())?;
    let mut first_error = FT_Err_Ok;
    let mut rows = Vec::with_capacity(probes.len());
    for probe in probes {
        let mut advances = vec![sentinel; out_len.max(1)];
        let error = run(&probe, &mut advances[..out_len]);
        if first_error == FT_Err_Ok && error != FT_Err_Ok {
            first_error = error;
        }
        let output_values = advances[..out_len].to_vec();
        rows.push(json!({
            "probe": probe,
            "status": error,
            "error": error,
            "padvances": output_values,
            "padvances_preserved": output_values.iter().all(|advance| *advance == sentinel)
        }));
    }
    Ok(error_with_output(first_error, json!({"rows": rows})))
}

fn get_advances_probe_labels(params: &Value) -> Result<Vec<String>, String> {
    string_array_param(params, "probes")
}

fn assert_font_hori_advance_agrees(case: &InputCase, output: &RunOutput) -> Result<(), String> {
    if !bool_param(
        &case.inputs.params,
        "assert_font_hori_advance_agrees",
        false,
    )? {
        return Ok(());
    }
    if output.status.kind != StatusKind::Ok {
        return Err(format!(
            "{} assert_font_hori_advance_agrees requires successful FT_Get_Advance output",
            case.case_id
        ));
    }
    let load_flags = load_flags_param(&case.inputs.params)?;
    if load_flags & (FT_LOAD_VERTICAL_LAYOUT | FT_LOAD_NO_SCALE) != 0
        || (load_flags & FT_LOAD_NO_HINTING == 0
            && FT_LOAD_TARGET_MODE(load_flags) != FT_RENDER_MODE_LIGHT)
    {
        return Err(format!(
            "{} assert_font_hori_advance_agrees requires horizontal scaled fast-path flags",
            case.case_id
        ));
    }
    let codepoint = u32_param(&case.inputs.params, "advance_codepoint")?;
    let data = font_bytes(case)?;
    let (_, pixel_height) = pixel_size_param(&case.inputs.params)?;
    let font =
        Font::truetype_with_load_mode(data.as_ref(), pixel_height as f32, LoadMode::NoHinting)
            .map_err(|err| format!("{} Font constructor returned {err}", case.case_id))?;
    let actual = i64::from(font.glyph_hori_advance_26dot6(codepoint));
    let expected_16dot16 = output
        .output
        .get("advance")
        .and_then(Value::as_i64)
        .ok_or_else(|| format!("{} FT_Get_Advance output missing advance", case.case_id))?;
    if expected_16dot16 < 0 {
        return Err(format!(
            "{} assert_font_hori_advance_agrees requires non-negative horizontal advance",
            case.case_id
        ));
    }
    let expected = (expected_16dot16 + 512) >> 10;
    if actual != expected {
        return Err(format!(
            "{} Font::glyph_hori_advance_26dot6 disagrees with FT_Get_Advance: font={actual} ft_fixed_rounded={expected}",
            case.case_id
        ));
    }
    Ok(())
}

fn font_kerning_char_selector(row: &Value, key: &str) -> Result<char, String> {
    let selector = row
        .get(key)
        .and_then(Value::as_str)
        .ok_or_else(|| format!("kerning row missing {key} selector"))?;
    if let Some(hex) = selector.strip_prefix("U+") {
        let value = u32::from_str_radix(hex, 16)
            .map_err(|err| format!("invalid Unicode selector {selector}: {err}"))?;
        return char::from_u32(value)
            .ok_or_else(|| format!("invalid Unicode scalar selector {selector}"));
    }
    let mut chars = selector.chars();
    let ch = chars
        .next()
        .ok_or_else(|| format!("empty kerning selector {key}"))?;
    if chars.next().is_some() {
        return Err(format!(
            "Font::getkerning assertion requires one-character selectors, got {selector}"
        ));
    }
    Ok(ch)
}

fn rust_glyph_selector_index(face: &FT_Face, selector: &str) -> Result<u32, String> {
    glyph_selector_index(selector, |char_code| FT_Get_Char_Index(face, char_code))
}

fn c_glyph_selector_index(face: c_abi::FT_Face, selector: &str) -> Result<u32, String> {
    glyph_selector_index(selector, |char_code| {
        c_abi::FT_Get_Char_Index(face, char_code)
    })
}

fn wasm_glyph_selector_index(handle: usize, selector: &str) -> Result<u32, String> {
    glyph_selector_index(selector, |char_code| {
        wasm_abi::fontdone_wasm_get_char_index(handle, char_code)
    })
}

fn glyph_selector_index(
    selector: &str,
    mut char_index: impl FnMut(u64) -> u32,
) -> Result<u32, String> {
    let selector = selector.trim();
    if matches!(selector, "" | "glyph0" | ".notdef") {
        return Ok(0);
    }
    if let Some(raw) = selector.strip_prefix("gid:") {
        return raw
            .parse::<u32>()
            .map_err(|err| format!("parse glyph selector {selector}: {err}"));
    }
    if let Some(raw) = selector.strip_prefix("U+") {
        let char_code = u64::from_str_radix(raw, 16)
            .map_err(|err| format!("parse glyph selector {selector}: {err}"))?;
        return Ok(char_index(char_code));
    }
    let mut chars = selector.chars();
    if let (Some(ch), None) = (chars.next(), chars.next()) {
        return Ok(char_index(u64::from(u32::from(ch))));
    }
    Ok(0)
}

fn os2_unicode_ranges_json(
    table_present: bool,
    ul_unicode_range1: u64,
    ul_unicode_range2: u64,
    ul_unicode_range3: u64,
    ul_unicode_range4: u64,
    glyph_indices: Vec<u32>,
) -> Value {
    json!({
        "table_present": table_present,
        "has_os2_table": table_present,
        "ulUnicodeRange1": ul_unicode_range1,
        "ulUnicodeRange2": ul_unicode_range2,
        "ulUnicodeRange3": ul_unicode_range3,
        "ulUnicodeRange4": ul_unicode_range4,
        "glyph_indices": glyph_indices,
    })
}

fn rust_load_sfnt_table_output(
    face: &FT_Face,
    case: &InputCase,
    params: &Value,
) -> Result<RunOutput, String> {
    let tag = load_sfnt_table_tag_value(params)?;
    let offset = load_sfnt_table_offset_arg(params)?
        .parse::<i64>()
        .map_err(|e| e.to_string())?;
    if load_sfnt_table_length_state_arg(params)? == "null" {
        return match FT_Load_Sfnt_Table(face, tag, offset as FT_Long, None) {
            Ok(Some(bytes)) => Ok(ok(json!({
                "length_after": Value::Null,
                "bytes_written": hex_bytes(&bytes),
                "bytes_hash": djb2_hash(&bytes)
            }))),
            Ok(None) => Ok(ok(json!({
                "length_after": Value::Null
            }))),
            Err(err) => Ok(error_with_output(
                err,
                json!({
                    "length_after": Value::Null
                }),
            )),
        };
    }
    if let Some(length) = params.get("core_length_request").and_then(Value::as_u64) {
        let data = font_bytes(case)?;
        let face_index = usize::try_from(face_index_param(params)?)
            .map_err(|err| format!("load_sfnt_table face_index does not fit usize: {err}"))?;
        let font = Font::truetype_face(data.as_ref(), face_index, 10.0)
            .map_err(|err| format!("load sfnt core font: {err}"))?;
        let Ok(tag) = u32::try_from(tag) else {
            return Ok(error(FT_Err_Table_Missing as FT_Error));
        };
        return match font.load_sfnt_table(tag, offset, Some(length as usize)) {
            Ok(bytes) => Ok(ok(json!({
                "length_after": bytes.len() as FT_ULong,
                "bytes_written": hex_bytes(&bytes),
                "bytes_hash": djb2_hash(&bytes)
            }))),
            Err(_) if font.sfnt_table_len(tag).is_err() => {
                Ok(error(FT_Err_Table_Missing as FT_Error))
            }
            Err(_) => Ok(error(FT_Err_Invalid_Stream_Operation as FT_Error)),
        };
    }
    let mut length: FT_ULong = 0;
    // Probe first to get the actual table size.
    match FT_Load_Sfnt_Table(face, tag, offset as FT_Long, Some(&mut length)) {
        Ok(None) => {
            // Length probe succeeded; length now holds the remaining table size.
            let copy_len = load_sfnt_table_copy_len(params);
            if let Some(wanted) = copy_len {
                // Fixture specifies a length_request: perform a second call
                // to actually copy the bytes and produce a hash.
                let mut want = wanted.min(length);
                let result = FT_Load_Sfnt_Table(face, tag, offset as FT_Long, Some(&mut want));
                match result {
                    Ok(Some(bytes)) => {
                        let hash = djb2_hash(&bytes);
                        Ok(ok(json!({
                            "length_after": want,
                            "bytes_written": hex_bytes(&bytes),
                            "bytes_hash": hash
                        })))
                    }
                    Ok(None) => Ok(ok(json!({
                        "length_after": want
                    }))),
                    Err(err) => Ok(error_with_output(
                        err,
                        json!({
                            "length_after": want
                        }),
                    )),
                }
            } else {
                // No length_request: return probe result only.
                Ok(ok(json!({
                    "length_after": length
                })))
            }
        }
        Err(err) => Ok(error_with_output(
            err,
            json!({
                "length_after": length
            }),
        )),
        _ => unreachable!(),
    }
}

fn c_load_sfnt_table_output(face: c_abi::FT_Face, params: &Value) -> Result<RunOutput, String> {
    let tag = load_sfnt_table_tag_value(params)?;
    let offset = load_sfnt_table_offset_arg(params)?
        .parse::<i64>()
        .map_err(|e| e.to_string())? as c_abi::FT_Long;
    let length_state = load_sfnt_table_initial_length(params)?;
    if length_state.is_none() {
        let buffer_kind = load_sfnt_table_buffer_kind_arg(params)?;
        let mut probe_len: c_abi::FT_ULong = 0;
        let _ = c_abi::FT_Load_Sfnt_Table(face, tag, 0, ptr::null_mut(), &mut probe_len);
        let mut buffer = vec![0u8; usize::try_from(probe_len).unwrap_or(0).max(1)];
        let buffer_ptr = if buffer_kind == "allocated" {
            buffer.as_mut_ptr()
        } else {
            ptr::null_mut()
        };
        let err = c_abi::FT_Load_Sfnt_Table(face, tag, offset, buffer_ptr, ptr::null_mut());
        return sfnt_table_bytes_output(
            err,
            None,
            &buffer,
            Some(probe_len),
            buffer_kind == "allocated",
        );
    }
    let mut length = length_state.unwrap_or(0);
    let buffer_kind = load_sfnt_table_buffer_kind_arg(params)?;
    let mut buffer = vec![0u8; usize::try_from(length).unwrap_or(0).max(1)];
    let buffer_ptr = if buffer_kind == "allocated" {
        buffer.as_mut_ptr()
    } else {
        ptr::null_mut()
    };
    let err = c_abi::FT_Load_Sfnt_Table(face, tag, offset, buffer_ptr, &mut length);
    sfnt_table_bytes_output(err, Some(length), &buffer, None, buffer_kind == "allocated")
}

fn wasm_load_sfnt_table_output(handle: usize, params: &Value) -> Result<RunOutput, String> {
    let tag = load_sfnt_table_tag_value(params)?;
    let offset = load_sfnt_table_offset_arg(params)?
        .parse::<i64>()
        .map_err(|e| e.to_string())? as wasm_abi::FT_Long;
    let length_state = load_sfnt_table_initial_length(params)?;
    if length_state.is_none() {
        let buffer_kind = load_sfnt_table_buffer_kind_arg(params)?;
        let mut probe_len: wasm_abi::FT_ULong = 0;
        let _ = wasm_abi::fontdone_wasm_load_sfnt_table(
            handle,
            tag,
            0,
            ptr::null_mut(),
            &mut probe_len,
        );
        let mut buffer = vec![0u8; usize::try_from(probe_len).unwrap_or(0).max(1)];
        let buffer_ptr = if buffer_kind == "allocated" {
            buffer.as_mut_ptr()
        } else {
            ptr::null_mut()
        };
        let err = wasm_abi::fontdone_wasm_load_sfnt_table(
            handle,
            tag,
            offset,
            buffer_ptr,
            ptr::null_mut(),
        );
        return sfnt_table_bytes_output(
            err,
            None,
            &buffer,
            Some(probe_len),
            buffer_kind == "allocated",
        );
    }
    let mut length = length_state.unwrap_or(0);
    let buffer_kind = load_sfnt_table_buffer_kind_arg(params)?;
    let mut buffer = vec![0u8; usize::try_from(length).unwrap_or(0).max(1)];
    let buffer_ptr = if buffer_kind == "allocated" {
        buffer.as_mut_ptr()
    } else {
        ptr::null_mut()
    };
    let err = wasm_abi::fontdone_wasm_load_sfnt_table(handle, tag, offset, buffer_ptr, &mut length);
    sfnt_table_bytes_output(err, Some(length), &buffer, None, buffer_kind == "allocated")
}

fn sfnt_table_bytes_output(
    err: FT_Error,
    length_after: Option<FT_ULong>,
    buffer: &[u8],
    copied_len: Option<FT_ULong>,
    buffer_allocated: bool,
) -> Result<RunOutput, String> {
    let length_json = length_after.map_or(Value::Null, |length| json!(length));
    if err != FT_Err_Ok {
        return Ok(error_with_output(
            err,
            json!({
                "length_after": length_json
            }),
        ));
    }
    let mut output = json!({
        "length_after": length_json
    });
    let bytes_len = copied_len.or(length_after).unwrap_or(0);
    if buffer_allocated && bytes_len > 0 {
        let bytes_len = usize::try_from(bytes_len).map_err(|err| err.to_string())?;
        let bytes = buffer
            .get(..bytes_len)
            .ok_or_else(|| format!("sfnt copied length {bytes_len} exceeds buffer"))?;
        output["bytes_written"] = json!(hex_bytes(bytes));
        output["bytes_hash"] = json!(djb2_hash(bytes));
    }
    Ok(ok(output))
}

fn load_sfnt_table_copy_len(params: &Value) -> Option<FT_ULong> {
    // Try to get length_request from reads array first entry.
    if let Some(reads) = params.get("reads").and_then(Value::as_array) {
        if let Some(first) = reads.first() {
            if let Some(len) = first.get("length_request") {
                if let Some(n) = len.as_u64() {
                    return Some(n as FT_ULong);
                }
                if let Some(s) = len.as_str() {
                    if s == "full" {
                        return None; // Use probe size
                    }
                    if let Ok(n) = s.parse::<u64>() {
                        return Some(n as FT_ULong);
                    }
                }
            }
        }
    }
    if let Some(state) = params.get("length_state").and_then(Value::as_str) {
        if let Ok(n) = state.parse::<u64>() {
            return Some(n as FT_ULong);
        }
    }
    None
}

fn rust_sfnt_get_table_output(face: &FT_Face, params: &Value) -> Result<RunOutput, String> {
    let tags_csv = sfnt_get_table_tags_arg(params)?;
    let mut entries = Vec::new();
    for token in tags_csv.split(',') {
        let token = token.trim();
        if token.is_empty() {
            continue;
        }
        let tag_val = token
            .parse::<i64>()
            .map_err(|e| format!("invalid tag value {token}: {e}"))?;
        let ptr = FT_Get_Sfnt_Table(face, tag_val as FT_Sfnt_Tag);
        let pointer_null = ptr.is_null();
        let record_kind = if pointer_null {
            Value::Null
        } else {
            Value::String(match tag_val {
                v if v == FT_SFNT_HEAD => "TT_Header".to_string(),
                v if v == FT_SFNT_MAXP => "TT_MaxProfile".to_string(),
                v if v == FT_SFNT_OS2 => "TT_OS2".to_string(),
                v if v == FT_SFNT_HHEA => "TT_HoriHeader".to_string(),
                v if v == FT_SFNT_VHEA => "TT_VertHeader".to_string(),
                v if v == FT_SFNT_POST => "TT_Postscript".to_string(),
                v if v == FT_SFNT_PCLT => "TT_PCLT".to_string(),
                _ => "unknown".to_string(),
            })
        };
        entries.push(json!({
            "tag": tag_val as FT_ULong,
            "pointer_null": pointer_null,
            "record_kind": record_kind
        }));
    }
    Ok(ok(json!({"entries": entries})))
}

fn rust_sfnt_table_info_output(face: &FT_Face, params: &Value) -> Result<RunOutput, String> {
    let tag_ptr_state = sfnt_table_info_tag_ptr_arg(params)?;
    let length_ptr_state = sfnt_table_info_length_ptr_arg(params)?;
    let index = sfnt_table_info_index_arg(params)?
        .parse::<u32>()
        .map_err(|e| e.to_string())?;
    let mut tag_after: FT_ULong = 0;
    let mut length_after: FT_ULong = 0;
    let tag_ptr = if tag_ptr_state == "non_null" {
        Some(&mut tag_after)
    } else {
        None
    };
    let length_ptr = if length_ptr_state == "non_null" {
        Some(&mut length_after)
    } else {
        None
    };
    let err = FT_Sfnt_Table_Info(face, index as FT_UInt, tag_ptr, length_ptr);
    sfnt_table_info_result(err, tag_after, length_after)
}

