fn postscript_name_json(name: Option<&str>) -> Value {
    nullable_c_string_json(name)
}

fn nullable_c_string_json(value: Option<&str>) -> Value {
    match value {
        Some(value) => json!({
            "null": false,
            "bytes": hex_bytes(value.as_bytes()),
            "length": value.len()
        }),
        None => json!({
            "null": true,
            "bytes": "",
            "length": 0
        }),
    }
}

fn font_format_alias_json(font_format: Option<&str>, x11_font_format: Option<&str>) -> Value {
    json!({
        "font_format_return": nullable_c_string_json(font_format),
        "x11_font_format_return": nullable_c_string_json(x11_font_format),
        "alias_equal": font_format == x11_font_format
    })
}

fn c_postscript_name_json(name: *const std::ffi::c_char) -> Value {
    c_nullable_c_string_json(name)
}

fn c_nullable_c_string_json(name: *const std::ffi::c_char) -> Value {
    if name.is_null() {
        return nullable_c_string_json(None);
    }
    let bytes = c_abi::abi_c_string_bytes(name);
    json!({
        "null": false,
        "bytes": hex_bytes(&bytes),
        "length": bytes.len()
    })
}

fn c_font_format_alias_json(face: c_abi::FT_Face) -> Value {
    let font_format = c_abi::FT_Get_Font_Format(face);
    let x11_font_format = c_abi::FT_Get_X11_Font_Format(face);
    json!({
        "font_format_return": c_nullable_c_string_json(font_format),
        "x11_font_format_return": c_nullable_c_string_json(x11_font_format),
        "alias_equal": font_format == x11_font_format
    })
}

fn wasm_postscript_name_json(handle: usize) -> Value {
    wasm_fontdone_string_json(|out| wasm_abi::fontdone_wasm_get_postscript_name(handle, out))
}

fn wasm_font_format_json(handle: usize, x11_alias: bool) -> Value {
    if x11_alias {
        wasm_fontdone_string_json(|out| wasm_abi::fontdone_wasm_get_x11_font_format(handle, out))
    } else {
        wasm_fontdone_string_json(|out| wasm_abi::fontdone_wasm_get_font_format(handle, out))
    }
}

fn wasm_font_format_alias_json(handle: usize) -> Value {
    let mut font_format = wasm_abi::FontdoneWasmString::default();
    let mut x11_font_format = wasm_abi::FontdoneWasmString::default();
    let font_ok = wasm_abi::fontdone_wasm_get_font_format(handle, &mut font_format) != 0;
    let x11_ok = wasm_abi::fontdone_wasm_get_x11_font_format(handle, &mut x11_font_format) != 0;
    json!({
        "font_format_return": wasm_string_record_json(font_ok, font_format),
        "x11_font_format_return": wasm_string_record_json(x11_ok, x11_font_format),
        "alias_equal": font_ok == x11_ok
            && font_format.string == x11_font_format.string
            && font_format.string_len == x11_font_format.string_len
    })
}

fn wasm_fontdone_string_json(
    f: impl FnOnce(*mut wasm_abi::FontdoneWasmString) -> FT_Bool,
) -> Value {
    let mut name = wasm_abi::FontdoneWasmString::default();
    let ok = f(&mut name) != 0;
    wasm_string_record_json(ok, name)
}

fn wasm_string_record_json(ok: bool, name: wasm_abi::FontdoneWasmString) -> Value {
    if !ok {
        return nullable_c_string_json(None);
    }
    let bytes = c_abi::abi_byte_slice(name.string, name.string_len);
    json!({
        "null": false,
        "bytes": hex_bytes(&bytes),
        "length": bytes.len()
    })
}

fn error_string_codes_arg(params: &Value) -> Result<String, String> {
    Ok(error_string_codes(params)?
        .into_iter()
        .map(|code| code.to_string())
        .collect::<Vec<_>>()
        .join(","))
}

fn error_string_codes(params: &Value) -> Result<Vec<i32>, String> {
    let mut codes = Vec::new();
    if let Some(value) = params.get("error_code") {
        codes.push(error_string_code_value(value, "error_code")?);
    }
    if let Some(values) = params.get("error_codes") {
        for value in values
            .as_array()
            .ok_or_else(|| "error_codes must be an array".to_string())?
        {
            codes.push(error_string_code_value(value, "error_codes")?);
        }
    }
    if let Some(value) = params.get("base_error") {
        codes.push(error_string_code_value(value, "base_error")?);
    }
    if let Some(value) = params.get("module_error_expression") {
        codes.push(error_string_code_value(value, "module_error_expression")?);
    }
    if codes.is_empty() {
        return Err("FT_Error_String case must query at least one error code".to_string());
    }
    Ok(codes)
}

fn error_string_code_value(value: &Value, key: &str) -> Result<i32, String> {
    let code = if let Some(object) = value.as_object() {
        if let Some(raw) = object.get("value_from_pinned_header") {
            i64_value(raw, key)?
        } else if let Some(symbol) = object.get("symbol").and_then(Value::as_str) {
            rust_constant(symbol)?
        } else {
            return Err(format!(
                "{key} object must contain value_from_pinned_header or symbol"
            ));
        }
    } else {
        i64_value(value, key)?
    };
    i32::try_from(code).map_err(|err| format!("{key} does not fit FT_Error: {err}"))
}

fn error_string_output<F>(params: &Value, mut lookup: F) -> Result<Value, String>
where
    F: FnMut(i32) -> Option<Vec<u8>>,
{
    let queries = error_string_codes(params)?
        .into_iter()
        .map(|code| {
            let bytes = lookup(code);
            json!({
                "code": code,
                "null": bytes.is_none(),
                "bytes": bytes.as_deref().map(hex_bytes).unwrap_or_default(),
                "length": bytes.as_ref().map_or(0, Vec::len)
            })
        })
        .collect::<Vec<_>>();
    Ok(json!({
        "build_has_error_strings": FT_CONFIG_OPTION_ERROR_STRINGS_ENABLED,
        "queries": queries
    }))
}

fn rust_error_string(case: &InputCase) -> Result<RunOutput, String> {
    Ok(ok(error_string_output(&case.inputs.params, |code| {
        FT_Error_String(code).map(|text| text.to_bytes().to_vec())
    })?))
}

fn c_error_string(case: &InputCase) -> Result<RunOutput, String> {
    Ok(ok(error_string_output(&case.inputs.params, |code| {
        let ptr = c_abi::FT_Error_String(code);
        (!ptr.is_null()).then(|| c_abi::abi_c_string_bytes(ptr))
    })?))
}

fn wasm_error_string(case: &InputCase) -> Result<RunOutput, String> {
    Ok(ok(error_string_output(&case.inputs.params, |code| {
        let mut out = wasm_abi::FontdoneWasmString::default();
        if wasm_abi::fontdone_wasm_error_string(code, &mut out) == 0 {
            return None;
        }
        Some(c_abi::abi_byte_slice(out.string, out.string_len))
    })?))
}

fn has_postscript_name_variants(params: &Value) -> bool {
    params.get("face_variants").is_some() || params.get("named_instances").is_some()
}

fn postscript_name_variant_values(params: &Value) -> Result<Vec<String>, String> {
    if params.get("face_variants").is_some() {
        return string_array_param(params, "face_variants");
    }
    array_param(params, "named_instances")?
        .iter()
        .map(|item| {
            if let Some(value) = item.as_str() {
                return Ok(value.to_string());
            }
            let Some(value) = item.as_u64() else {
                return Err(format!("named_instances contains unsupported value {item}"));
            };
            Ok(value.to_string())
        })
        .collect()
}

fn postscript_name_named_instance_index(
    params: &Value,
    variant: &str,
) -> Result<Option<FT_UInt>, String> {
    if params.get("named_instances").is_none() {
        return Ok(None);
    }
    if variant == "null" {
        return Ok(None);
    }
    if variant == "default" {
        return Ok(Some(0));
    }
    let value = variant
        .parse::<u64>()
        .map_err(|err| format!("invalid named instance variant {variant}: {err}"))?;
    FT_UInt::try_from(value)
        .map(Some)
        .map_err(|err| format!("named instance {value} does not fit FT_UInt: {err}"))
}

fn set_named_instance_index_param(params: &Value) -> Result<FT_UInt, String> {
    let value = u64_param(params, "instance_index")?;
    FT_UInt::try_from(value)
        .map_err(|err| format!("instance_index {value} does not fit FT_UInt: {err}"))
}

fn default_named_instance_sentinel(params: &Value) -> Result<FT_UInt, String> {
    let value = u64_param(params, "instance_index_initial")?;
    FT_UInt::try_from(value)
        .map_err(|err| format!("instance_index_initial {value} does not fit FT_UInt: {err}"))
}

fn default_named_instance_row(
    variant: &str,
    status: FT_Error,
    before: FT_UInt,
    after: FT_UInt,
) -> Value {
    json!({
        "variant": variant,
        "status": status,
        "instance_index_before": before,
        "instance_index_after": after,
    })
}

fn default_named_instance_output(status: FT_Error, output: Value) -> RunOutput {
    if status == FT_Err_Ok {
        ok(output)
    } else {
        error_with_output(status, output)
    }
}

fn rust_get_default_named_instance(case: &InputCase) -> Result<RunOutput, String> {
    let before = default_named_instance_sentinel(&case.inputs.params)?;
    if case.case == "invalid_face_error" {
        let mut null_after = before;
        let null_status = FT_Get_Default_Named_Instance(None, Some(&mut null_after));
        let face = rust_new_face_without_size(case)?;
        let mut non_variable_after = before;
        let non_variable_status =
            FT_Get_Default_Named_Instance(Some(&face), Some(&mut non_variable_after));
        return Ok(default_named_instance_output(
            null_status,
            json!({"rows": [
                default_named_instance_row("null", null_status, before, null_after),
                default_named_instance_row(
                    "non_variable",
                    non_variable_status,
                    before,
                    non_variable_after,
                ),
            ]}),
        ));
    }
    let face = rust_new_face_without_size(case)?;
    let mut after = before;
    let status = FT_Get_Default_Named_Instance(Some(&face), Some(&mut after));
    Ok(default_named_instance_output(
        status,
        default_named_instance_row("variable", status, before, after),
    ))
}

fn c_get_default_named_instance(case: &InputCase) -> Result<RunOutput, String> {
    let before = default_named_instance_sentinel(&case.inputs.params)?;
    if case.case == "invalid_face_error" {
        let mut null_after = before;
        let null_status =
            c_abi::FT_Get_Default_Named_Instance(std::ptr::null_mut(), &mut null_after);
        let (library, face) = c_new_face_without_size(case)?;
        let mut non_variable_after = before;
        let non_variable_status =
            c_abi::FT_Get_Default_Named_Instance(face, &mut non_variable_after);
        c_done_face(face);
        c_done_library(library);
        return Ok(default_named_instance_output(
            null_status,
            json!({"rows": [
                default_named_instance_row("null", null_status, before, null_after),
                default_named_instance_row(
                    "non_variable",
                    non_variable_status,
                    before,
                    non_variable_after,
                ),
            ]}),
        ));
    }
    let (library, face) = c_new_face_without_size(case)?;
    let mut after = before;
    let status = c_abi::FT_Get_Default_Named_Instance(face, &mut after);
    c_done_face(face);
    c_done_library(library);
    Ok(default_named_instance_output(
        status,
        default_named_instance_row("variable", status, before, after),
    ))
}

fn wasm_get_default_named_instance(case: &InputCase) -> Result<RunOutput, String> {
    let before = default_named_instance_sentinel(&case.inputs.params)?;
    if case.case == "invalid_face_error" {
        let mut null_after = before;
        let null_status = wasm_abi::fontdone_wasm_get_default_named_instance(0, &mut null_after);
        let handle = wasm_new_face_without_size(case)?;
        let mut non_variable_after = before;
        let non_variable_status =
            wasm_abi::fontdone_wasm_get_default_named_instance(handle, &mut non_variable_after);
        wasm_done_face(handle);
        return Ok(default_named_instance_output(
            null_status,
            json!({"rows": [
                default_named_instance_row("null", null_status, before, null_after),
                default_named_instance_row(
                    "non_variable",
                    non_variable_status,
                    before,
                    non_variable_after,
                ),
            ]}),
        ));
    }
    let handle = wasm_new_face_without_size(case)?;
    let mut after = before;
    let status = wasm_abi::fontdone_wasm_get_default_named_instance(handle, &mut after);
    wasm_done_face(handle);
    Ok(default_named_instance_output(
        status,
        default_named_instance_row("variable", status, before, after),
    ))
}

fn prior_named_instance_index_param(params: &Value) -> Result<Option<FT_UInt>, String> {
    let Ok(prior_calls) = array_param(params, "prior_calls") else {
        return Ok(None);
    };
    for call in prior_calls {
        let operation = call
            .get("operation")
            .and_then(Value::as_str)
            .unwrap_or_default();
        if operation != "FT_Set_Named_Instance" {
            continue;
        }
        let value = call
            .get("instance_index")
            .and_then(Value::as_u64)
            .ok_or_else(|| "FT_Set_Named_Instance prior call missing instance_index".to_string())?;
        return FT_UInt::try_from(value)
            .map(Some)
            .map_err(|err| format!("prior instance_index {value} does not fit FT_UInt: {err}"));
    }
    Ok(None)
}

fn set_named_instance_prior_arg(params: &Value) -> Result<String, String> {
    prior_named_instance_index_param(params).map(|value| {
        value
            .map(|instance| instance.to_string())
            .unwrap_or_else(|| "-".to_string())
    })
}

fn has_adobe_mm_prior_call(params: &Value) -> bool {
    array_param(params, "prior_calls").is_ok_and(|prior_calls| {
        prior_calls.iter().any(|call| {
            call.get("operation")
                .and_then(Value::as_str)
                .is_some_and(|operation| operation == "FT_Set_MM_Design_Coordinates")
        })
    })
}

fn named_instance_observation_json(
    status: FT_Error,
    info: &FT_FaceRecPublic,
    postscript_name: Value,
) -> Value {
    json!({
        "return": status,
        "face_index": info.face_index,
        "face_flags": info.face_flags,
        "variation_bit_set": (info.face_flags & FT_FACE_FLAG_VARIATION) != 0,
        "postscript_name": postscript_name
    })
}

fn named_instance_null_face_output(status: FT_Error) -> RunOutput {
    error_with_output(
        status,
        json!({
            "return": status,
            "face_index": Value::Null,
            "face_flags": Value::Null,
            "variation_bit_set": Value::Null,
            "postscript_name": postscript_name_json(None)
        }),
    )
}

fn named_instance_run_output(
    status: FT_Error,
    info: &FT_FaceRecPublic,
    postscript_name: Value,
) -> RunOutput {
    let output = named_instance_observation_json(status, info, postscript_name);
    if status == FT_Err_Ok {
        ok(output)
    } else {
        error_with_output(status, output)
    }
}

fn rust_postscript_name_variant_output(
    face: &mut FT_Face,
    params: &Value,
    variant: &str,
) -> Result<Value, String> {
    if variant == "null" {
        return Ok(postscript_name_json(None));
    }
    if let Some(instance_index) = postscript_name_named_instance_index(params, variant)? {
        let err = FT_Set_Named_Instance(Some(face), instance_index);
        if err != FT_Err_Ok {
            return Err(format!(
                "FT_Set_Named_Instance({instance_index}) returned {err}"
            ));
        }
    }
    Ok(postscript_name_json(FT_Get_Postscript_Name(face)))
}

fn c_postscript_name_variant_output(
    face: c_abi::FT_Face,
    params: &Value,
    variant: &str,
) -> Result<Value, String> {
    if variant == "null" {
        return Ok(postscript_name_json(None));
    }
    if let Some(instance_index) = postscript_name_named_instance_index(params, variant)? {
        let err = c_abi::FT_Set_Named_Instance(face, instance_index);
        if err != FT_Err_Ok {
            return Err(format!(
                "C ABI FT_Set_Named_Instance({instance_index}) returned {err}"
            ));
        }
    }
    Ok(c_postscript_name_json(c_abi::FT_Get_Postscript_Name(face)))
}

fn wasm_postscript_name_variant_output(
    handle: usize,
    params: &Value,
    variant: &str,
) -> Result<Value, String> {
    if variant == "null" {
        return Ok(postscript_name_json(None));
    }
    if let Some(instance_index) = postscript_name_named_instance_index(params, variant)? {
        let err = wasm_abi::fontdone_wasm_set_named_instance(handle, instance_index);
        if err != FT_Err_Ok {
            return Err(format!(
                "WASM ABI fontdone_wasm_set_named_instance({instance_index}) returned {err}"
            ));
        }
    }
    Ok(wasm_postscript_name_json(handle))
}

fn postscript_name_variants_output<F>(params: &Value, mut output: F) -> Result<Value, String>
where
    F: FnMut(&str) -> Result<Value, String>,
{
    let variants = postscript_name_variant_values(params)?;
    let mut results = Vec::with_capacity(variants.len());
    for variant in variants {
        results.push(json!({
            "variant": variant,
            "result": output(&variant)?
        }));
    }
    Ok(json!({ "results": results }))
}

fn rust_set_named_instance(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "face") == Some("null") {
        let err = FT_Set_Named_Instance(None, set_named_instance_index_param(&case.inputs.params)?);
        return Ok(named_instance_null_face_output(err));
    }
    let mut face = rust_new_face_without_size(case)?;
    if let Some(prior_instance) = prior_named_instance_index_param(&case.inputs.params)? {
        let err = FT_Set_Named_Instance(Some(&mut face), prior_instance);
        if err != FT_Err_Ok {
            return Ok(named_instance_run_output(
                err,
                &rust_face_info(&face),
                postscript_name_json(FT_Get_Postscript_Name(&face)),
            ));
        }
    }
    let err = FT_Set_Named_Instance(
        Some(&mut face),
        set_named_instance_index_param(&case.inputs.params)?,
    );
    if err != FT_Err_Ok {
        return Ok(named_instance_run_output(
            err,
            &rust_face_info(&face),
            postscript_name_json(FT_Get_Postscript_Name(&face)),
        ));
    }
    Ok(named_instance_run_output(
        FT_Err_Ok,
        &rust_face_info(&face),
        postscript_name_json(FT_Get_Postscript_Name(&face)),
    ))
}

fn c_set_named_instance(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "face") == Some("null") {
        let err = c_abi::FT_Set_Named_Instance(
            std::ptr::null_mut(),
            set_named_instance_index_param(&case.inputs.params)?,
        );
        return Ok(named_instance_null_face_output(err));
    }
    let (library, face) = c_new_face_without_size(case)?;
    let output = c_set_named_instance_on_face(face, &case.inputs.params);
    c_done_face(face);
    c_done_library(library);
    output
}

fn c_set_named_instance_on_face(face: c_abi::FT_Face, params: &Value) -> Result<RunOutput, String> {
    if let Some(prior_instance) = prior_named_instance_index_param(params)? {
        let err = c_abi::FT_Set_Named_Instance(face, prior_instance);
        if err != FT_Err_Ok {
            let info =
                c_abi::abi_face_info(face).ok_or_else(|| "missing c face info".to_string())?;
            return Ok(named_instance_run_output(
                err,
                &info,
                c_postscript_name_json(c_abi::FT_Get_Postscript_Name(face)),
            ));
        }
    }
    let err = c_abi::FT_Set_Named_Instance(face, set_named_instance_index_param(params)?);
    let info = c_abi::abi_face_info(face).ok_or_else(|| "missing c face info".to_string())?;
    Ok(named_instance_run_output(
        err,
        &info,
        c_postscript_name_json(c_abi::FT_Get_Postscript_Name(face)),
    ))
}

fn wasm_set_named_instance(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "face") == Some("null") {
        let err = wasm_abi::fontdone_wasm_set_named_instance(
            0,
            set_named_instance_index_param(&case.inputs.params)?,
        );
        return Ok(named_instance_null_face_output(err));
    }
    let handle = wasm_new_face_without_size(case)?;
    let output = wasm_set_named_instance_on_face(handle, &case.inputs.params);
    wasm_done_face(handle);
    output
}

fn wasm_set_named_instance_on_face(handle: usize, params: &Value) -> Result<RunOutput, String> {
    if let Some(prior_instance) = prior_named_instance_index_param(params)? {
        let err = wasm_abi::fontdone_wasm_set_named_instance(handle, prior_instance);
        if err != FT_Err_Ok {
            let info = wasm_abi::abi_face_info(handle)
                .ok_or_else(|| "missing wasm face info".to_string())?;
            return Ok(named_instance_run_output(
                err,
                &info,
                wasm_postscript_name_json(handle),
            ));
        }
    }
    let err =
        wasm_abi::fontdone_wasm_set_named_instance(handle, set_named_instance_index_param(params)?);
    let info =
        wasm_abi::abi_face_info(handle).ok_or_else(|| "missing wasm face info".to_string())?;
    Ok(named_instance_run_output(
        err,
        &info,
        wasm_postscript_name_json(handle),
    ))
}

#[derive(Debug, Clone)]
enum GlyphNameSelector {
    Index(u32),
    Name(String),
    NumGlyphs,
    NumGlyphsPlusOne,
}

fn glyph_name_selector_param(params: &Value) -> Result<GlyphNameSelector, String> {
    let raw = params
        .get("glyph_index")
        .ok_or_else(|| "missing glyph_index".to_string())?;
    if let Some(value) = raw.as_u64() {
        return u32::try_from(value)
            .map(GlyphNameSelector::Index)
            .map_err(|err| format!("glyph_index does not fit u32: {err}"));
    }
    let Some(value) = raw.as_str() else {
        return Err(format!("unsupported glyph_index {raw}"));
    };
    if value == ".notdef" || value == "glyph0" {
        return Ok(GlyphNameSelector::Index(0));
    }
    if value == "num_glyphs" || value == "face.num_glyphs" {
        return Ok(GlyphNameSelector::NumGlyphs);
    }
    if value == "num_glyphs_plus_1" || value == "face.num_glyphs_plus_1" {
        return Ok(GlyphNameSelector::NumGlyphsPlusOne);
    }
    if let Some(index) = value.strip_prefix("gid:") {
        return index
            .parse::<u32>()
            .map(GlyphNameSelector::Index)
            .map_err(|err| format!("glyph_index {value}: {err}"));
    }
    Ok(GlyphNameSelector::Name(value.to_string()))
}

fn glyph_name_selector_arg(params: &Value) -> Result<String, String> {
    match glyph_name_selector_param(params)? {
        GlyphNameSelector::Index(index) => Ok(format!("gid:{index}")),
        GlyphNameSelector::Name(name) => Ok(name),
        GlyphNameSelector::NumGlyphs => Ok("num_glyphs".to_string()),
        GlyphNameSelector::NumGlyphsPlusOne => Ok("num_glyphs_plus_1".to_string()),
    }
}

fn rust_glyph_name_index(face: &FT_Face, params: &Value) -> Result<u32, String> {
    match glyph_name_selector_param(params)? {
        GlyphNameSelector::Index(index) => Ok(index),
        GlyphNameSelector::Name(name) => Ok(FT_Get_Name_Index(Some(face), Some(&name))),
        GlyphNameSelector::NumGlyphs => u32::try_from((face).num_glyphs)
            .map_err(|err| format!("face.num_glyphs does not fit u32: {err}")),
        GlyphNameSelector::NumGlyphsPlusOne => u32::try_from((face).num_glyphs)
            .map_err(|err| format!("face.num_glyphs does not fit u32: {err}"))?
            .checked_add(1)
            .ok_or_else(|| "face.num_glyphs_plus_1 overflowed u32".to_string()),
    }
}

fn c_glyph_name_index(face: c_abi::FT_Face, params: &Value) -> Result<u32, String> {
    match glyph_name_selector_param(params)? {
        GlyphNameSelector::Index(index) => Ok(index),
        GlyphNameSelector::Name(name) => {
            let name = CString::new(name).map_err(|err| format!("glyph name: {err}"))?;
            Ok(c_abi::FT_Get_Name_Index(face, name.as_ptr()))
        }
        GlyphNameSelector::NumGlyphs => c_abi::abi_face_info(face)
            .ok_or_else(|| "missing c abi face info".to_string())
            .and_then(|info| {
                u32::try_from(info.num_glyphs)
                    .map_err(|err| format!("face.num_glyphs does not fit u32: {err}"))
            }),
        GlyphNameSelector::NumGlyphsPlusOne => c_abi::abi_face_info(face)
            .ok_or_else(|| "missing c abi face info".to_string())
            .and_then(|info| {
                u32::try_from(info.num_glyphs)
                    .map_err(|err| format!("face.num_glyphs does not fit u32: {err}"))
            })?
            .checked_add(1)
            .ok_or_else(|| "face.num_glyphs_plus_1 overflowed u32".to_string()),
    }
}

fn wasm_glyph_name_index(handle: usize, params: &Value) -> Result<u32, String> {
    match glyph_name_selector_param(params)? {
        GlyphNameSelector::Index(index) => Ok(index),
        GlyphNameSelector::Name(name) => Ok(wasm_abi::fontdone_wasm_get_name_index(
            handle,
            name.as_ptr(),
            u32::try_from(name.len()).map_err(|err| format!("glyph name length: {err}"))?,
        )),
        GlyphNameSelector::NumGlyphs => wasm_abi::abi_face_info(handle)
            .ok_or_else(|| "missing wasm abi face info".to_string())
            .and_then(|info| {
                u32::try_from(info.num_glyphs)
                    .map_err(|err| format!("face.num_glyphs does not fit u32: {err}"))
            }),
        GlyphNameSelector::NumGlyphsPlusOne => wasm_abi::abi_face_info(handle)
            .ok_or_else(|| "missing wasm abi face info".to_string())
            .and_then(|info| {
                u32::try_from(info.num_glyphs)
                    .map_err(|err| format!("face.num_glyphs does not fit u32: {err}"))
            })?
            .checked_add(1)
            .ok_or_else(|| "face.num_glyphs_plus_1 overflowed u32".to_string()),
    }
}

fn glyph_name_buffer_initial(params: &Value) -> Result<u8, String> {
    let Some(raw) = params.get("buffer_initial") else {
        return Ok(0xAA);
    };
    if let Some(value) = raw.as_u64() {
        return u8::try_from(value).map_err(|err| format!("buffer_initial: {err}"));
    }
    let Some(text) = raw.as_str() else {
        return Err(format!("unsupported buffer_initial {raw}"));
    };
    let text = text.strip_prefix("0x").unwrap_or(text);
    u8::from_str_radix(text, 16).map_err(|err| format!("buffer_initial {raw}: {err}"))
}

fn glyph_name_output(
    glyph_index: u32,
    buffer_max: u32,
    status: FT_Error,
    buffer: Option<&[u8]>,
) -> Value {
    json!({
        "glyph_index": glyph_index,
        "buffer_max": buffer_max,
        "status": status,
        "buffer_hex": buffer.map(hex_bytes)
    })
}

fn rust_get_glyph_name(case: &InputCase) -> Result<RunOutput, String> {
    let params = &case.inputs.params;
    let face_null = lifecycle_handle_param(params, "face") == Some("null");
    let buffer_null = lifecycle_handle_param(params, "buffer") == Some("null");
    let buffer_max = u32_param(params, "buffer_max")?;
    let fill = glyph_name_buffer_initial(params)?;
    let mut buffer = if buffer_null {
        None
    } else {
        Some(vec![
            fill;
            usize::try_from(buffer_max).map_err(|err| format!(
                "buffer_max does not fit usize: {err}"
            ))?
        ])
    };
    if face_null {
        return Ok(ok(glyph_name_output(
            0,
            buffer_max,
            FT_Err_Invalid_Face_Handle as FT_Error,
            buffer.as_deref(),
        )));
    }
    let face = open_face(case)?;
    let glyph_index = rust_glyph_name_index(&face, params)?;
    let status = if let Some(buffer) = buffer.as_mut() {
        match FT_Get_Glyph_Name(&face, glyph_index, buffer.as_mut_slice()) {
            Ok(_) => FT_Err_Ok,
            Err(err) => err,
        }
    } else {
        FT_Err_Invalid_Argument
    };
    Ok(ok(glyph_name_output(
        glyph_index,
        buffer_max,
        status,
        buffer.as_deref(),
    )))
}

fn c_get_glyph_name(case: &InputCase) -> Result<RunOutput, String> {
    let params = &case.inputs.params;
    let face_null = lifecycle_handle_param(params, "face") == Some("null");
    let buffer_null = lifecycle_handle_param(params, "buffer") == Some("null");
    let buffer_max = u32_param(params, "buffer_max")?;
    let fill = glyph_name_buffer_initial(params)?;
    let mut buffer = if buffer_null {
        None
    } else {
        Some(vec![
            fill;
            usize::try_from(buffer_max).map_err(|err| format!(
                "buffer_max does not fit usize: {err}"
            ))?
        ])
    };

    let (library, face) = if face_null {
        (std::ptr::null_mut(), std::ptr::null_mut())
    } else {
        c_new_face_without_size(case)?
    };
    let glyph_index = if face_null {
        0
    } else {
        c_glyph_name_index(face, params)?
    };
    let buffer_ptr = buffer
        .as_mut()
        .map_or(std::ptr::null_mut(), |bytes| bytes.as_mut_ptr().cast());
    let status = c_abi::FT_Get_Glyph_Name(face, glyph_index, buffer_ptr, buffer_max);
    c_done_face(face);
    c_done_library(library);
    Ok(ok(glyph_name_output(
        glyph_index,
        buffer_max,
        status,
        buffer.as_deref(),
    )))
}

