fn rust_library_version_output(params: &Value) -> Result<Value, String> {
    let library = if library_present_arg(params)? != 0 {
        Some(FT_Init_FreeType())
    } else {
        None
    };
    library_version_output(params, |mask, major, minor, patch| {
        FT_Library_Version(
            library.as_ref(),
            if mask & LIBRARY_VERSION_MAJOR != 0 {
                Some(major)
            } else {
                None
            },
            if mask & LIBRARY_VERSION_MINOR != 0 {
                Some(minor)
            } else {
                None
            },
            if mask & LIBRARY_VERSION_PATCH != 0 {
                Some(patch)
            } else {
                None
            },
        );
    })
}

fn c_library_version_output(params: &Value) -> Result<Value, String> {
    let mut library = std::ptr::null_mut();
    let live = library_present_arg(params)? != 0;
    if live {
        let err = c_abi::FT_Init_FreeType(&mut library);
        if err != FT_Err_Ok {
            return Err(format!("FT_Init_FreeType returned {err}"));
        }
    }
    let output = library_version_output(params, |mask, major, minor, patch| {
        c_abi::FT_Library_Version(
            library,
            if mask & LIBRARY_VERSION_MAJOR != 0 {
                major
            } else {
                std::ptr::null_mut()
            },
            if mask & LIBRARY_VERSION_MINOR != 0 {
                minor
            } else {
                std::ptr::null_mut()
            },
            if mask & LIBRARY_VERSION_PATCH != 0 {
                patch
            } else {
                std::ptr::null_mut()
            },
        );
    });
    if live {
        c_done_library(library);
    }
    output
}

fn wasm_library_version_output(params: &Value) -> Result<Value, String> {
    let live = library_present_arg(params)?;
    library_version_output(params, |mask, major, minor, patch| {
        wasm_abi::fontdone_wasm_library_version(
            live,
            if mask & LIBRARY_VERSION_MAJOR != 0 {
                major
            } else {
                std::ptr::null_mut()
            },
            if mask & LIBRARY_VERSION_MINOR != 0 {
                minor
            } else {
                std::ptr::null_mut()
            },
            if mask & LIBRARY_VERSION_PATCH != 0 {
                patch
            } else {
                std::ptr::null_mut()
            },
        );
    })
}

fn rust_truetype_engine_output(params: &Value) -> Result<Value, String> {
    let library = match truetype_engine_library_present_arg(params)? {
        0 => None,
        2 => Some(FT_New_Library_Without_Default_Modules()),
        _ => Some(FT_Init_FreeType()),
    };
    Ok(json!({
        "engine_type": FT_Get_TrueType_Engine_Type(library.as_ref()),
        "module_present": FT_Library_Has_TrueType_Module(library.as_ref()),
        "service_present": FT_Library_Has_TrueType_Engine_Service(library.as_ref())
    }))
}

fn c_truetype_engine_output(params: &Value) -> Result<Value, String> {
    let library_kind = truetype_engine_library_present_arg(params)?;
    let mut library = std::ptr::null_mut();
    if library_kind == 1 {
        let err = c_abi::FT_Init_FreeType(&mut library);
        if err != FT_Err_Ok {
            return Err(format!("FT_Init_FreeType returned {err}"));
        }
    } else if library_kind == 2 {
        library = c_abi::abi_support_new_library_without_default_modules();
    }
    let engine_type = c_abi::FT_Get_TrueType_Engine_Type(library);
    let module_present = c_abi::abi_support_library_has_truetype_module(library);
    let service_present = c_abi::abi_support_library_has_truetype_engine_service(library);
    if library_kind != 0 {
        c_done_library(library);
    }
    Ok(json!({
        "engine_type": engine_type,
        "module_present": module_present,
        "service_present": service_present
    }))
}

fn wasm_truetype_engine_output(params: &Value) -> Result<Value, String> {
    let (engine_type, module_present, service_present) =
        wasm_abi::abi_support_truetype_engine_observation(truetype_engine_library_present_arg(
            params,
        )?);
    Ok(json!({
        "engine_type": engine_type,
        "module_present": module_present,
        "service_present": service_present
    }))
}

fn debug_hook_action(case: &InputCase) -> Result<i32, String> {
    if case.case_id.contains(".stores_valid_hook") {
        Ok(1)
    } else if case.case_id.contains(".null_library_noop") {
        Ok(2)
    } else if case.case_id.contains(".invalid_index_or_null_hook_noop") {
        Ok(3)
    } else {
        Err(format!("unsupported debug hook case {}", case.case_id))
    }
}

fn debug_hook_library_present(params: &Value) -> i32 {
    if params
        .get("library")
        .and_then(Value::as_str)
        .is_some_and(|library| library == "null")
    {
        0
    } else {
        1
    }
}

fn debug_hook_class_name(class: FT_Int) -> &'static str {
    match class {
        1 => "hook_a",
        2 => "hook_b",
        3 => "other",
        _ => "null",
    }
}

fn debug_hook_snapshot_json(classes: [FT_Int; 4]) -> Value {
    json!(classes.map(debug_hook_class_name))
}

fn debug_hook_output(action: i32, before: [FT_Int; 4], after: [FT_Int; 4]) -> Value {
    match action {
        1 => json!({
            "return": "void",
            "debug_hooks_snapshot": debug_hook_snapshot_json(after),
            "stored_slot_identity": debug_hook_class_name(after[0])
        }),
        2 => json!({
            "return": "void",
            "crashed": false,
            "observable_writes": "none"
        }),
        3 => json!({
            "return": "void",
            "debug_hooks_before": debug_hook_snapshot_json(before),
            "debug_hooks_after": debug_hook_snapshot_json(after)
        }),
        _ => json!({ "return": "void" }),
    }
}

fn rust_set_debug_hook(case: &InputCase) -> Result<RunOutput, String> {
    let Ok(action) = debug_hook_action(case) else {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    };
    let mut library = if debug_hook_library_present(&case.inputs.params) != 0 {
        Some(FT_Init_FreeType())
    } else {
        None
    };
    if action == 3 {
        FT_Set_Debug_Hook(
            library.as_mut(),
            FT_DEBUG_HOOK_TRUETYPE as FT_UInt,
            Some(debug_hook_a),
        );
    }
    let before =
        FT_Library_Debug_Hook_Classes(library.as_ref(), Some(debug_hook_a), Some(debug_hook_b));
    match action {
        1 => FT_Set_Debug_Hook(
            library.as_mut(),
            FT_DEBUG_HOOK_TRUETYPE as FT_UInt,
            Some(debug_hook_a),
        ),
        3 => {
            FT_Set_Debug_Hook(library.as_mut(), 4, Some(debug_hook_b));
            FT_Set_Debug_Hook(library.as_mut(), FT_DEBUG_HOOK_TRUETYPE as FT_UInt, None);
        }
        _ => FT_Set_Debug_Hook(
            library.as_mut(),
            FT_DEBUG_HOOK_TRUETYPE as FT_UInt,
            Some(debug_hook_a),
        ),
    }
    let after =
        FT_Library_Debug_Hook_Classes(library.as_ref(), Some(debug_hook_a), Some(debug_hook_b));
    Ok(ok(debug_hook_output(action, before, after)))
}

fn c_set_debug_hook(case: &InputCase) -> Result<RunOutput, String> {
    let Ok(action) = debug_hook_action(case) else {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    };
    let mut library = std::ptr::null_mut();
    if debug_hook_library_present(&case.inputs.params) != 0 {
        let err = c_abi::FT_Init_FreeType(&mut library);
        if err != FT_Err_Ok {
            return Err(format!("FT_Init_FreeType returned {err}"));
        }
    }
    if action == 3 {
        c_abi::FT_Set_Debug_Hook(
            library,
            FT_DEBUG_HOOK_TRUETYPE as FT_UInt,
            Some(debug_hook_a),
        );
    }
    let before =
        c_abi::abi_support_debug_hook_classes(library, Some(debug_hook_a), Some(debug_hook_b));
    match action {
        1 => c_abi::FT_Set_Debug_Hook(
            library,
            FT_DEBUG_HOOK_TRUETYPE as FT_UInt,
            Some(debug_hook_a),
        ),
        3 => {
            c_abi::FT_Set_Debug_Hook(library, 4, Some(debug_hook_b));
            c_abi::FT_Set_Debug_Hook(library, FT_DEBUG_HOOK_TRUETYPE as FT_UInt, None);
        }
        _ => c_abi::FT_Set_Debug_Hook(
            library,
            FT_DEBUG_HOOK_TRUETYPE as FT_UInt,
            Some(debug_hook_a),
        ),
    }
    let after =
        c_abi::abi_support_debug_hook_classes(library, Some(debug_hook_a), Some(debug_hook_b));
    c_done_library(library);
    Ok(ok(debug_hook_output(action, before, after)))
}

fn wasm_set_debug_hook(case: &InputCase) -> Result<RunOutput, String> {
    let Ok(action) = debug_hook_action(case) else {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    };
    let (_library_present, before, after) = wasm_abi::abi_support_debug_hook_classes(
        debug_hook_library_present(&case.inputs.params),
        action,
    );
    Ok(ok(debug_hook_output(action, before, after)))
}

