fn outline_operation_output(
    case: &InputCase,
    slot_format: i32,
    outline: Option<Value>,
    bbox: JsonBBox,
    cbox: JsonBBox,
) -> Result<Value, String> {
    match case.operation.as_str() {
        "freetype.load_glyph_outline" => Ok(json!({
            "slot_format": slot_format,
            "outline": outline.unwrap_or_else(empty_outline_json),
            "cbox": bbox_json(cbox)
        })),
        "ftbbox.outline_get_bbox" => Ok(json!({
            "bbox_error": FT_Err_Ok,
            "bbox": bbox_json(bbox),
            "cbox": bbox_json(cbox)
        })),
        "ftoutln.outline_get_cbox" => Ok(json!({
            "cbox": bbox_json(cbox)
        })),
        "ftglyph.glyph_get_cbox" => Ok(json!({
            "boxes": bbox_modes_param(&case.inputs.params)?
                .into_iter()
                .map(|mode| json!({"mode": mode as u32, "bbox": bbox_json(apply_bbox_mode(cbox, mode))}))
                .collect::<Vec<_>>()
        })),
        other => Err(format!("unsupported outline operation {other}")),
    }
}

fn outline_snapshot_json(outline: &FT_OutlineSnapshot) -> Value {
    json!({
        "n_points": outline.points.len(),
        "n_contours": outline.contours.len(),
        "points": outline.points
            .iter()
            .map(|point| json!({"x": point.x, "y": point.y}))
            .collect::<Vec<_>>(),
        "tags": outline.tags,
        "contours": outline.contours,
        "flags": outline.flags
    })
}

fn empty_outline_json() -> Value {
    json!({
        "n_points": 0,
        "n_contours": 0,
        "points": [],
        "tags": [],
        "contours": [],
        "flags": 0
    })
}

fn bbox_json(bbox: JsonBBox) -> Value {
    json!({
        "xMin": bbox.x_min,
        "yMin": bbox.y_min,
        "xMax": bbox.x_max,
        "yMax": bbox.y_max
    })
}

fn apply_bbox_mode(bbox: JsonBBox, mode: i32) -> JsonBBox {
    match mode {
        1 => JsonBBox {
            x_min: pix_floor(bbox.x_min),
            y_min: pix_floor(bbox.y_min),
            x_max: pix_ceil(bbox.x_max),
            y_max: pix_ceil(bbox.y_max),
        },
        2 => JsonBBox {
            x_min: bbox.x_min >> 6,
            y_min: bbox.y_min >> 6,
            x_max: bbox.x_max >> 6,
            y_max: bbox.y_max >> 6,
        },
        3 => {
            let gridfit = apply_bbox_mode(bbox, 1);
            JsonBBox {
                x_min: gridfit.x_min >> 6,
                y_min: gridfit.y_min >> 6,
                x_max: gridfit.x_max >> 6,
                y_max: gridfit.y_max >> 6,
            }
        }
        _ => bbox,
    }
}

fn pix_floor(value: i64) -> i64 {
    value & !63
}

fn pix_ceil(value: i64) -> i64 {
    (value + 63) & !63
}

#[derive(Debug, Clone, Copy)]
struct FtsynthSlantRow {
    glyph_index: u32,
    load_flags: i32,
    xslant: i64,
    yslant: i64,
}

fn ftsynth_slant_rows_arg(params: &Value, oblique: bool) -> Result<String, String> {
    Ok(ftsynth_slant_rows(params, oblique)?
        .into_iter()
        .map(|row| {
            format!(
                "{}:{}:{}:{}",
                row.glyph_index, row.load_flags, row.xslant, row.yslant
            )
        })
        .collect::<Vec<_>>()
        .join(","))
}

fn ftsynth_slant_rows(params: &Value, oblique: bool) -> Result<Vec<FtsynthSlantRow>, String> {
    let load = params.get("load").unwrap_or(params);
    let load_flags = load_flags_param(load)?;
    let glyph_indices = if let Some(values) = load.get("glyph_indices").and_then(Value::as_array) {
        values
            .iter()
            .enumerate()
            .map(|(index, value)| u32_value(value, &format!("glyph_indices[{index}]")))
            .collect::<Result<Vec<_>, _>>()?
    } else if let Some(value) = load.get("glyph_index") {
        vec![u32_value(value, "glyph_index")?]
    } else {
        vec![glyph_index_param(load)?]
    };
    if glyph_indices.is_empty() {
        return Err("ftsynth slant rows require at least one glyph index".to_string());
    }

    let slants = if oblique {
        vec![(0x0366A, 0)]
    } else if let Some(values) = params.get("slants").and_then(Value::as_array) {
        values
            .iter()
            .enumerate()
            .map(|(index, value)| ftsynth_slant_value(value, &format!("slants[{index}]")))
            .collect::<Result<Vec<_>, _>>()?
    } else {
        vec![ftsynth_slant_value(params, "slant")?]
    };
    if slants.is_empty() {
        return Err("ftsynth slant rows require at least one slant".to_string());
    }

    let mut rows = Vec::new();
    for glyph_index in glyph_indices {
        for (xslant, yslant) in &slants {
            rows.push(FtsynthSlantRow {
                glyph_index,
                load_flags,
                xslant: *xslant,
                yslant: *yslant,
            });
        }
    }
    Ok(rows)
}

fn ftsynth_slant_value(value: &Value, label: &str) -> Result<(i64, i64), String> {
    let xslant = value
        .get("xslant_16_16")
        .map(|value| i64_value(value, &format!("{label}.xslant_16_16")))
        .transpose()?
        .unwrap_or(0);
    let yslant = value
        .get("yslant_16_16")
        .map(|value| i64_value(value, &format!("{label}.yslant_16_16")))
        .transpose()?
        .unwrap_or(0);
    Ok((xslant, yslant))
}

#[derive(Debug, Clone, Copy)]
struct FtsynthWeightRow {
    glyph_index: u32,
    load_flags: i32,
    xdelta: i64,
    ydelta: i64,
}

fn ftsynth_weight_rows_arg(params: &Value, embolden: bool) -> Result<String, String> {
    Ok(ftsynth_weight_rows(params, embolden)?
        .into_iter()
        .map(|row| {
            format!(
                "{}:{}:{}:{}",
                row.glyph_index, row.load_flags, row.xdelta, row.ydelta
            )
        })
        .collect::<Vec<_>>()
        .join(","))
}

fn ftsynth_weight_rows(params: &Value, embolden: bool) -> Result<Vec<FtsynthWeightRow>, String> {
    let load = params.get("load").unwrap_or(params);
    let load_flags = load_flags_param(load)?;
    let glyph_indices = if let Some(values) = load.get("glyph_indices").and_then(Value::as_array) {
        values
            .iter()
            .enumerate()
            .map(|(index, value)| u32_value(value, &format!("glyph_indices[{index}]")))
            .collect::<Result<Vec<_>, _>>()?
    } else if let Some(value) = load.get("glyph_index") {
        vec![u32_value(value, "glyph_index")?]
    } else {
        vec![glyph_index_param(load)?]
    };
    if glyph_indices.is_empty() {
        return Err("ftsynth weight rows require at least one glyph index".to_string());
    }

    let adjustments = if embolden {
        let strength = params
            .get("compare_with_adjust_weight_strength")
            .map(|value| i64_value(value, "compare_with_adjust_weight_strength"))
            .transpose()?
            .unwrap_or(0x0AAA);
        vec![(strength, strength)]
    } else if let Some(values) = params.get("adjustments").and_then(Value::as_array) {
        values
            .iter()
            .enumerate()
            .map(|(index, value)| ftsynth_weight_value(value, &format!("adjustments[{index}]")))
            .collect::<Result<Vec<_>, _>>()?
    } else {
        vec![ftsynth_weight_value(params, "adjustment")?]
    };
    if adjustments.is_empty() {
        return Err("ftsynth weight rows require at least one adjustment".to_string());
    }

    let mut rows = Vec::new();
    for glyph_index in glyph_indices {
        for (xdelta, ydelta) in &adjustments {
            rows.push(FtsynthWeightRow {
                glyph_index,
                load_flags,
                xdelta: *xdelta,
                ydelta: *ydelta,
            });
        }
    }
    Ok(rows)
}

fn ftsynth_weight_value(value: &Value, label: &str) -> Result<(i64, i64), String> {
    let xdelta = value
        .get("xdelta_16_16")
        .map(|value| i64_value(value, &format!("{label}.xdelta_16_16")))
        .transpose()?
        .unwrap_or(0);
    let ydelta = value
        .get("ydelta_16_16")
        .map(|value| i64_value(value, &format!("{label}.ydelta_16_16")))
        .transpose()?
        .unwrap_or(0);
    Ok((xdelta, ydelta))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FtsynthNullNoopFunction {
    AdjustWeight,
    Embolden,
    Oblique,
    Slant,
}

impl FtsynthNullNoopFunction {
    fn as_str(self) -> &'static str {
        match self {
            Self::AdjustWeight => "FT_GlyphSlot_AdjustWeight",
            Self::Embolden => "FT_GlyphSlot_Embolden",
            Self::Oblique => "FT_GlyphSlot_Oblique",
            Self::Slant => "FT_GlyphSlot_Slant",
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct FtsynthNullNoop {
    function: FtsynthNullNoopFunction,
    first: i64,
    second: i64,
}

fn ftsynth_null_noop_param(params: &Value) -> Result<FtsynthNullNoop, String> {
    let function = match string_param(params, "function")? {
        "FT_GlyphSlot_AdjustWeight" => FtsynthNullNoopFunction::AdjustWeight,
        "FT_GlyphSlot_Embolden" => FtsynthNullNoopFunction::Embolden,
        "FT_GlyphSlot_Oblique" => FtsynthNullNoopFunction::Oblique,
        "FT_GlyphSlot_Slant" => FtsynthNullNoopFunction::Slant,
        other => return Err(format!("unsupported ftsynth null no-op function {other}")),
    };
    let (first, second) = match function {
        FtsynthNullNoopFunction::AdjustWeight => ftsynth_weight_value(params, "adjustment")?,
        FtsynthNullNoopFunction::Slant => ftsynth_slant_value(params, "slant")?,
        FtsynthNullNoopFunction::Embolden | FtsynthNullNoopFunction::Oblique => (0, 0),
    };
    Ok(FtsynthNullNoop {
        function,
        first,
        second,
    })
}

fn ftsynth_null_noop_oracle_args(params: &Value) -> Result<Vec<String>, String> {
    let row = ftsynth_null_noop_param(params)?;
    Ok(vec![
        "--glyphslot-null-noop".to_string(),
        row.function.as_str().to_string(),
        row.first.to_string(),
        row.second.to_string(),
    ])
}

fn ftsynth_null_noop_output(row: FtsynthNullNoop) -> RunOutput {
    ok(json!({
        "function": row.function.as_str(),
        "slot": "null",
        "first": row.first,
        "second": row.second,
        "completed": true
    }))
}

fn rust_ftsynth_null_noop(case: &InputCase) -> Result<RunOutput, String> {
    let row = ftsynth_null_noop_param(&case.inputs.params)?;
    match row.function {
        FtsynthNullNoopFunction::AdjustWeight => {
            FT_GlyphSlot_AdjustWeight(None, row.first, row.second);
        }
        FtsynthNullNoopFunction::Embolden => FT_GlyphSlot_Embolden(None),
        FtsynthNullNoopFunction::Oblique => FT_GlyphSlot_Oblique(None),
        FtsynthNullNoopFunction::Slant => FT_GlyphSlot_Slant(None, row.first, row.second),
    }
    Ok(ftsynth_null_noop_output(row))
}

fn c_ftsynth_null_noop(case: &InputCase) -> Result<RunOutput, String> {
    let row = ftsynth_null_noop_param(&case.inputs.params)?;
    match row.function {
        FtsynthNullNoopFunction::AdjustWeight => {
            c_abi::FT_GlyphSlot_AdjustWeight(ptr::null_mut(), row.first, row.second);
        }
        FtsynthNullNoopFunction::Embolden => c_abi::FT_GlyphSlot_Embolden(ptr::null_mut()),
        FtsynthNullNoopFunction::Oblique => c_abi::FT_GlyphSlot_Oblique(ptr::null_mut()),
        FtsynthNullNoopFunction::Slant => {
            c_abi::FT_GlyphSlot_Slant(ptr::null_mut(), row.first, row.second);
        }
    }
    Ok(ftsynth_null_noop_output(row))
}

fn ftsynth_output(rows: Vec<Value>) -> RunOutput {
    ok(json!({ "rows": rows }))
}

fn ftsynth_row_json(row: FtsynthSlantRow, before: Value, after: Value) -> Value {
    json!({
        "glyph_index": row.glyph_index,
        "load_flags": row.load_flags,
        "xslant": row.xslant,
        "yslant": row.yslant,
        "slot_format": after["slot_format"].clone(),
        "outline_points_before": before["outline_points"].clone(),
        "outline_points_after": after["outline_points"].clone(),
        "outline_cbox_after": after["outline_cbox"].clone(),
        "metrics_before": before["metrics"].clone(),
        "metrics_after": after["metrics"].clone(),
        "advance_before": before["advance"].clone(),
        "advance_after": after["advance"].clone()
    })
}

fn ftsynth_weight_row_json(row: FtsynthWeightRow, before: Value, after: Value) -> Value {
    json!({
        "glyph_index": row.glyph_index,
        "load_flags": row.load_flags,
        "xdelta": row.xdelta,
        "ydelta": row.ydelta,
        "slot_format": after["slot_format"].clone(),
        "outline_points_before": before["outline_points"].clone(),
        "outline_points_after": after["outline_points"].clone(),
        "outline_cbox_after": after["outline_cbox"].clone(),
        "bitmap_before": before["bitmap"].clone(),
        "bitmap_after": after["bitmap"].clone(),
        "bitmap_top_before": before["bitmap_top"].clone(),
        "bitmap_top_after": after["bitmap_top"].clone(),
        "metrics_before": before["metrics"].clone(),
        "metrics_after": after["metrics"].clone(),
        "advance_before": before["advance"].clone(),
        "advance_after": after["advance"].clone()
    })
}

fn ftsynth_rust_slot_state(slot: &FT_GlyphSlot) -> Value {
    json!({
        "slot_format": slot.format,
        "outline_points": ftsynth_outline_points_json(slot.outline.as_ref()),
        "outline_cbox": json!({
            "xMin": slot.outline_cbox.xMin,
            "yMin": slot.outline_cbox.yMin,
            "xMax": slot.outline_cbox.xMax,
            "yMax": slot.outline_cbox.yMax
        }),
        "bitmap": ftsynth_rust_bitmap_json(slot),
        "bitmap_top": slot.bitmap.as_ref().map_or(Value::Null, |_| json!(slot.bitmap_top)),
        "metrics": glyph_metrics_fields_json(rust_metrics_fields(&slot.metrics)),
        "advance": {
            "x": slot.advance.x,
            "y": slot.advance.y
        }
    })
}

fn ftsynth_rust_bitmap_json(slot: &FT_GlyphSlot) -> Value {
    slot.bitmap.as_ref().map_or(Value::Null, |bitmap| {
        json!({
            "width": bitmap.width,
            "rows": bitmap.rows,
            "pitch": bitmap.pitch,
            "pixel_mode": bitmap.pixel_mode,
            "num_grays": bitmap.num_grays,
            "left": slot.bitmap_left,
            "top": slot.bitmap_top,
            "buffer_hex": hex_bytes(&bitmap.buffer)
        })
    })
}

fn ftsynth_outline_points_json(outline: Option<&FT_OutlineSnapshot>) -> Value {
    outline.map_or_else(
        || json!([]),
        |outline| {
            json!(
                outline
                    .points
                    .iter()
                    .map(|point| json!({"x": point.x, "y": point.y}))
                    .collect::<Vec<_>>()
            )
        },
    )
}

fn rust_ftsynth_slant(case: &InputCase, oblique: bool) -> Result<RunOutput, String> {
    let face = open_face(case)?;
    let mut rows = Vec::new();
    for row in ftsynth_slant_rows(&case.inputs.params, oblique)? {
        let mut slot = match FT_Load_Glyph(&face, row.glyph_index, row.load_flags) {
            Ok(slot) => slot,
            Err(err) => return Ok(error(err)),
        };
        let before = ftsynth_rust_slot_state(&slot);
        if oblique {
            FT_GlyphSlot_Oblique(Some(&mut slot));
        } else {
            FT_GlyphSlot_Slant(Some(&mut slot), row.xslant, row.yslant);
        }
        rows.push(ftsynth_row_json(
            row,
            before,
            ftsynth_rust_slot_state(&slot),
        ));
    }
    Ok(ftsynth_output(rows))
}

fn rust_ftsynth_weight(case: &InputCase, embolden: bool) -> Result<RunOutput, String> {
    if !has_runtime_font_source(case) {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    }
    let face = open_face(case)?;
    let mut rows = Vec::new();
    for row in ftsynth_weight_rows(&case.inputs.params, embolden)? {
        let mut slot = match FT_Load_Glyph(&face, row.glyph_index, row.load_flags) {
            Ok(slot) => slot,
            Err(err) => return Ok(error(err)),
        };
        let before = ftsynth_rust_slot_state(&slot);
        if embolden {
            FT_GlyphSlot_Embolden(Some(&mut slot));
        } else {
            FT_GlyphSlot_AdjustWeight(Some(&mut slot), row.xdelta, row.ydelta);
        }
        rows.push(ftsynth_weight_row_json(
            row,
            before,
            ftsynth_rust_slot_state(&slot),
        ));
    }
    Ok(ftsynth_output(rows))
}

fn rust_render_glyph(
    face: &FT_Face,
    glyph_input: GlyphLoadInput,
    load_flags: i32,
    render_mode: i32,
    repeat_count: u32,
) -> Result<RunOutput, String> {
    if repeat_count > 1 {
        let mut rows = Vec::new();
        for iteration in 0..repeat_count {
            let loaded = match glyph_input {
                GlyphLoadInput::CharCode(char_code) => FT_Load_Char(face, char_code, load_flags),
                GlyphLoadInput::GlyphIndex(glyph_index) => {
                    FT_Load_Glyph(face, glyph_index, load_flags)
                }
            };
            match loaded.and_then(|slot| FT_Render_Glyph(slot, render_mode)) {
                Ok(slot) => rows.push(render_glyph_sequence_row(iteration, slot_json(&slot))),
                Err(err) => return Ok(error(err)),
            }
        }
        return Ok(ok(render_glyph_sequence_json(rows)));
    }

    let loaded = match glyph_input {
        GlyphLoadInput::CharCode(char_code) => FT_Load_Char(face, char_code, load_flags),
        GlyphLoadInput::GlyphIndex(glyph_index) => FT_Load_Glyph(face, glyph_index, load_flags),
    };
    match loaded.and_then(|slot| FT_Render_Glyph(slot, render_mode)) {
        Ok(slot) => Ok(ok(slot_json(&slot))),
        Err(err) => Ok(error(err)),
    }
}

fn rust_load_char_public_api(case: &InputCase) -> Result<RunOutput, String> {
    let raw_load_flags = load_flags_param(&case.inputs.params)?;
    let char_code = u64_param(&case.inputs.params, "char_code")?;
    if lifecycle_handle_param(&case.inputs.params, "face") == Some("null") {
        return Ok(error(FT_Err_Invalid_Face_Handle as FT_Error));
    }
    let Ok(char_code) = u32::try_from(char_code) else {
        let face = open_face(case)?;
        return match FT_Load_Char(&face, char_code.into(), raw_load_flags) {
            Ok(slot) => Ok(ok(slot_json(&slot))),
            Err(err) => Ok(error(err)),
        };
    };
    let load_flags = match load_flags_to_core(raw_load_flags) {
        Ok(flags) => flags,
        Err(err) => return Ok(error(err)),
    };
    let face = open_api_face(case)?;
    let expected_autohint_bits = reset_autohint_coverage_if_requested(case)?;
    let output = match face.load_char(char_code, load_flags) {
        Ok(slot) => ok(api_slot_json(&slot)),
        Err(err) => error(font_error_to_ft(err)),
    };
    assert_autohint_coverage_bits(case, expected_autohint_bits.as_deref())?;
    Ok(output)
}

fn assert_api_load_glyph_agrees(
    case: &InputCase,
    ffi_result: Result<&FT_GlyphSlot, FT_Error>,
) -> Result<(), String> {
    if !checks_api_load_glyph_agreement(case)? {
        return Ok(());
    }
    let load_flags = match load_flags_to_core(load_flags_param(&case.inputs.params)?) {
        Ok(flags) => flags,
        Err(err) => {
            return Err(format!(
                "{} load flag conversion failed: {err}",
                case.case_id
            ));
        }
    };
    let ffi_face = open_face(case)?;
    let glyph_index = u16::try_from(rust_resolved_glyph_index(&ffi_face, &case.inputs.params)?)
        .map_err(|err| format!("{} glyph_index does not fit u16: {err}", case.case_id))?;
    let face = open_api_face(case)?;
    let expected_autohint_bits = reset_autohint_coverage_if_requested(case)?;
    let api_result = face
        .load_glyph(glyph_index, load_flags)
        .map_err(font_error_to_ft);
    assert_autohint_coverage_bits(case, expected_autohint_bits.as_deref())?;
    match (api_result, ffi_result) {
        (Ok(api_slot), Ok(ffi_slot)) => {
            let ffi_json = slot_json(ffi_slot);
            let api_json = api_slot_json(&api_slot);
            if api_json != ffi_json {
                return Err(format!(
                    "{} Face::load_glyph disagrees with FT_Load_Glyph: api={api_json} ffi={ffi_json}",
                    case.case_id
                ));
            }
        }
        (Err(api_err), Err(ffi_err)) if api_err == ffi_err => {}
        (Err(api_err), Err(ffi_err)) => {
            return Err(format!(
                "{} Face::load_glyph error disagrees with FT_Load_Glyph: api={api_err} ffi={ffi_err}",
                case.case_id
            ));
        }
        (Ok(api_slot), Err(ffi_err)) => {
            let api_json = api_slot_json(&api_slot);
            return Err(format!(
                "{} Face::load_glyph succeeded while FT_Load_Glyph returned {ffi_err}: api={api_json}",
                case.case_id
            ));
        }
        (Err(api_err), Ok(ffi_slot)) => {
            let ffi_json = slot_json(ffi_slot);
            return Err(format!(
                "{} Face::load_glyph returned {api_err} while FT_Load_Glyph succeeded: ffi={ffi_json}",
                case.case_id
            ));
        }
    }
    Ok(())
}

fn checks_api_load_glyph_agreement(case: &InputCase) -> Result<bool, String> {
    bool_param(&case.inputs.params, "assert_api_load_glyph_agrees", false)
}

fn reset_autohint_coverage_if_requested(case: &InputCase) -> Result<Option<Vec<u32>>, String> {
    let expected = autohint_coverage_bits_param(case)?;
    if expected.is_some() {
        autohint_coverage::reset();
        let mask = autohint_coverage::current_mask();
        if mask != 0 {
            return Err(format!(
                "{} autohint coverage reset left mask=0x{mask:x}",
                case.case_id
            ));
        }
    }
    Ok(expected)
}

fn assert_autohint_coverage_bits(case: &InputCase, expected: Option<&[u32]>) -> Result<(), String> {
    let Some(expected) = expected else {
        return Ok(());
    };
    let mask = autohint_coverage::current_mask();
    let actual = autohint_coverage::collect_hit_bits(mask);
    let missing = expected
        .iter()
        .copied()
        .filter(|bit| !actual.contains(bit))
        .collect::<Vec<_>>();
    autohint_coverage::reset();
    if !missing.is_empty() {
        return Err(format!(
            "{} autohint coverage bits missing: expected_include={expected:?} actual={actual:?} missing={missing:?}",
            case.case_id
        ));
    }
    Ok(())
}

fn autohint_coverage_bits_param(case: &InputCase) -> Result<Option<Vec<u32>>, String> {
    let Some(raw) = case
        .inputs
        .params
        .get("assert_autohint_coverage_bits_include")
    else {
        return Ok(None);
    };
    let values = raw.as_array().ok_or_else(|| {
        format!(
            "{} assert_autohint_coverage_bits_include must be an array",
            case.case_id
        )
    })?;
    let mut bits = Vec::with_capacity(values.len());
    for value in values {
        let bit = value.as_u64().ok_or_else(|| {
            format!(
                "{} assert_autohint_coverage_bits_include entries must be integers",
                case.case_id
            )
        })?;
        if bit >= u64::BITS.into() {
            return Err(format!(
                "{} autohint coverage bit {bit} is outside the u64 mask",
                case.case_id
            ));
        }
        bits.push(u32::try_from(bit).map_err(|err| {
            format!(
                "{} autohint coverage bit {bit} does not fit u32: {err}",
                case.case_id
            )
        })?);
    }
    Ok(Some(bits))
}

fn rust_render_glyph_public_api(case: &InputCase) -> Result<RunOutput, String> {
    let raw_load_flags = load_flags_param(&case.inputs.params)?;
    let repeat_count = render_repeat_count_param(&case.inputs.params)?;
    let capture_error_slot = bool_param(&case.inputs.params, "capture_render_error_slot", false)?;
    if capture_error_slot {
        if repeat_count != 1 || !case.expect_error {
            return Err(format!(
                "{} capture_render_error_slot requires one expected-error render",
                case.case_id
            ));
        }
        let face = open_face(case)?;
        let loaded = match glyph_load_input_param(&case.inputs.params)? {
            GlyphLoadInput::CharCode(char_code) => FT_Load_Char(&face, char_code, raw_load_flags),
            GlyphLoadInput::GlyphIndex(glyph_index) => {
                FT_Load_Glyph(&face, glyph_index, raw_load_flags)
            }
        };
        let loaded = match loaded {
            Ok(slot) => slot,
            Err(err) => return Ok(error(err)),
        };
        return match FT_Render_Glyph(loaded.clone(), render_mode_param(&case.inputs.params)?) {
            Ok(slot) => Ok(ok(slot_json(&slot))),
            Err(err) => Ok(error_with_output(err, slot_json(&loaded))),
        };
    }
    if raw_load_flags & FT_LOAD_RENDER != 0 {
        let face = open_face(case)?;
        return rust_render_glyph(
            &face,
            glyph_load_input_param(&case.inputs.params)?,
            raw_load_flags,
            render_mode_param(&case.inputs.params)?,
            repeat_count,
        );
    }
    let face = open_api_face(case)?;
    let glyph_index = match glyph_load_input_param(&case.inputs.params)? {
        GlyphLoadInput::CharCode(char_code) => {
            face.get_char_index(u32::try_from(char_code).map_err(|err| err.to_string())?)
        }
        GlyphLoadInput::GlyphIndex(glyph_index) => {
            u16::try_from(glyph_index).map_err(|err| err.to_string())?
        }
    };
    let load_flags = match load_flags_to_core(raw_load_flags) {
        Ok(flags) => flags,
        Err(err) => return Ok(error(err)),
    };
    let Some(render_mode) = render_mode_to_core(render_mode_param(&case.inputs.params)?) else {
        return Ok(error(FT_Err_Cannot_Render_Glyph));
    };
    if repeat_count > 1 {
        let mut rows = Vec::new();
        for iteration in 0..repeat_count {
            match face.render_loaded_glyph(glyph_index, load_flags, render_mode) {
                Ok(slot) => {
                    let slot_json = api_slot_json(&slot);
                    assert_font_render_mode_agrees(case, &slot_json)?;
                    rows.push(render_glyph_sequence_row(iteration, slot_json));
                }
                Err(err) => return Ok(error(font_error_to_ft(err))),
            }
        }
        return Ok(ok(render_glyph_sequence_json(rows)));
    }
    match face.render_loaded_glyph(glyph_index, load_flags, render_mode) {
        Ok(slot) => {
            let slot_json = api_slot_json(&slot);
            assert_font_render_mode_agrees(case, &slot_json)?;
            Ok(ok(slot_json))
        }
        Err(err) => Ok(error(font_error_to_ft(err))),
    }
}

fn assert_font_render_mode_agrees(case: &InputCase, slot_json: &Value) -> Result<(), String> {
    if !bool_param(&case.inputs.params, "assert_font_render_mode_agrees", false)? {
        return Ok(());
    }
    let Some(render_mode) = render_mode_to_core(render_mode_param(&case.inputs.params)?) else {
        return Ok(());
    };
    if let Some(expected) = case
        .inputs
        .params
        .get("assert_render_mode_fixture_name")
        .and_then(Value::as_str)
    {
        let actual = render_mode_fixture_name(render_mode);
        if actual != expected {
            return Err(format!(
                "{} render mode fixture name disagrees: mode={actual} expected={expected}",
                case.case_id
            ));
        }
    }
    let text = case
        .inputs
        .params
        .get("font_render_text")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            format!(
                "{} assert_font_render_mode_agrees requires font_render_text",
                case.case_id
            )
        })?;
    let data = font_bytes(case)?;
    let (_, pixel_height) = pixel_size_param(&case.inputs.params)?;
    let load_mode = font_load_mode_from_params(&case.inputs.params)?;
    let font = if bool_param(
        &case.inputs.params,
        "assert_font_truetype_constructor_agrees",
        false,
    )? {
        if load_mode != LoadMode::Default {
            return Err(format!(
                "{} assert_font_truetype_constructor_agrees requires default load mode",
                case.case_id
            ));
        }
        Font::truetype(data.as_ref(), pixel_height as f32)
    } else {
        Font::truetype_with_load_mode(data.as_ref(), pixel_height as f32, load_mode)
    }
    .map_err(|err| format!("{} Font constructor returned {err}", case.case_id))?;
    if bool_param(&case.inputs.params, "assert_font_face_count_agrees", false)? {
        let face = open_face(case)?;
        let expected = usize::try_from(face.num_faces)
            .map_err(|err| format!("{} FT_FaceRec.num_faces invalid: {err}", case.case_id))?;
        let actual = Font::face_count(data.as_ref()).map_err(|err| {
            format!(
                "{} Font::face_count returned {}",
                case.case_id,
                font_error_to_ft(err)
            )
        })?;
        if actual != expected {
            return Err(format!(
                "{} Font::face_count disagrees with FT_FaceRec.num_faces: font={actual} face={expected}",
                case.case_id
            ));
        }
    }
    if bool_param(&case.inputs.params, "assert_font_empty_text_render", false)? {
        let empty_bitmap = font.render_mode("", render_mode).map_err(|err| {
            format!(
                "{} Font::render_mode(\"\") returned {}",
                case.case_id,
                font_error_to_ft(err)
            )
        })?;
        let empty_json = rendered_bitmap_json(&empty_bitmap);
        if !is_empty_rendered_bitmap_json(&empty_json) {
            return Err(format!(
                "{} Font::render_mode(\"\") returned non-empty bitmap: {empty_json}",
                case.case_id
            ));
        }
    }
    let ch = text
        .chars()
        .next()
        .ok_or_else(|| "font_render_text must not be empty".to_string())?;
    let char_bitmap = font.render_char_mode(ch, render_mode).map_err(|err| {
        format!(
            "{} Font::render_char_mode returned {}",
            case.case_id,
            font_error_to_ft(err)
        )
    })?;
    let text_bitmap = font.render_mode(text, render_mode).map_err(|err| {
        format!(
            "{} Font::render_mode returned {}",
            case.case_id,
            font_error_to_ft(err)
        )
    })?;
    let char_json = rendered_bitmap_json(&char_bitmap);
    let text_json = rendered_bitmap_json(&text_bitmap);
    if let Some(expected) = case
        .inputs
        .params
        .get("assert_pixel_mode_fixture_name")
        .and_then(Value::as_str)
    {
        let actual = pixel_mode_fixture_name(char_bitmap.pixel_mode);
        if actual != expected {
            return Err(format!(
                "{} pixel mode fixture name disagrees: pixel={actual} expected={expected}",
                case.case_id
            ));
        }
    }
    assert_font_convenience_helpers_agree(case, &font, text, render_mode, &char_bitmap, slot_json)?;
    let Some(slot_bitmap) = slot_json.get("bitmap") else {
        return Err(format!(
            "{} slot output missing bitmap for Font render comparison",
            case.case_id
        ));
    };
    if slot_bitmap.is_null() {
        if !is_empty_rendered_bitmap_json(&char_json) {
            return Err(format!(
                "{} Font::render_char_mode returned non-empty bitmap while FT_Render_Glyph exposed no bitmap: font={char_json}",
                case.case_id
            ));
        }
        if text_json != char_json {
            return Err(format!(
                "{} Font::render_mode disagrees with Font::render_char_mode: text={text_json} char={char_json}",
                case.case_id
            ));
        }
        return Ok(());
    }
    if &char_json != slot_bitmap {
        return Err(format!(
            "{} Font::render_char_mode disagrees with FT_Render_Glyph: font={char_json} slot={slot_bitmap}",
            case.case_id
        ));
    }
    if text_json != char_json {
        return Err(format!(
            "{} Font::render_mode disagrees with Font::render_char_mode: text={text_json} char={char_json}",
            case.case_id
        ));
    }
    Ok(())
}

fn render_mode_fixture_name(mode: RenderMode) -> &'static str {
    match mode {
        RenderMode::Normal => "normal",
        RenderMode::Mono => "mono",
        RenderMode::Lcd => "lcd",
        RenderMode::LcdV => "lcd_v",
        RenderMode::Sdf => "sdf",
    }
}

fn pixel_mode_fixture_name(mode: PixelMode) -> &'static str {
    match mode {
        PixelMode::Gray => "gray",
        PixelMode::Mono => "mono",
        PixelMode::Gray2 => "gray2",
        PixelMode::Gray4 => "gray4",
        PixelMode::Lcd => "lcd",
        PixelMode::LcdV => "lcd_v",
        PixelMode::Bgra => "bgra",
    }
}

fn font_load_mode_from_params(params: &Value) -> Result<LoadMode, String> {
    let load_flags = load_flags_param(params)?;
    let no_autohint = load_flags & FT_LOAD_NO_AUTOHINT != 0;
    if load_flags & FT_LOAD_NO_HINTING != 0
        || load_flags & (FT_LOAD_NO_SCALE | FT_LOAD_NO_RECURSE) != 0
    {
        Ok(LoadMode::NoHinting)
    } else if FT_LOAD_TARGET_MODE(load_flags) == FT_RENDER_MODE_LIGHT && !no_autohint {
        Ok(LoadMode::TargetLight)
    } else if load_flags & FT_LOAD_FORCE_AUTOHINT != 0 {
        if no_autohint {
            Ok(LoadMode::NoAutoHint)
        } else {
            Ok(LoadMode::ForceAutoHint)
        }
    } else if no_autohint {
        Ok(LoadMode::NoAutoHint)
    } else {
        Ok(LoadMode::Default)
    }
}

fn assert_font_convenience_helpers_agree(
    case: &InputCase,
    font: &Font,
    text: &str,
    render_mode: RenderMode,
    rendered: &RenderedBitmap,
    slot_json: &Value,
) -> Result<(), String> {
    if bool_param(&case.inputs.params, "assert_font_getmetrics_agrees", false)? {
        let face = open_face(case)?;
        let metrics = face.size_metrics;
        let expected = (
            u32_from_positive_26dot6(metrics.ascender, "ascender")?,
            u32_from_positive_26dot6(-metrics.descender, "descender")?,
        );
        let actual = font.getmetrics();
        if actual != expected {
            return Err(format!(
                "{} Font::getmetrics disagrees with FT_Size_Metrics: font={actual:?} size_metrics={expected:?}",
                case.case_id
            ));
        }
    }

    if bool_param(&case.inputs.params, "assert_font_getlength_agrees", false)? {
        let expected_advance = slot_json
            .pointer("/metrics/horiAdvance")
            .and_then(Value::as_i64)
            .ok_or_else(|| {
                format!(
                    "{} assert_font_getlength_agrees requires slot metrics.horiAdvance",
                    case.case_id
                )
            })?;
        let actual = font.getlength(text);
        let expected = expected_advance as f32 / 64.0;
        if (actual - expected).abs() > 0.001 {
            return Err(format!(
                "{} Font::getlength disagrees with glyph-slot advance: font={actual} slot={expected}",
                case.case_id
            ));
        }
    }

    if bool_param(
        &case.inputs.params,
        "assert_font_glyph_metrics_agrees",
        false,
    )? {
        let ch = text
            .chars()
            .next()
            .ok_or_else(|| "font_render_text must not be empty".to_string())?;
        let metrics = font.glyph_metrics(ch as u32).map_err(|err| {
            format!(
                "{} Font::glyph_metrics returned {}",
                case.case_id,
                font_error_to_ft(err)
            )
        })?;
        let actual = json!({
            "width": metrics.width,
            "height": metrics.height,
            "horiBearingX": metrics.hori_bearing_x,
            "horiBearingY": metrics.hori_bearing_y,
            "horiAdvance": metrics.hori_advance,
            "vertBearingX": metrics.vert_bearing_x,
            "vertBearingY": metrics.vert_bearing_y,
            "vertAdvance": metrics.vert_advance
        });
        let expected = slot_json
            .get("metrics")
            .ok_or_else(|| format!("{} slot output missing metrics", case.case_id))?;
        if &actual != expected {
            return Err(format!(
                "{} Font::glyph_metrics disagrees with glyph-slot metrics: font={actual} slot={expected}",
                case.case_id
            ));
        }
    }

    if bool_param(&case.inputs.params, "assert_font_getmask_agrees", false)? {
        if render_mode != RenderMode::Normal {
            return Err(format!(
                "{} assert_font_getmask_agrees requires FT_RENDER_MODE_NORMAL",
                case.case_id
            ));
        }
        let bbox = font.getbbox(text);
        let mask = font.getmask(text).map_err(|err| {
            format!(
                "{} Font::getmask returned {}",
                case.case_id,
                font_error_to_ft(err)
            )
        })?;
        let expected_len = usize::try_from(mask.width)
            .ok()
            .and_then(|width| {
                usize::try_from(mask.height)
                    .ok()
                    .and_then(|height| width.checked_mul(height))
            })
            .ok_or_else(|| format!("{} Font::getmask dimensions overflow", case.case_id))?;
        if mask.pixels.len() != expected_len {
            return Err(format!(
                "{} Font::getmask pixel length disagrees with dimensions: len={} width={} height={}",
                case.case_id,
                mask.pixels.len(),
                mask.width,
                mask.height
            ));
        }
        if (mask.xmin, mask.ymin) != (bbox.0, bbox.1) {
            return Err(format!(
                "{} Font::getbbox offset disagrees with Font::getmask: bbox={bbox:?} mask=({}, {})",
                case.case_id, mask.xmin, mask.ymin
            ));
        }
        if mask.width != rendered.width
            || mask.height != rendered.rows
            || mask.pixels != rendered.buffer
        {
            return Err(format!(
                "{} Font::getmask disagrees with Font::render_mode(Normal): mask={}x{} rendered={}x{}",
                case.case_id, mask.width, mask.height, rendered.width, rendered.rows
            ));
        }
    }

    if bool_param(&case.inputs.params, "assert_font_empty_text_mask", false)? {
        let bbox = font.getbbox("");
        let mask = font.getmask("").map_err(|err| {
            format!(
                "{} Font::getmask(\"\") returned {}",
                case.case_id,
                font_error_to_ft(err)
            )
        })?;
        if bbox != (0, 0, 0, 0)
            || mask.width != 0
            || mask.height != 0
            || !mask.pixels.is_empty()
            || mask.xmin != 0
            || mask.ymin != 0
            || mask.advance_width != 0
        {
            return Err(format!(
                "{} empty Font bbox/mask was not empty: bbox={bbox:?} mask={}x{} len={}",
                case.case_id,
                mask.width,
                mask.height,
                mask.pixels.len()
            ));
        }
    }

    Ok(())
}

fn u32_from_positive_26dot6(value: i64, label: &str) -> Result<u32, String> {
    u32::try_from(value >> 6).map_err(|err| format!("{label} does not fit u32 pixels: {err}"))
}

fn is_empty_rendered_bitmap_json(value: &Value) -> bool {
    value.get("width").and_then(Value::as_u64) == Some(0)
        && value.get("rows").and_then(Value::as_u64) == Some(0)
        && value.get("pitch").and_then(Value::as_i64) == Some(0)
        && value.get("left").and_then(Value::as_i64) == Some(0)
        && value.get("top").and_then(Value::as_i64) == Some(0)
        && value.get("buffer_hex").and_then(Value::as_str) == Some("")
}

fn c_render_glyph(
    face: c_abi::FT_Face,
    glyph_input: GlyphLoadInput,
    load_flags: i32,
    render_mode: i32,
    repeat_count: u32,
    capture_error_slot: bool,
) -> Result<RunOutput, String> {
    if repeat_count > 1 {
        let mut rows = Vec::new();
        for iteration in 0..repeat_count {
            let load_err = match glyph_input {
                GlyphLoadInput::CharCode(char_code) => {
                    c_abi::FT_Load_Char(face, char_code, load_flags)
                }
                GlyphLoadInput::GlyphIndex(glyph_index) => {
                    c_abi::FT_Load_Glyph(face, glyph_index, load_flags)
                }
            };
            let err = if load_err == FT_Err_Ok {
                c_abi::abi_render_glyph_from_face(face, render_mode)
            } else {
                load_err
            };
            if err != FT_Err_Ok {
                return Ok(error(err));
            }
            rows.push(render_glyph_sequence_row(iteration, c_slot_json(face)?));
        }
        return Ok(ok(render_glyph_sequence_json(rows)));
    }

    let load_err = match glyph_input {
        GlyphLoadInput::CharCode(char_code) => c_abi::FT_Load_Char(face, char_code, load_flags),
        GlyphLoadInput::GlyphIndex(glyph_index) => {
            c_abi::FT_Load_Glyph(face, glyph_index, load_flags)
        }
    };
    let err = if load_err == FT_Err_Ok {
        c_abi::abi_render_glyph_from_face(face, render_mode)
    } else {
        load_err
    };
    if err == FT_Err_Ok {
        c_slot_json(face).map(ok)
    } else if capture_error_slot && load_err == FT_Err_Ok {
        Ok(error_with_output(err, c_slot_json(face)?))
    } else {
        Ok(error(err))
    }
}

fn wasm_render_glyph(
    handle: usize,
    glyph_input: GlyphLoadInput,
    load_flags: i32,
    render_mode: i32,
    repeat_count: u32,
    capture_error_slot: bool,
) -> Result<RunOutput, String> {
    if repeat_count > 1 {
        let mut rows = Vec::new();
        for iteration in 0..repeat_count {
            let load_err = match glyph_input {
                GlyphLoadInput::CharCode(char_code) => {
                    wasm_abi::fontdone_wasm_load_char(handle, char_code, load_flags)
                }
                GlyphLoadInput::GlyphIndex(glyph_index) => {
                    wasm_abi::fontdone_wasm_load_glyph(handle, glyph_index, load_flags)
                }
            };
            let err = if load_err == FT_Err_Ok {
                wasm_abi::fontdone_wasm_render_glyph(handle, render_mode)
            } else {
                load_err
            };
            if err != FT_Err_Ok {
                return Ok(error(err));
            }
            rows.push(render_glyph_sequence_row(
                iteration,
                wasm_slot_json(handle)?,
            ));
        }
        return Ok(ok(render_glyph_sequence_json(rows)));
    }

    let load_err = match glyph_input {
        GlyphLoadInput::CharCode(char_code) => {
            wasm_abi::fontdone_wasm_load_char(handle, char_code, load_flags)
        }
        GlyphLoadInput::GlyphIndex(glyph_index) => {
            wasm_abi::fontdone_wasm_load_glyph(handle, glyph_index, load_flags)
        }
    };
    let err = if load_err == FT_Err_Ok {
        wasm_abi::fontdone_wasm_render_glyph(handle, render_mode)
    } else {
        load_err
    };
    if err != FT_Err_Ok && capture_error_slot && load_err == FT_Err_Ok {
        Ok(error_with_output(err, wasm_slot_json(handle)?))
    } else {
        wasm_slot_output(handle, err)
    }
}

fn face_macro_flags_values(params: &Value) -> Result<Vec<i64>, String> {
    let values = params
        .get("flags")
        .or_else(|| params.get("face_flags_values"))
        .and_then(Value::as_array)
        .ok_or_else(|| "missing flags/face_flags_values array".to_string())?
        .iter()
        .map(|value| i64_value(value, "face_flags"))
        .collect::<Result<Vec<_>, String>>()?;
    if values.is_empty() {
        return Err("face_macro_flags requires at least one flag value".to_string());
    }
    let mut seen = BTreeSet::new();
    for value in &values {
        if !seen.insert(*value) {
            return Err(format!("duplicate face_flags value {value}"));
        }
    }
    Ok(values)
}

fn face_macro_flags_json(case: &InputCase) -> Result<Value, String> {
    let macro_name = face_macro_param(case)?;
    let face_index = face_index_param(&case.inputs.params)?;
    let rows = face_macro_flags_values(&case.inputs.params)?
        .into_iter()
        .map(|face_flags| {
            let info = FT_FaceRecPublic {
                face_index,
                face_flags,
                ..FT_FaceRecPublic::default()
            };
            Ok(json!({
                "face_flags": face_flags,
                "macro_result": face_macro_result(&info, macro_name)?
            }))
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok(json!({
        "macro": macro_name,
        "import_compiles": true,
        "rows": rows
    }))
}

fn rust_face_macro(face: &FT_Face, case: &InputCase) -> Result<RunOutput, String> {
    Ok(ok(face_macro_json(
        &rust_face_info(face),
        face_macro_param(case)?,
    )?))
}

fn c_face_macro(face: c_abi::FT_Face, case: &InputCase) -> Result<RunOutput, String> {
    let info = c_abi::abi_face_info(face).ok_or_else(|| "missing c face info".to_string())?;
    Ok(ok(face_macro_json(&info, face_macro_param(case)?)?))
}

fn wasm_face_macro(handle: usize, case: &InputCase) -> Result<RunOutput, String> {
    let info =
        wasm_abi::abi_face_info(handle).ok_or_else(|| "missing wasm face info".to_string())?;
    Ok(ok(face_macro_json(&info, face_macro_param(case)?)?))
}

fn rust_face_flags(face: &FT_Face, case: &InputCase) -> Result<RunOutput, String> {
    Ok(ok(face_flags_json(
        &rust_face_info(face),
        face_flag_param(case)?,
    )?))
}

fn c_face_flags(face: c_abi::FT_Face, case: &InputCase) -> Result<RunOutput, String> {
    let info = c_abi::abi_face_info(face).ok_or_else(|| "missing c face info".to_string())?;
    Ok(ok(face_flags_json(&info, face_flag_param(case)?)?))
}

fn wasm_face_flags(handle: usize, case: &InputCase) -> Result<RunOutput, String> {
    let info =
        wasm_abi::abi_face_info(handle).ok_or_else(|| "missing wasm face info".to_string())?;
    Ok(ok(face_flags_json(&info, face_flag_param(case)?)?))
}

fn rust_face_info(face: &FT_Face) -> FT_FaceRecPublic {
    FT_FaceRecPublic {
        num_faces: face.num_faces,
        face_index: face.face_index,
        face_flags: face.face_flags,
        style_flags: face.style_flags,
        num_glyphs: face.num_glyphs,
        bbox: face.bbox,
        units_per_EM: face.units_per_EM,
        ascender: face.ascender,
        descender: face.descender,
        height: face.height,
        max_advance_width: face.max_advance_width,
        max_advance_height: face.max_advance_height,
        underline_position: face.underline_position,
        underline_thickness: face.underline_thickness,
        size: face.size,
        ..FT_FaceRecPublic::default()
    }
}

fn face_flags_json(info: &FT_FaceRecPublic, flag_name: &str) -> Result<Value, String> {
    let flag = rust_constant(flag_name)?;
    Ok(json!({
        "face_flags": info.face_flags,
        "flag": flag,
        "bit_set": (info.face_flags & flag) != 0,
        "face_index": info.face_index,
        "import_compiles": true
    }))
}

fn face_macro_json(info: &FT_FaceRecPublic, macro_name: &str) -> Result<Value, String> {
    Ok(json!({
        "macro_result": face_macro_result(info, macro_name)?,
        "face_flags": info.face_flags,
        "face_index": info.face_index,
        "import_compiles": true
    }))
}

fn face_macro_result(info: &FT_FaceRecPublic, macro_name: &str) -> Result<i32, String> {
    if macro_name == "FT_HAS_FAST_GLYPHS" {
        return Ok(0);
    }
    if macro_name == "FT_IS_NAMED_INSTANCE" {
        return Ok(i32::from((info.face_index & 0x7FFF_0000) != 0));
    }
    let flag = face_macro_flag(macro_name)?;
    Ok(i32::from((info.face_flags & flag) != 0))
}

fn face_macro_flag(macro_name: &str) -> Result<i64, String> {
    match macro_name {
        "FT_HAS_COLOR" => Ok(FT_FACE_FLAG_COLOR),
        "FT_HAS_FIXED_SIZES" => Ok(FT_FACE_FLAG_FIXED_SIZES),
        "FT_HAS_GLYPH_NAMES" => Ok(FT_FACE_FLAG_GLYPH_NAMES),
        "FT_HAS_HORIZONTAL" => Ok(FT_FACE_FLAG_HORIZONTAL),
        "FT_HAS_KERNING" => Ok(FT_FACE_FLAG_KERNING),
        "FT_HAS_MULTIPLE_MASTERS" => Ok(FT_FACE_FLAG_MULTIPLE_MASTERS),
        "FT_HAS_SBIX" => Ok(FT_FACE_FLAG_SBIX),
        "FT_HAS_SBIX_OVERLAY" => Ok(FT_FACE_FLAG_SBIX_OVERLAY),
        "FT_HAS_SVG" => Ok(FT_FACE_FLAG_SVG),
        "FT_HAS_VERTICAL" => Ok(FT_FACE_FLAG_VERTICAL),
        "FT_IS_CID_KEYED" => Ok(FT_FACE_FLAG_CID_KEYED),
        "FT_IS_FIXED_WIDTH" => Ok(FT_FACE_FLAG_FIXED_WIDTH),
        "FT_IS_SCALABLE" => Ok(FT_FACE_FLAG_SCALABLE),
        "FT_IS_SFNT" => Ok(FT_FACE_FLAG_SFNT),
        "FT_IS_TRICKY" => Ok(FT_FACE_FLAG_TRICKY),
        "FT_IS_VARIATION" => Ok(FT_FACE_FLAG_VARIATION),
        _ => Err(format!("unsupported face macro {macro_name}")),
    }
}

fn is_supported_face_macro(macro_name: &str) -> bool {
    macro_name == "FT_HAS_FAST_GLYPHS"
        || macro_name == "FT_IS_NAMED_INSTANCE"
        || face_macro_flag(macro_name).is_ok()
}

fn c_new_face_without_size(
    case: &InputCase,
) -> Result<(c_abi::FT_Library, c_abi::FT_Face), String> {
    let bytes = font_bytes(case)?;
    c_new_face_from_bytes(bytes.as_ref(), face_index_param(&case.inputs.params)?)
}

fn c_new_foreign_face_without_size(
    case: &InputCase,
) -> Result<(c_abi::FT_Library, c_abi::FT_Face), String> {
    let bytes = foreign_font_bytes(case)?;
    c_new_face_from_bytes(bytes.as_ref(), 0)
}

fn c_new_face_from_bytes(
    bytes: &[u8],
    face_index: i64,
) -> Result<(c_abi::FT_Library, c_abi::FT_Face), String> {
    let mut library = std::ptr::null_mut();
    let err = c_abi::FT_Init_FreeType(&mut library);
    if err != FT_Err_Ok {
        return Err(format!("FT_Init_FreeType returned {err}"));
    }
    let mut face = std::ptr::null_mut();
    let file_size = i64::try_from(bytes.len()).map_err(|err| err.to_string())?;
    let err = c_abi::FT_New_Memory_Face(library, bytes.as_ptr(), file_size, face_index, &mut face);
    if err != FT_Err_Ok {
        c_done_library(library);
        return Err(format!("FT_New_Memory_Face returned {err}"));
    }
    Ok((library, face))
}

fn c_open_face(case: &InputCase) -> Result<(c_abi::FT_Library, c_abi::FT_Face), String> {
    c_open_face_with_size_or_char_size(case, pixel_size_param(&case.inputs.params)?)
}

fn c_open_face_with_size_or_char_size(
    case: &InputCase,
    pixel_size: (u32, u32),
) -> Result<(c_abi::FT_Library, c_abi::FT_Face), String> {
    let (library, face) = c_new_face_without_size(case)?;
    if preserve_initial_size(&case.inputs.params)? {
        return Ok((library, face));
    }
    let err = if let Some(row) = preload_size_request_row(&case.inputs.params)? {
        let request = c_size_request_rec(row);
        c_abi::FT_Request_Size(face, &request)
    } else if let Some(row) = preload_char_size_row(&case.inputs.params)? {
        c_abi::FT_Set_Char_Size(
            face,
            row.char_width,
            row.char_height,
            row.horz_resolution,
            row.vert_resolution,
        )
    } else {
        let (pixel_width, pixel_height) = pixel_size;
        c_abi::FT_Set_Pixel_Sizes(face, pixel_width, pixel_height)
    };
    if err == FT_Err_Ok {
        Ok((library, face))
    } else {
        c_done_face(face);
        c_done_library(library);
        Err(format!("FT size setup returned {err}"))
    }
}

fn c_open_face_with_size(
    case: &InputCase,
    pixel_size: (u32, u32),
) -> Result<(c_abi::FT_Library, c_abi::FT_Face), String> {
    c_open_face_with_size_or_char_size(case, pixel_size)
}

fn c_slot_json(face: c_abi::FT_Face) -> Result<Value, String> {
    let slot = c_abi::abi_slot_snapshot(face)
        .ok_or_else(|| "missing c glyph slot snapshot".to_string())?;
    let bitmap = slot.bitmap.as_ref().map_or(Value::Null, |bitmap| {
        json!({
            "width": bitmap.width,
            "rows": bitmap.rows,
            "pitch": bitmap.pitch,
            "pixel_mode": bitmap.pixel_mode,
            "num_grays": bitmap.num_grays,
            "left": bitmap.left,
            "top": bitmap.top,
            "buffer_hex": hex_bytes(&bitmap.buffer)
        })
    });
    Ok(json!({
        "glyph_index": slot.glyph_index,
        "format": slot.format,
        "advance": {"x": slot.advance.x, "y": slot.advance.y},
        "metrics": {
            "width": slot.metrics.width,
            "height": slot.metrics.height,
            "horiBearingX": slot.metrics.horiBearingX,
            "horiBearingY": slot.metrics.horiBearingY,
            "horiAdvance": slot.metrics.horiAdvance,
            "vertBearingX": slot.metrics.vertBearingX,
            "vertBearingY": slot.metrics.vertBearingY,
            "vertAdvance": slot.metrics.vertAdvance
        },
        "bitmap": bitmap
    }))
}

fn ftsynth_c_slot_state(slot: &c_abi::AbiSlotSnapshot) -> Value {
    json!({
        "slot_format": slot.format,
        "outline_points": ftsynth_outline_points_json(slot.outline.as_ref()),
        "outline_cbox": json!({
            "xMin": slot.outline_cbox.xMin,
            "yMin": slot.outline_cbox.yMin,
            "xMax": slot.outline_cbox.xMax,
            "yMax": slot.outline_cbox.yMax
        }),
        "bitmap": ftsynth_c_bitmap_json(slot),
        "bitmap_top": slot.bitmap.as_ref().map_or(Value::Null, |bitmap| json!(bitmap.top)),
        "metrics": glyph_metrics_fields_json(c_metrics_fields(&slot.metrics)),
        "advance": {
            "x": slot.advance.x,
            "y": slot.advance.y
        }
    })
}

fn ftsynth_c_bitmap_json(slot: &c_abi::AbiSlotSnapshot) -> Value {
    slot.bitmap.as_ref().map_or(Value::Null, |bitmap| {
        json!({
            "width": bitmap.width,
            "rows": bitmap.rows,
            "pitch": bitmap.pitch,
            "pixel_mode": bitmap.pixel_mode,
            "num_grays": bitmap.num_grays,
            "left": bitmap.left,
            "top": bitmap.top,
            "buffer_hex": hex_bytes(&bitmap.buffer)
        })
    })
}

fn c_ftsynth_slant(
    face: c_abi::FT_Face,
    case: &InputCase,
    oblique: bool,
) -> Result<RunOutput, String> {
    let mut rows = Vec::new();
    for row in ftsynth_slant_rows(&case.inputs.params, oblique)? {
        let err = c_abi::FT_Load_Glyph(face, row.glyph_index, row.load_flags);
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let before = c_abi::abi_slot_snapshot(face)
            .ok_or_else(|| "missing c ftsynth slot before".to_string())
            .map(|slot| ftsynth_c_slot_state(&slot))?;
        let err = if oblique {
            c_abi::abi_glyphslot_oblique_from_face(face)
        } else {
            c_abi::abi_glyphslot_slant_from_face(face, row.xslant, row.yslant)
        };
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let after = c_abi::abi_slot_snapshot(face)
            .ok_or_else(|| "missing c ftsynth slot after".to_string())
            .map(|slot| ftsynth_c_slot_state(&slot))?;
        rows.push(ftsynth_row_json(row, before, after));
    }
    Ok(ftsynth_output(rows))
}

fn c_ftsynth_weight(
    face: c_abi::FT_Face,
    case: &InputCase,
    embolden: bool,
) -> Result<RunOutput, String> {
    if !has_runtime_font_source(case) {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    }
    let mut rows = Vec::new();
    for row in ftsynth_weight_rows(&case.inputs.params, embolden)? {
        let err = c_abi::FT_Load_Glyph(face, row.glyph_index, row.load_flags);
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let before = c_abi::abi_slot_snapshot(face)
            .ok_or_else(|| "missing c ftsynth weight slot before".to_string())
            .map(|slot| ftsynth_c_slot_state(&slot))?;
        let err = if embolden {
            c_abi::abi_glyphslot_embolden_from_face(face)
        } else {
            c_abi::abi_glyphslot_adjust_weight_from_face(face, row.xdelta, row.ydelta)
        };
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let after = c_abi::abi_slot_snapshot(face)
            .ok_or_else(|| "missing c ftsynth weight slot after".to_string())
            .map(|slot| ftsynth_c_slot_state(&slot))?;
        rows.push(ftsynth_weight_row_json(row, before, after));
    }
    Ok(ftsynth_output(rows))
}

fn c_load_char_output(face: c_abi::FT_Face, params: &Value) -> Result<RunOutput, String> {
    let err = c_abi::FT_Load_Char(
        face,
        u64_param(params, "char_code")?,
        load_flags_param(params)?,
    );
    if err == FT_Err_Ok {
        c_slot_json(face).map(ok)
    } else {
        Ok(error(err))
    }
}

fn c_load_glyph_output(face: c_abi::FT_Face, params: &Value) -> Result<RunOutput, String> {
    let glyph_index = if face.is_null() {
        glyph_index_param(params)?
    } else {
        c_resolved_glyph_index(face, params)?
    };
    let err = c_abi::FT_Load_Glyph(face, glyph_index, load_flags_param(params)?);
    if err == FT_Err_Ok {
        c_slot_json(face).map(ok)
    } else {
        Ok(error(err))
    }
}

fn c_size_metrics_json(face: c_abi::FT_Face) -> Result<Value, String> {
    let metrics =
        c_abi::abi_size_metrics(face).ok_or_else(|| "missing c size metrics".to_string())?;
    Ok(json!({
        "x_ppem": metrics.x_ppem,
        "y_ppem": metrics.y_ppem,
        "x_scale": metrics.x_scale,
        "y_scale": metrics.y_scale,
        "ascender": metrics.ascender,
        "descender": metrics.descender,
        "height": metrics.height,
        "max_advance": metrics.max_advance
    }))
}

fn c_select_size(case: &InputCase) -> Result<RunOutput, String> {
    let strike_index = select_size_strike_index_param(&case.inputs.params)?;
    if lifecycle_handle_param(&case.inputs.params, "face") == Some("null") {
        return Ok(error(c_abi::FT_Select_Size(
            std::ptr::null_mut(),
            strike_index,
        )));
    }
    let (library, face) = c_open_face(case)?;
    let err = c_abi::FT_Select_Size(face, strike_index);
    let output = if err == FT_Err_Ok {
        c_size_metrics_json(face).map(ok)
    } else {
        Ok(error(err))
    };
    c_done_face(face);
    c_done_library(library);
    output
}

fn c_active_size(face: c_abi::FT_Face) -> c_abi::FT_Size {
    c_abi::abi_active_size(face).unwrap_or(std::ptr::null_mut())
}

fn c_glyph_metrics_fields_json(face: c_abi::FT_Face) -> Result<Value, String> {
    let slot = c_abi::abi_slot_snapshot(face)
        .ok_or_else(|| "missing c glyph slot snapshot".to_string())?;
    Ok(glyph_metrics_fields_json(c_metrics_fields(&slot.metrics)))
}

fn c_new_size(case: &InputCase) -> Result<RunOutput, String> {
    let mut size = std::ptr::null_mut();
    if lifecycle_handle_param(&case.inputs.params, "face") == Some("null") {
        let err = c_abi::FT_New_Size(std::ptr::null_mut(), &mut size);
        return if err == FT_Err_Ok {
            Ok(ok(json!({"size_is_null": size.is_null()})))
        } else {
            Ok(error_with_output(
                err,
                json!({"output_size_nullness": if size.is_null() { "null" } else { "non_null" }}),
            ))
        };
    }

    let (library, face) = c_new_face_without_size(case)?;
    let output_is_null = lifecycle_handle_param(&case.inputs.params, "output") == Some("null");
    let active_size_nullness_before = if c_active_size(face).is_null() {
        "null"
    } else {
        "non_null"
    };
    let err = if output_is_null {
        c_abi::FT_New_Size(face, std::ptr::null_mut())
    } else {
        c_abi::FT_New_Size(face, &mut size)
    };
    let result = if err == FT_Err_Ok {
        Ok(ok(json!({"size_is_null": size.is_null()})))
    } else {
        Ok(error_with_output(
            err,
            json!({
                "output_pointer_null": output_is_null,
                "active_size_nullness_before": active_size_nullness_before,
                "active_size_nullness_after": if c_active_size(face).is_null() { "null" } else { "non_null" }
            }),
        ))
    };
    c_done_face(face);
    c_done_library(library);
    result
}

fn c_done_size(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "size") != Some("null") {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    }
    let err = c_abi::FT_Done_Size(std::ptr::null_mut());
    if err == FT_Err_Ok {
        Ok(ok(json!({"done": true})))
    } else {
        Ok(error_with_output(err, json!({"size_input_null": true})))
    }
}

fn c_activate_size(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "size") != Some("null") {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    }
    let err = c_abi::FT_Activate_Size(std::ptr::null_mut());
    if err == FT_Err_Ok {
        Ok(ok(json!({"activated": true})))
    } else {
        Ok(error_with_output(err, json!({"size_input_null": true})))
    }
}

fn c_new_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_new_face_without_size(case)?;
    let initial = c_active_size(face);
    let mut secondary = std::ptr::null_mut();
    let new_error = c_abi::FT_New_Size(face, &mut secondary);
    let active_unchanged_until_activation = c_active_size(face) == initial;
    let parent_face = if secondary.is_null() {
        "none"
    } else {
        "same_face"
    };

    let activate_secondary_error = c_abi::FT_Activate_Size(secondary);
    let request20 = c_nominal_size_request(20 * 64);
    let request20_error = c_abi::FT_Request_Size(face, &request20);
    let secondary_metrics = if request20_error == FT_Err_Ok {
        c_size_metrics_json(face)?
    } else {
        Value::Null
    };

    let activate_initial_error = c_abi::FT_Activate_Size(initial);
    let request10 = c_nominal_size_request(10 * 64);
    let request10_error = c_abi::FT_Request_Size(face, &request10);
    let initial_metrics = if request10_error == FT_Err_Ok {
        c_size_metrics_json(face)?
    } else {
        Value::Null
    };

    let errors = [
        new_error,
        activate_secondary_error,
        request20_error,
        activate_initial_error,
        request10_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "new_size_nullness": if secondary.is_null() { "null" } else { "non_null" },
        "new_size_parent_face": parent_face,
        "active_size_unchanged_until_activation": active_unchanged_until_activation,
        "metrics_by_size": {
            "initial_size": initial_metrics,
            "secondary_size": secondary_metrics
        }
    });
    c_done_face(face);
    c_done_library(library);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn c_done_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_new_face_without_size(case)?;
    let initial = c_active_size(face);
    let mut secondary = std::ptr::null_mut();
    let remove_active = bool_param(&case.inputs.params, "remove_active", true)?;
    let new_error = c_abi::FT_New_Size(face, &mut secondary);
    let active_before_done = if remove_active { secondary } else { initial };
    let activate_error = c_abi::FT_Activate_Size(active_before_done);
    let set18_error = c_abi::FT_Set_Pixel_Sizes(face, 0, 18);
    let done_error = c_abi::FT_Done_Size(secondary);
    let active_after_done = c_active_size(face);
    let set12_error = c_abi::FT_Set_Pixel_Sizes(face, 0, 12);
    let load_error = c_abi::FT_Load_Glyph(face, 36, FT_LOAD_DEFAULT);
    let glyph_metrics = if load_error == FT_Err_Ok {
        c_glyph_metrics_fields_json(face)?
    } else {
        Value::Null
    };

    let errors = [
        new_error,
        activate_error,
        set18_error,
        done_error,
        set12_error,
        load_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "destroyed_size_removed": active_after_done != secondary,
        "active_size_after_done": size_identity_label(active_after_done, initial, secondary),
        "post_done_face_usable": set12_error == FT_Err_Ok && load_error == FT_Err_Ok,
        "post_done_glyph_metrics": glyph_metrics
    });
    c_done_face(face);
    c_done_library(library);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn c_activate_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_new_face_without_size(case)?;
    let initial = c_active_size(face);
    let set12_error = c_abi::FT_Set_Pixel_Sizes(face, 0, 12);
    let initial_metrics = if set12_error == FT_Err_Ok {
        c_size_metrics_json(face)?
    } else {
        Value::Null
    };

    let mut secondary = std::ptr::null_mut();
    let new_error = c_abi::FT_New_Size(face, &mut secondary);
    let activate_secondary_error = c_abi::FT_Activate_Size(secondary);
    let after_secondary_activation = size_identity_label(c_active_size(face), initial, secondary);
    let request18 = c_nominal_size_request(18 * 64);
    let request18_error = c_abi::FT_Request_Size(face, &request18);
    let secondary_metrics = if request18_error == FT_Err_Ok {
        c_size_metrics_json(face)?
    } else {
        Value::Null
    };
    let load_secondary_error = c_abi::FT_Load_Glyph(face, 36, FT_LOAD_DEFAULT);
    let secondary_glyph_metrics = if load_secondary_error == FT_Err_Ok {
        c_glyph_metrics_fields_json(face)?
    } else {
        Value::Null
    };

    let activate_initial_error = c_abi::FT_Activate_Size(initial);
    let after_initial_activation = size_identity_label(c_active_size(face), initial, secondary);
    let load_initial_error = c_abi::FT_Load_Glyph(face, 36, FT_LOAD_DEFAULT);
    let initial_glyph_metrics = if load_initial_error == FT_Err_Ok {
        c_glyph_metrics_fields_json(face)?
    } else {
        Value::Null
    };

    let errors = [
        set12_error,
        new_error,
        activate_secondary_error,
        request18_error,
        load_secondary_error,
        activate_initial_error,
        load_initial_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "active_size_identity": {
            "after_secondary_activation": after_secondary_activation,
            "after_initial_activation": after_initial_activation
        },
        "metrics_by_size": {
            "initial_size": initial_metrics,
            "secondary_size": secondary_metrics
        },
        "glyph_metrics_by_active_size": [secondary_glyph_metrics, initial_glyph_metrics]
    });
    c_done_face(face);
    c_done_library(library);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn c_activate_select_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_new_face_without_size(case)?;
    let initial = c_active_size(face);
    let set_initial_error = c_abi::FT_Set_Pixel_Sizes(face, 0, 12);
    let mut secondary = std::ptr::null_mut();
    let new_error = c_abi::FT_New_Size(face, &mut secondary);
    let activate_secondary_error = c_abi::FT_Activate_Size(secondary);
    let after_secondary_activation = size_identity_label(c_active_size(face), initial, secondary);
    let select_error =
        c_abi::FT_Select_Size(face, select_size_strike_index_param(&case.inputs.params)?);
    let selected_metrics = if select_error == FT_Err_Ok {
        c_size_metrics_json(face)?
    } else {
        Value::Null
    };
    let activate_initial_error = c_abi::FT_Activate_Size(initial);
    let after_initial_activation = size_identity_label(c_active_size(face), initial, secondary);
    let inactive_metrics = if activate_initial_error == FT_Err_Ok {
        c_size_metrics_json(face)?
    } else {
        Value::Null
    };

    let errors = [
        set_initial_error,
        new_error,
        activate_secondary_error,
        select_error,
        activate_initial_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "active_size_identity": {
            "after_secondary_activation": after_secondary_activation,
            "after_initial_activation": after_initial_activation
        },
        "selected_strike_metrics": selected_metrics,
        "inactive_size_metrics": inactive_metrics
    });
    c_done_face(face);
    c_done_library(library);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn c_done_face(face: c_abi::FT_Face) {
    if !face.is_null() {
        let _ = c_abi::FT_Done_Face(face);
    }
}

fn c_done_library(library: c_abi::FT_Library) {
    if !library.is_null() {
        let _ = c_abi::FT_Done_FreeType(library);
    }
}

fn wasm_new_face_without_size(case: &InputCase) -> Result<usize, String> {
    let bytes = font_bytes(case)?;
    wasm_new_face_from_bytes(bytes.as_ref(), face_index_param(&case.inputs.params)?)
}

fn wasm_new_foreign_face_without_size(case: &InputCase) -> Result<usize, String> {
    let bytes = foreign_font_bytes(case)?;
    wasm_new_face_from_bytes(bytes.as_ref(), 0)
}

fn wasm_new_face_from_bytes(bytes: &[u8], face_index: i64) -> Result<usize, String> {
    let status = wasm_abi::fontdone_wasm_open_face(bytes.as_ptr(), bytes.len(), face_index, 20.0);
    if status.error == FT_Err_Ok {
        Ok(status.handle)
    } else {
        Err(format!("fontdone_wasm_open_face returned {}", status.error))
    }
}

fn wasm_open_face(case: &InputCase) -> Result<usize, String> {
    wasm_open_face_with_size_or_char_size(case, pixel_size_param(&case.inputs.params)?)
}

fn wasm_open_face_with_size_or_char_size(
    case: &InputCase,
    pixel_size: (u32, u32),
) -> Result<usize, String> {
    let bytes = font_bytes(case)?;
    let status = wasm_abi::fontdone_wasm_open_face(
        bytes.as_ptr(),
        bytes.len(),
        face_index_param(&case.inputs.params)?,
        20.0,
    );
    if status.error != FT_Err_Ok {
        return Err(format!("fontdone_wasm_open_face returned {}", status.error));
    }
    if preserve_initial_size(&case.inputs.params)? {
        return Ok(status.handle);
    }
    let err = if let Some(row) = preload_size_request_row(&case.inputs.params)? {
        let request = wasm_size_request_rec(row);
        wasm_abi::fontdone_wasm_request_size(status.handle, &request)
    } else if let Some(row) = preload_char_size_row(&case.inputs.params)? {
        wasm_abi::fontdone_wasm_set_char_size(
            status.handle,
            row.char_width,
            row.char_height,
            row.horz_resolution,
            row.vert_resolution,
        )
    } else {
        let (pixel_width, pixel_height) = pixel_size;
        wasm_abi::fontdone_wasm_set_pixel_sizes(status.handle, pixel_width, pixel_height)
    };
    if err == FT_Err_Ok {
        Ok(status.handle)
    } else {
        wasm_done_face(status.handle);
        Err(format!("fontdone_wasm size setup returned {err}"))
    }
}

fn wasm_open_face_with_size(case: &InputCase, pixel_size: (u32, u32)) -> Result<usize, String> {
    wasm_open_face_with_size_or_char_size(case, pixel_size)
}

fn wasm_new_memory_face(case: &InputCase) -> Result<RunOutput, String> {
    if case.inputs.params.get("variants").is_some() {
        return wasm_new_memory_face_variants(case);
    }
    if lifecycle_handle_param(&case.inputs.params, "file_base") == Some("null") {
        let file_size = usize::try_from(i64_param(&case.inputs.params, "file_size")?)
            .map_err(|err| err.to_string())?;
        let status = wasm_abi::fontdone_wasm_open_face(
            ptr::null(),
            file_size,
            face_index_param(&case.inputs.params)?,
            20.0,
        );
        return if status.error == FT_Err_Ok {
            wasm_done_face(status.handle);
            Ok(ok(json!({"opened": true})))
        } else {
            Ok(error(status.error))
        };
    }
    let bytes = font_bytes(case)?;
    let status = wasm_abi::fontdone_wasm_open_face(
        bytes.as_ptr(),
        bytes.len(),
        face_index_param(&case.inputs.params)?,
        20.0,
    );
    if status.error == FT_Err_Ok {
        wasm_done_face(status.handle);
        Ok(ok(json!({"opened": true})))
    } else {
        Ok(error(status.error))
    }
}

fn wasm_size_metrics_value(handle: usize) -> Result<Value, String> {
    let mut metrics = wasm_abi::FontdoneWasmSizeMetrics::default();
    let err = wasm_abi::fontdone_wasm_size_metrics(handle, &mut metrics);
    if err == FT_Err_Ok {
        Ok(wasm_size_metrics_json(&metrics))
    } else {
        Err(format!("fontdone_wasm_size_metrics returned {err}"))
    }
}

fn wasm_select_size(case: &InputCase) -> Result<RunOutput, String> {
    let strike_index = select_size_strike_index_param(&case.inputs.params)?;
    if lifecycle_handle_param(&case.inputs.params, "face") == Some("null") {
        return Ok(error(wasm_abi::fontdone_wasm_select_size(0, strike_index)));
    }
    let handle = wasm_open_face(case)?;
    let err = wasm_abi::fontdone_wasm_select_size(handle, strike_index);
    let output = if err == FT_Err_Ok {
        wasm_size_metrics_value(handle).map(ok)
    } else {
        Ok(error(err))
    };
    wasm_done_face(handle);
    output
}

fn wasm_glyph_metrics_fields_json(handle: usize) -> Result<Value, String> {
    let slot = wasm_abi::abi_slot_snapshot(handle)
        .ok_or_else(|| "missing wasm glyph slot snapshot".to_string())?;
    Ok(glyph_metrics_fields_json(wasm_metrics_fields(
        &slot.metrics,
    )))
}

fn wasm_new_size(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "face") == Some("null") {
        let mut size = 0usize;
        let err = wasm_abi::fontdone_wasm_new_size_out(0, &mut size);
        return if err == FT_Err_Ok {
            Ok(ok(json!({"size_is_null": size == 0})))
        } else {
            Ok(error_with_output(
                err,
                json!({"output_size_nullness": if size == 0 { "null" } else { "non_null" }}),
            ))
        };
    }

    let handle = wasm_new_face_without_size(case)?;
    let mut size = 0usize;
    let output_is_null = lifecycle_handle_param(&case.inputs.params, "output") == Some("null");
    let active_size_nullness_before = if wasm_abi::fontdone_wasm_active_size(handle) == 0 {
        "null"
    } else {
        "non_null"
    };
    let err = if output_is_null {
        wasm_abi::fontdone_wasm_new_size_out(handle, std::ptr::null_mut())
    } else {
        wasm_abi::fontdone_wasm_new_size_out(handle, &mut size)
    };
    let result = if err == FT_Err_Ok {
        Ok(ok(json!({"size_is_null": size == 0})))
    } else {
        Ok(error_with_output(
            err,
            json!({
                "output_pointer_null": output_is_null,
                "active_size_nullness_before": active_size_nullness_before,
                "active_size_nullness_after": if wasm_abi::fontdone_wasm_active_size(handle) == 0 { "null" } else { "non_null" }
            }),
        ))
    };
    wasm_done_face(handle);
    result
}

fn wasm_done_size(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "size") != Some("null") {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    }
    let err = wasm_abi::fontdone_wasm_done_size(0);
    if err == FT_Err_Ok {
        Ok(ok(json!({"done": true})))
    } else {
        Ok(error_with_output(err, json!({"size_input_null": true})))
    }
}

fn wasm_activate_size(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "size") != Some("null") {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    }
    let err = wasm_abi::fontdone_wasm_activate_size(0);
    if err == FT_Err_Ok {
        Ok(ok(json!({"activated": true})))
    } else {
        Ok(error_with_output(err, json!({"size_input_null": true})))
    }
}

fn wasm_new_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let handle = wasm_new_face_without_size(case)?;
    let initial = wasm_abi::fontdone_wasm_active_size(handle);
    let status = wasm_abi::fontdone_wasm_new_size(handle);
    let secondary = status.handle;
    let new_error = status.error;
    let active_unchanged_until_activation = wasm_abi::fontdone_wasm_active_size(handle) == initial;
    let parent_face = if secondary == 0 { "none" } else { "same_face" };

    let activate_secondary_error = wasm_abi::fontdone_wasm_activate_size(secondary);
    let request20 = wasm_nominal_size_request(20 * 64);
    let request20_error = wasm_abi::fontdone_wasm_request_size(handle, &request20);
    let secondary_metrics = if request20_error == FT_Err_Ok {
        wasm_size_metrics_value(handle)?
    } else {
        Value::Null
    };

    let activate_initial_error = wasm_abi::fontdone_wasm_activate_size(initial);
    let request10 = wasm_nominal_size_request(10 * 64);
    let request10_error = wasm_abi::fontdone_wasm_request_size(handle, &request10);
    let initial_metrics = if request10_error == FT_Err_Ok {
        wasm_size_metrics_value(handle)?
    } else {
        Value::Null
    };

    let errors = [
        new_error,
        activate_secondary_error,
        request20_error,
        activate_initial_error,
        request10_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "new_size_nullness": if secondary == 0 { "null" } else { "non_null" },
        "new_size_parent_face": parent_face,
        "active_size_unchanged_until_activation": active_unchanged_until_activation,
        "metrics_by_size": {
            "initial_size": initial_metrics,
            "secondary_size": secondary_metrics
        }
    });
    wasm_done_face(handle);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn wasm_done_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let handle = wasm_new_face_without_size(case)?;
    let initial = wasm_abi::fontdone_wasm_active_size(handle);
    let status = wasm_abi::fontdone_wasm_new_size(handle);
    let secondary = status.handle;
    let remove_active = bool_param(&case.inputs.params, "remove_active", true)?;
    let new_error = status.error;
    let active_before_done = if remove_active { secondary } else { initial };
    let activate_error = wasm_abi::fontdone_wasm_activate_size(active_before_done);
    let set18_error = wasm_abi::fontdone_wasm_set_pixel_sizes(handle, 0, 18);
    let done_error = wasm_abi::fontdone_wasm_done_size(secondary);
    let active_after_done = wasm_abi::fontdone_wasm_active_size(handle);
    let set12_error = wasm_abi::fontdone_wasm_set_pixel_sizes(handle, 0, 12);
    let load_error = wasm_abi::fontdone_wasm_load_glyph(handle, 36, FT_LOAD_DEFAULT);
    let glyph_metrics = if load_error == FT_Err_Ok {
        wasm_glyph_metrics_fields_json(handle)?
    } else {
        Value::Null
    };

    let errors = [
        new_error,
        activate_error,
        set18_error,
        done_error,
        set12_error,
        load_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "destroyed_size_removed": active_after_done != secondary,
        "active_size_after_done": size_identity_label_usize(active_after_done, initial, secondary),
        "post_done_face_usable": set12_error == FT_Err_Ok && load_error == FT_Err_Ok,
        "post_done_glyph_metrics": glyph_metrics
    });
    wasm_done_face(handle);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn wasm_activate_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let handle = wasm_new_face_without_size(case)?;
    let initial = wasm_abi::fontdone_wasm_active_size(handle);
    let set12_error = wasm_abi::fontdone_wasm_set_pixel_sizes(handle, 0, 12);
    let initial_metrics = if set12_error == FT_Err_Ok {
        wasm_size_metrics_value(handle)?
    } else {
        Value::Null
    };

    let status = wasm_abi::fontdone_wasm_new_size(handle);
    let secondary = status.handle;
    let new_error = status.error;
    let activate_secondary_error = wasm_abi::fontdone_wasm_activate_size(secondary);
    let after_secondary_activation = size_identity_label_usize(
        wasm_abi::fontdone_wasm_active_size(handle),
        initial,
        secondary,
    );
    let request18 = wasm_nominal_size_request(18 * 64);
    let request18_error = wasm_abi::fontdone_wasm_request_size(handle, &request18);
    let secondary_metrics = if request18_error == FT_Err_Ok {
        wasm_size_metrics_value(handle)?
    } else {
        Value::Null
    };
    let load_secondary_error = wasm_abi::fontdone_wasm_load_glyph(handle, 36, FT_LOAD_DEFAULT);
    let secondary_glyph_metrics = if load_secondary_error == FT_Err_Ok {
        wasm_glyph_metrics_fields_json(handle)?
    } else {
        Value::Null
    };

    let activate_initial_error = wasm_abi::fontdone_wasm_activate_size(initial);
    let after_initial_activation = size_identity_label_usize(
        wasm_abi::fontdone_wasm_active_size(handle),
        initial,
        secondary,
    );
    let load_initial_error = wasm_abi::fontdone_wasm_load_glyph(handle, 36, FT_LOAD_DEFAULT);
    let initial_glyph_metrics = if load_initial_error == FT_Err_Ok {
        wasm_glyph_metrics_fields_json(handle)?
    } else {
        Value::Null
    };

    let errors = [
        set12_error,
        new_error,
        activate_secondary_error,
        request18_error,
        load_secondary_error,
        activate_initial_error,
        load_initial_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "active_size_identity": {
            "after_secondary_activation": after_secondary_activation,
            "after_initial_activation": after_initial_activation
        },
        "metrics_by_size": {
            "initial_size": initial_metrics,
            "secondary_size": secondary_metrics
        },
        "glyph_metrics_by_active_size": [secondary_glyph_metrics, initial_glyph_metrics]
    });
    wasm_done_face(handle);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn wasm_activate_select_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let handle = wasm_new_face_without_size(case)?;
    let initial = wasm_abi::fontdone_wasm_active_size(handle);
    let set_initial_error = wasm_abi::fontdone_wasm_set_pixel_sizes(handle, 0, 12);
    let status = wasm_abi::fontdone_wasm_new_size(handle);
    let secondary = status.handle;
    let new_error = status.error;
    let activate_secondary_error = wasm_abi::fontdone_wasm_activate_size(secondary);
    let after_secondary_activation = size_identity_label_usize(
        wasm_abi::fontdone_wasm_active_size(handle),
        initial,
        secondary,
    );
    let select_error = wasm_abi::fontdone_wasm_select_size(
        handle,
        select_size_strike_index_param(&case.inputs.params)?,
    );
    let selected_metrics = if select_error == FT_Err_Ok {
        wasm_size_metrics_value(handle)?
    } else {
        Value::Null
    };
    let activate_initial_error = wasm_abi::fontdone_wasm_activate_size(initial);
    let after_initial_activation = size_identity_label_usize(
        wasm_abi::fontdone_wasm_active_size(handle),
        initial,
        secondary,
    );
    let inactive_metrics = if activate_initial_error == FT_Err_Ok {
        wasm_size_metrics_value(handle)?
    } else {
        Value::Null
    };

    let errors = [
        set_initial_error,
        new_error,
        activate_secondary_error,
        select_error,
        activate_initial_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "active_size_identity": {
            "after_secondary_activation": after_secondary_activation,
            "after_initial_activation": after_initial_activation
        },
        "selected_strike_metrics": selected_metrics,
        "inactive_size_metrics": inactive_metrics
    });
    wasm_done_face(handle);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn wasm_slot_output(handle: usize, err: i32) -> Result<RunOutput, String> {
    if err != FT_Err_Ok {
        return Ok(error(err));
    }
    Ok(ok(wasm_slot_json(handle)?))
}

fn wasm_load_char_output(handle: usize, params: &Value) -> Result<RunOutput, String> {
    let err = wasm_abi::fontdone_wasm_load_char(
        handle,
        u64_param(params, "char_code")?,
        load_flags_param(params)?,
    );
    wasm_slot_output(handle, err)
}

fn wasm_load_glyph_output(handle: usize, params: &Value) -> Result<RunOutput, String> {
    let glyph_index = if handle == 0 {
        glyph_index_param(params)?
    } else {
        wasm_resolved_glyph_index(handle, params)?
    };
    let err = wasm_abi::fontdone_wasm_load_glyph(handle, glyph_index, load_flags_param(params)?);
    wasm_slot_output(handle, err)
}

fn wasm_slot_json(handle: usize) -> Result<Value, String> {
    let slot = wasm_abi::abi_slot_snapshot(handle)
        .ok_or_else(|| "missing wasm glyph slot snapshot".to_string())?;
    let bitmap = slot.bitmap.as_ref().map_or(Value::Null, |bitmap| {
        json!({
            "width": bitmap.width,
            "rows": bitmap.rows,
            "pitch": bitmap.pitch,
            "pixel_mode": bitmap.pixel_mode,
            "num_grays": bitmap.num_grays,
            "left": bitmap.left,
            "top": bitmap.top,
            "buffer_hex": hex_bytes(&bitmap.buffer)
        })
    });
    Ok(json!({
        "glyph_index": slot.glyph_index,
        "format": slot.format,
        "advance": {"x": slot.advance.x, "y": slot.advance.y},
        "metrics": {
            "width": slot.metrics.width,
            "height": slot.metrics.height,
            "horiBearingX": slot.metrics.horiBearingX,
            "horiBearingY": slot.metrics.horiBearingY,
            "horiAdvance": slot.metrics.horiAdvance,
            "vertBearingX": slot.metrics.vertBearingX,
            "vertBearingY": slot.metrics.vertBearingY,
            "vertAdvance": slot.metrics.vertAdvance
        },
        "bitmap": bitmap
    }))
}

fn ftsynth_wasm_slot_state(slot: &wasm_abi::AbiSlotSnapshot) -> Value {
    json!({
        "slot_format": slot.format,
        "outline_points": ftsynth_outline_points_json(slot.outline.as_ref()),
        "outline_cbox": json!({
            "xMin": slot.outline_cbox.xMin,
            "yMin": slot.outline_cbox.yMin,
            "xMax": slot.outline_cbox.xMax,
            "yMax": slot.outline_cbox.yMax
        }),
        "bitmap": ftsynth_wasm_bitmap_json(slot),
        "bitmap_top": slot.bitmap.as_ref().map_or(Value::Null, |bitmap| json!(bitmap.top)),
        "metrics": glyph_metrics_fields_json(wasm_metrics_fields(&slot.metrics)),
        "advance": {
            "x": slot.advance.x,
            "y": slot.advance.y
        }
    })
}

fn ftsynth_wasm_bitmap_json(slot: &wasm_abi::AbiSlotSnapshot) -> Value {
    slot.bitmap.as_ref().map_or(Value::Null, |bitmap| {
        json!({
            "width": bitmap.width,
            "rows": bitmap.rows,
            "pitch": bitmap.pitch,
            "pixel_mode": bitmap.pixel_mode,
            "num_grays": bitmap.num_grays,
            "left": bitmap.left,
            "top": bitmap.top,
            "buffer_hex": hex_bytes(&bitmap.buffer)
        })
    })
}

fn wasm_ftsynth_slant(handle: usize, case: &InputCase, oblique: bool) -> Result<RunOutput, String> {
    let mut rows = Vec::new();
    for row in ftsynth_slant_rows(&case.inputs.params, oblique)? {
        let err = wasm_abi::fontdone_wasm_load_glyph(handle, row.glyph_index, row.load_flags);
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let before = wasm_abi::abi_slot_snapshot(handle)
            .ok_or_else(|| "missing wasm ftsynth slot before".to_string())
            .map(|slot| ftsynth_wasm_slot_state(&slot))?;
        let err = if oblique {
            wasm_abi::fontdone_wasm_glyphslot_oblique(handle)
        } else {
            wasm_abi::fontdone_wasm_glyphslot_slant(handle, row.xslant, row.yslant)
        };
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let after = wasm_abi::abi_slot_snapshot(handle)
            .ok_or_else(|| "missing wasm ftsynth slot after".to_string())
            .map(|slot| ftsynth_wasm_slot_state(&slot))?;
        rows.push(ftsynth_row_json(row, before, after));
    }
    Ok(ftsynth_output(rows))
}

fn wasm_ftsynth_weight(
    handle: usize,
    case: &InputCase,
    embolden: bool,
) -> Result<RunOutput, String> {
    if !has_runtime_font_source(case) {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    }
    let mut rows = Vec::new();
    for row in ftsynth_weight_rows(&case.inputs.params, embolden)? {
        let err = wasm_abi::fontdone_wasm_load_glyph(handle, row.glyph_index, row.load_flags);
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let before = wasm_abi::abi_slot_snapshot(handle)
            .ok_or_else(|| "missing wasm ftsynth weight slot before".to_string())
            .map(|slot| ftsynth_wasm_slot_state(&slot))?;
        let err = if embolden {
            wasm_abi::fontdone_wasm_glyphslot_embolden(handle)
        } else {
            wasm_abi::fontdone_wasm_glyphslot_adjust_weight(handle, row.xdelta, row.ydelta)
        };
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let after = wasm_abi::abi_slot_snapshot(handle)
            .ok_or_else(|| "missing wasm ftsynth weight slot after".to_string())
            .map(|slot| ftsynth_wasm_slot_state(&slot))?;
        rows.push(ftsynth_weight_row_json(row, before, after));
    }
    Ok(ftsynth_output(rows))
}

fn wasm_done_face(handle: usize) {
    if handle != 0 {
        let _ = wasm_abi::fontdone_wasm_done_face(handle);
    }
}

fn rust_new_memory_face(case: &InputCase) -> Result<RunOutput, String> {
    if case.inputs.params.get("variants").is_some() {
        return rust_new_memory_face_variants(case);
    }
    if lifecycle_handle_param(&case.inputs.params, "file_base") == Some("null") {
        // C `FT_New_Memory_Face` rejects a null file_base before parsing data.
        // The safe Rust core receives slices, so this row validates wrapper input policy.
        return Ok(error(FT_Err_Invalid_Argument));
    }
    let data = font_bytes(case)?;
    let library = FT_Init_FreeType();
    match FT_New_Memory_Face(
        &library,
        data.as_ref(),
        face_index_param(&case.inputs.params)?,
        20.0,
    ) {
        Ok(mut face) => {
            if is_face_probe(case)? {
                return Ok(ok(json!({"opened": true})));
            }
            let (pixel_width, pixel_height) = pixel_size_param(&case.inputs.params)?;
            let err = FT_Set_Pixel_Sizes(&mut face, pixel_width, pixel_height);
            if err == FT_Err_Ok {
                Ok(ok(json!({"opened": true})))
            } else {
                Ok(error(err))
            }
        }
        Err(err) => Ok(error(err)),
    }
}

fn rust_new_memory_face_variants(case: &InputCase) -> Result<RunOutput, String> {
    let data = font_bytes(case)?;
    let library = FT_Init_FreeType();
    let rows = memory_face_rows(&case.inputs.params)?;
    memory_face_outputs(rows, |row| {
        if row.library_is_null {
            return Ok((FT_Err_Invalid_Library_Handle as FT_Error, true));
        }
        if row.open_args_is_null {
            return Ok((FT_Err_Invalid_Argument, true));
        }
        if row.aface_is_null {
            return Ok((FT_Err_Invalid_Argument, true));
        }
        if case.subject == "freetype.FT_Open_Face" {
            let source_flags =
                row.open_flags & (FT_OPEN_MEMORY | FT_OPEN_STREAM | FT_OPEN_PATHNAME);
            if source_flags != FT_OPEN_MEMORY {
                // C `FT_Open_Face` rejects calls unless exactly one source flag
                // is selected before any driver probing (ftobjs.c:2524-2547).
                return Ok((FT_Err_Invalid_Argument, true));
            }
        }
        let Some(bytes) = memory_face_row_bytes(data.as_ref(), row)? else {
            return Ok((FT_Err_Invalid_Argument, true));
        };
        match FT_New_Memory_Face(&library, bytes, row.face_index, 20.0) {
            Ok(_face) => Ok((FT_Err_Ok, false)),
            Err(err) => Ok((err, true)),
        }
    })
}

fn c_new_memory_face_variants(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let rows = memory_face_rows(&case.inputs.params)?;
    let mut library = std::ptr::null_mut();
    let err = c_abi::FT_Init_FreeType(&mut library);
    if err != FT_Err_Ok {
        return Ok(error(err));
    }
    let output = memory_face_outputs(rows, |row| {
        let file_size = memory_face_file_size(bytes.len(), row)?;
        let library_arg = if row.library_is_null {
            std::ptr::null_mut()
        } else {
            library
        };
        let mut face = std::ptr::null_mut();
        let face_ptr = if row.aface_is_null {
            std::ptr::null_mut()
        } else {
            &mut face
        };
        let open_args = c_abi::FT_Open_Args {
            flags: row.open_flags as c_abi::FT_UInt,
            memory_base: bytes.as_ptr(),
            memory_size: file_size,
            pathname: std::ptr::null_mut(),
            stream: std::ptr::null_mut(),
            driver: std::ptr::null_mut(),
            num_params: 0,
            params: std::ptr::null_mut(),
        };
        let err = if case.subject == "freetype.FT_Open_Face"
            || row.has_open_args
            || row.open_args_is_null
        {
            let args_ptr = if row.open_args_is_null {
                std::ptr::null()
            } else {
                &open_args
            };
            c_abi::FT_Open_Face(library_arg, args_ptr, row.face_index, face_ptr)
        } else {
            c_abi::FT_New_Memory_Face(
                library_arg,
                bytes.as_ptr(),
                file_size,
                row.face_index,
                face_ptr,
            )
        };
        let face_is_null = face.is_null();
        if err == FT_Err_Ok {
            c_done_face(face);
        }
        Ok((err, face_is_null))
    });
    c_done_library(library);
    output
}

fn c_new_memory_face_null_base(case: &InputCase) -> Result<RunOutput, String> {
    let mut library = std::ptr::null_mut();
    let init_err = c_abi::FT_Init_FreeType(&mut library);
    if init_err != FT_Err_Ok {
        return Ok(error(init_err));
    }
    let mut face = std::ptr::null_mut();
    let err = c_abi::FT_New_Memory_Face(
        library,
        ptr::null(),
        i64_param(&case.inputs.params, "file_size")?,
        face_index_param(&case.inputs.params)?,
        &mut face,
    );
    if err == FT_Err_Ok {
        c_done_face(face);
    }
    c_done_library(library);
    if err == FT_Err_Ok {
        Ok(ok(json!({"opened": true})))
    } else {
        Ok(error(err))
    }
}

fn wasm_new_memory_face_variants(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let rows = memory_face_rows(&case.inputs.params)?;
    memory_face_outputs(rows, |row| {
        if row.library_is_null {
            return Ok((FT_Err_Invalid_Library_Handle as FT_Error, true));
        }
        if row.open_args_is_null {
            return Ok((FT_Err_Invalid_Argument, true));
        }
        if row.aface_is_null {
            return Ok((FT_Err_Invalid_Argument, true));
        }
        if case.subject == "freetype.FT_Open_Face" {
            let source_flags =
                row.open_flags & (FT_OPEN_MEMORY | FT_OPEN_STREAM | FT_OPEN_PATHNAME);
            if source_flags != FT_OPEN_MEMORY {
                return Ok((FT_Err_Invalid_Argument, true));
            }
        }
        let file_size = memory_face_file_size(bytes.len(), row)?;
        let Ok(file_size) = usize::try_from(file_size) else {
            return Ok((FT_Err_Invalid_Argument, true));
        };
        let status =
            wasm_abi::fontdone_wasm_open_face(bytes.as_ptr(), file_size, row.face_index, 20.0);
        let face_is_null = status.handle == 0;
        wasm_done_face(status.handle);
        Ok((status.error, face_is_null))
    })
}

fn memory_face_outputs(
    rows: Vec<MemoryFaceRow>,
    mut call: impl FnMut(MemoryFaceRow) -> Result<(FT_Error, bool), String>,
) -> Result<RunOutput, String> {
    let mut first_error = FT_Err_Ok;
    let mut outputs = Vec::with_capacity(rows.len());
    for row in rows {
        let (status, face_is_null) = call(row)?;
        if first_error == FT_Err_Ok && status != FT_Err_Ok {
            first_error = status;
        }
        outputs.push(json!({
            "face_index": row.face_index,
            "file_size": row.file_size,
            "status": status,
            "error": status,
            "opened": !face_is_null,
            "face_nullness": if face_is_null { "null" } else { "non_null" }
        }));
    }
    let output = json!({ "outputs": outputs });
    if first_error == FT_Err_Ok {
        Ok(ok(output))
    } else {
        Ok(error_with_output(first_error, output))
    }
}

fn memory_face_file_size(data_len: usize, row: MemoryFaceRow) -> Result<i64, String> {
    Ok(row
        .file_size
        .unwrap_or_else(|| i64::try_from(data_len).unwrap_or(i64::MAX)))
}

fn memory_face_row_bytes(data: &[u8], row: MemoryFaceRow) -> Result<Option<&[u8]>, String> {
    let file_size = memory_face_file_size(data.len(), row)?;
    let Ok(file_size) = usize::try_from(file_size) else {
        return Ok(None);
    };
    data.get(..file_size).map(Some).ok_or_else(|| {
        format!(
            "file_size {file_size} exceeds fixture length {}",
            data.len()
        )
    })
}

fn rust_new_face_without_size(case: &InputCase) -> Result<FT_Face, String> {
    let data = font_bytes(case)?;
    rust_new_face_from_bytes(data.as_ref(), face_index_param(&case.inputs.params)?)
}

fn rust_new_foreign_face_without_size(case: &InputCase) -> Result<FT_Face, String> {
    let data = foreign_font_bytes(case)?;
    rust_new_face_from_bytes(data.as_ref(), 0)
}

fn rust_new_face_from_bytes(data: &[u8], face_index: i64) -> Result<FT_Face, String> {
    let library = FT_Init_FreeType();
    FT_New_Memory_Face(&library, data, face_index, 20.0)
        .map_err(|err| format!("FT_New_Memory_Face returned {err}"))
}

fn open_face(case: &InputCase) -> Result<FT_Face, String> {
    open_face_with_size_or_char_size(case, pixel_size_param(&case.inputs.params)?)
}

fn open_face_with_size_or_char_size(
    case: &InputCase,
    pixel_size: (u32, u32),
) -> Result<FT_Face, String> {
    let data = font_bytes(case)?;
    let library = FT_Init_FreeType();
    let mut face = FT_New_Memory_Face(
        &library,
        data.as_ref(),
        face_index_param(&case.inputs.params)?,
        20.0,
    )
    .map_err(|err| format!("FT_New_Memory_Face returned {err}"))?;
    if preserve_initial_size(&case.inputs.params)? {
        return Ok(face);
    }
    let err = if let Some(row) = preload_size_request_row(&case.inputs.params)? {
        let request = rust_size_request_rec(row);
        FT_Request_Size(Some(&mut face), Some(&request))
    } else if let Some(row) = preload_char_size_row(&case.inputs.params)? {
        FT_Set_Char_Size(
            &mut face,
            row.char_width,
            row.char_height,
            row.horz_resolution,
            row.vert_resolution,
        )
    } else {
        let (pixel_width, pixel_height) = pixel_size;
        FT_Set_Pixel_Sizes(&mut face, pixel_width, pixel_height)
    };
    if err == FT_Err_Ok {
        Ok(face)
    } else {
        Err(format!("FT size setup returned {err}"))
    }
}

fn open_face_with_size(case: &InputCase, pixel_size: (u32, u32)) -> Result<FT_Face, String> {
    open_face_with_size_or_char_size(case, pixel_size)
}

fn open_api_face(case: &InputCase) -> Result<ApiFace, String> {
    let data = font_bytes(case)?;
    let face_index =
        usize::try_from(face_index_param(&case.inputs.params)?).map_err(|err| err.to_string())?;
    let mut face = ApiFace::from_memory(data.as_ref(), face_index, 20.0)
        .map_err(|err| format!("Face::from_memory returned {err}"))?;
    if let Some(row) = preload_char_size_row(&case.inputs.params)? {
        let char_width = i32::try_from(row.char_width)
            .map_err(|err| format!("preload char_width does not fit i32: {err}"))?;
        let char_height = i32::try_from(row.char_height)
            .map_err(|err| format!("preload char_height does not fit i32: {err}"))?;
        face.set_char_size(
            char_width,
            char_height,
            row.horz_resolution,
            row.vert_resolution,
        );
    } else {
        let (pixel_width, pixel_height) = pixel_size_param(&case.inputs.params)?;
        face.set_pixel_sizes(pixel_width, pixel_height);
    }
    Ok(face)
}

fn rust_set_pixel_sizes(case: &InputCase) -> Result<RunOutput, String> {
    let data = font_bytes(case)?;
    let library = FT_Init_FreeType();
    match FT_New_Memory_Face(
        &library,
        data.as_ref(),
        face_index_param(&case.inputs.params)?,
        20.0,
    ) {
        Ok(mut face) => {
            let (pixel_width, pixel_height) = pixel_size_param(&case.inputs.params)?;
            let err = FT_Set_Pixel_Sizes(&mut face, pixel_width, pixel_height);
            if err == FT_Err_Ok {
                Ok(ok(size_metrics_json(&face.size_metrics)))
            } else {
                Ok(error(err))
            }
        }
        Err(err) => Ok(error(err)),
    }
}

fn rust_set_char_size(case: &InputCase) -> Result<RunOutput, String> {
    if !case.expect_error {
        return rust_set_char_size_public_api(case);
    }
    let mut face = rust_new_face_without_size(case)?;
    let rows = char_size_rows(&case.inputs.params)?;
    char_size_outputs(rows, |row| {
        let err = FT_Set_Char_Size(
            &mut face,
            row.char_width,
            row.char_height,
            row.horz_resolution,
            row.vert_resolution,
        );
        let output = if err == FT_Err_Ok {
            size_metrics_json(&face.size_metrics)
        } else {
            Value::Null
        };
        Ok((err, output))
    })
}

fn rust_set_char_size_public_api(case: &InputCase) -> Result<RunOutput, String> {
    let data = font_bytes(case)?;
    let face_index =
        usize::try_from(face_index_param(&case.inputs.params)?).map_err(|err| err.to_string())?;
    let mut face = ApiFace::from_memory(data.as_ref(), face_index, 20.0)
        .map_err(|err| format!("Face::from_memory returned {err}"))?;
    let rows = char_size_rows(&case.inputs.params)?;
    char_size_outputs(rows, |row| {
        let Ok(char_width) = i32::try_from(row.char_width) else {
            return Ok((FT_Err_Invalid_Argument, Value::Null));
        };
        let Ok(char_height) = i32::try_from(row.char_height) else {
            return Ok((FT_Err_Invalid_Argument, Value::Null));
        };
        face.set_char_size(
            char_width,
            char_height,
            row.horz_resolution,
            row.vert_resolution,
        );
        let metrics: FT_Size_Metrics = face.size_metrics().into();
        Ok((FT_Err_Ok, size_metrics_json(&metrics)))
    })
}

fn c_set_char_size(face: c_abi::FT_Face, case: &InputCase) -> Result<RunOutput, String> {
    let rows = char_size_rows(&case.inputs.params)?;
    char_size_outputs(rows, |row| {
        let err = c_abi::FT_Set_Char_Size(
            face,
            row.char_width,
            row.char_height,
            row.horz_resolution,
            row.vert_resolution,
        );
        let output = if err == FT_Err_Ok {
            c_size_metrics_json(face)?
        } else {
            Value::Null
        };
        Ok((err, output))
    })
}

fn wasm_set_char_size(handle: usize, case: &InputCase) -> Result<RunOutput, String> {
    let rows = char_size_rows(&case.inputs.params)?;
    char_size_outputs(rows, |row| {
        let err = wasm_abi::fontdone_wasm_set_char_size(
            handle,
            row.char_width,
            row.char_height,
            row.horz_resolution,
            row.vert_resolution,
        );
        let output = if err == FT_Err_Ok {
            let mut metrics = wasm_abi::FontdoneWasmSizeMetrics::default();
            let metrics_err = wasm_abi::fontdone_wasm_size_metrics(handle, &mut metrics);
            if metrics_err != FT_Err_Ok {
                return Ok((metrics_err, Value::Null));
            }
            wasm_size_metrics_json(&metrics)
        } else {
            Value::Null
        };
        Ok((err, output))
    })
}

fn char_size_outputs(
    rows: Vec<CharSizeRow>,
    mut call: impl FnMut(CharSizeRow) -> Result<(FT_Error, Value), String>,
) -> Result<RunOutput, String> {
    let mut first_error = FT_Err_Ok;
    let mut outputs = Vec::with_capacity(rows.len());
    for row in rows {
        let (status, output) = call(row)?;
        if first_error == FT_Err_Ok && status != FT_Err_Ok {
            first_error = status;
        }
        outputs.push(json!({
            "request": char_size_row_json(row),
            "status": status,
            "output": output
        }));
    }
    let output = json!({ "outputs": outputs });
    if first_error == FT_Err_Ok {
        Ok(ok(output))
    } else {
        Ok(error_with_output(first_error, output))
    }
}

fn rust_request_size(case: &InputCase) -> Result<RunOutput, String> {
    let mut face = rust_new_face_without_size(case)?;
    let rows = size_request_rows(&case.inputs.params)?;
    let mut outputs = Vec::with_capacity(rows.len());
    let mut first_error = FT_Err_Ok;
    for row in rows {
        let request = (!row.request_is_null).then(|| rust_size_request_rec(row));
        let err = if row.face_is_null {
            FT_Request_Size(None, request.as_ref())
        } else {
            FT_Request_Size(Some(&mut face), request.as_ref())
        };
        if first_error == FT_Err_Ok && err != FT_Err_Ok {
            first_error = err;
        }
        let metrics = if err == FT_Err_Ok && !row.face_is_null {
            size_metrics_json(&face.size_metrics)
        } else {
            Value::Null
        };
        outputs.push(size_request_row_output(row, err, metrics));
    }
    let output = json!({ "outputs": outputs });
    if first_error == FT_Err_Ok {
        Ok(ok(output))
    } else {
        Ok(error_with_output(first_error, output))
    }
}

fn c_request_size(face: c_abi::FT_Face, case: &InputCase) -> Result<RunOutput, String> {
    let rows = size_request_rows(&case.inputs.params)?;
    let mut outputs = Vec::with_capacity(rows.len());
    let mut first_error = FT_Err_Ok;
    for row in rows {
        let request = c_size_request_rec(row);
        let request_ptr = if row.request_is_null {
            std::ptr::null()
        } else {
            &request
        };
        let call_face = if row.face_is_null {
            std::ptr::null_mut()
        } else {
            face
        };
        let err = c_abi::FT_Request_Size(call_face, request_ptr);
        if first_error == FT_Err_Ok && err != FT_Err_Ok {
            first_error = err;
        }
        let metrics = if err == FT_Err_Ok && !row.face_is_null {
            c_size_metrics_json(face)?
        } else {
            Value::Null
        };
        outputs.push(size_request_row_output(row, err, metrics));
    }
    let output = json!({ "outputs": outputs });
    if first_error == FT_Err_Ok {
        Ok(ok(output))
    } else {
        Ok(error_with_output(first_error, output))
    }
}

fn wasm_request_size(handle: usize, case: &InputCase) -> Result<RunOutput, String> {
    let rows = size_request_rows(&case.inputs.params)?;
    let mut outputs = Vec::with_capacity(rows.len());
    let mut first_error = FT_Err_Ok;
    for row in rows {
        let request = wasm_size_request_rec(row);
        let request_ptr = if row.request_is_null {
            std::ptr::null()
        } else {
            &request
        };
        let call_handle = if row.face_is_null { 0 } else { handle };
        let err = wasm_abi::fontdone_wasm_request_size(call_handle, request_ptr);
        if first_error == FT_Err_Ok && err != FT_Err_Ok {
            first_error = err;
        }
        let metrics = if err == FT_Err_Ok && !row.face_is_null {
            let mut metrics = wasm_abi::FontdoneWasmSizeMetrics::default();
            let metrics_err = wasm_abi::fontdone_wasm_size_metrics(handle, &mut metrics);
            if metrics_err == FT_Err_Ok {
                wasm_size_metrics_json(&metrics)
            } else {
                Value::Null
            }
        } else {
            Value::Null
        };
        outputs.push(size_request_row_output(row, err, metrics));
    }
    let output = json!({ "outputs": outputs });
    if first_error == FT_Err_Ok {
        Ok(ok(output))
    } else {
        Ok(error_with_output(first_error, output))
    }
}

fn size_request_row_output(row: SizeRequestRow, err: i32, metrics: Value) -> Value {
    let request = if row.request_is_null {
        Value::Null
    } else {
        json!({
            "type": row.type_,
            "width": row.width,
            "height": row.height,
            "horiResolution": row.hori_resolution,
            "vertResolution": row.vert_resolution
        })
    };
    json!({
        "face": if row.face_is_null { "null" } else { "valid" },
        "request": request,
        "status": err,
        "metrics": metrics
    })
}

fn rust_size_request_rec(row: SizeRequestRow) -> FT_Size_RequestRec {
    FT_Size_RequestRec {
        type_: row.type_,
        width: row.width,
        height: row.height,
        horiResolution: row.hori_resolution,
        vertResolution: row.vert_resolution,
    }
}

fn c_size_request_rec(row: SizeRequestRow) -> c_abi::FT_Size_RequestRec {
    c_abi::FT_Size_RequestRec {
        type_: row.type_,
        width: row.width,
        height: row.height,
        horiResolution: row.hori_resolution,
        vertResolution: row.vert_resolution,
    }
}

fn wasm_size_request_rec(row: SizeRequestRow) -> wasm_abi::FontdoneWasmSizeRequest {
    wasm_abi::FontdoneWasmSizeRequest {
        type_: row.type_,
        width: row.width,
        height: row.height,
        horiResolution: row.hori_resolution,
        vertResolution: row.vert_resolution,
    }
}

