fn outline_decompose_transforms(case: &InputCase) -> Result<Vec<(FT_Int, FT_Pos)>, String> {
    if let Some(values) = case
        .inputs
        .params
        .get("shift_delta_cases")
        .or_else(|| case.inputs.params.get("shift_delta_matrix"))
        .and_then(Value::as_array)
    {
        return values
            .iter()
            .map(|value| {
                let shift = value
                    .get("shift")
                    .and_then(Value::as_i64)
                    .ok_or_else(|| "shift_delta_cases[].shift must be an integer".to_string())?;
                let delta = value
                    .get("delta")
                    .and_then(Value::as_i64)
                    .ok_or_else(|| "shift_delta_cases[].delta must be an integer".to_string())?;
                Ok((
                    FT_Int::try_from(shift).map_err(|err| err.to_string())?,
                    FT_Pos::try_from(delta).map_err(|err| err.to_string())?,
                ))
            })
            .collect();
    }
    if case.inputs.params.get("callback_return").is_some() {
        return Ok(vec![(0, 0)]);
    }
    if case.case_id == "ftimage.FT_CURVE_TAG.classifies_outline_tags" {
        return Ok(vec![(0, 0)]);
    }
    if case.inputs.params.get("shift").is_some() || case.inputs.params.get("delta").is_some() {
        let shift = case
            .inputs
            .params
            .get("shift")
            .and_then(Value::as_i64)
            .ok_or_else(|| "shift must be an integer".to_string())?;
        let delta = case
            .inputs
            .params
            .get("delta")
            .and_then(Value::as_i64)
            .ok_or_else(|| "delta must be an integer".to_string())?;
        return Ok(vec![(
            FT_Int::try_from(shift).map_err(|err| err.to_string())?,
            FT_Pos::try_from(delta).map_err(|err| err.to_string())?,
        )]);
    }
    let funcs = case
        .inputs
        .params
        .get("funcs")
        .or_else(|| {
            case.inputs
                .params
                .get("callback_fail_at")
                .map(|_| &Value::Null)
        })
        .ok_or_else(|| "shift_delta_cases or funcs must be present".to_string())?;
    if funcs.is_null() {
        return Ok(vec![(0, 0)]);
    }
    let shift = funcs
        .get("shift")
        .and_then(Value::as_i64)
        .ok_or_else(|| "funcs.shift must be an integer".to_string())?;
    let delta = funcs
        .get("delta")
        .and_then(Value::as_i64)
        .ok_or_else(|| "funcs.delta must be an integer".to_string())?;
    Ok(vec![(
        FT_Int::try_from(shift).map_err(|err| err.to_string())?,
        FT_Pos::try_from(delta).map_err(|err| err.to_string())?,
    )])
}

fn outline_decompose_trace_payload_with_malformed_status(
    runs: Vec<FTOutlineDecomposeRun>,
    malformed_status: Vec<Value>,
) -> Value {
    let mut payload = outline_decompose_trace_payload(runs);
    if let Some(object) = payload.as_object_mut() {
        object.insert(
            "malformed_status".to_string(),
            Value::Array(malformed_status),
        );
    }
    payload
}

fn outline_decompose_trace_payload_with_masked_tags(
    runs: Vec<FTOutlineDecomposeRun>,
    masked_tags: Vec<Value>,
) -> Value {
    let mut payload = outline_decompose_trace_payload(runs);
    if let Some(object) = payload.as_object_mut() {
        object.insert("masked_tags".to_string(), Value::Array(masked_tags));
    }
    payload
}

fn outline_decompose_masked_tags(outline: &fontdone::outline::Outline) -> Vec<Value> {
    // FreeType's public FT_CURVE_TAG macro masks only the low two bits
    // (`ftimage.h`), preserving TOUCH/SCANMODE bits in the stored tag byte
    // while ignoring them for outline decomposition classification.
    outline
        .tags
        .iter()
        .copied()
        .map(|tag| Value::from(i64::from(tag & 0x03)))
        .collect()
}

fn outline_decompose_trace_payload(runs: Vec<FTOutlineDecomposeRun>) -> Value {
    json!({
        "runs": runs
            .into_iter()
            .map(|run| {
                json!({
                    "shift": run.shift,
                    "delta": run.delta,
                    "status": FT_Err_Ok,
                    "events": run.events
                        .into_iter()
                        .map(outline_decompose_event_json)
                        .collect::<Vec<_>>(),
                    "transformed_points": run
                        .transformed_points
                        .into_iter()
                        .map(vector_json)
                        .collect::<Vec<_>>(),
                    "user_seen": run.user_seen,
                })
            })
            .collect::<Vec<_>>()
    })
}

fn outline_decompose_callback_error_output(
    case: &InputCase,
    runs: Vec<FTOutlineDecomposeRun>,
) -> Result<RunOutput, String> {
    let fail_at = case
        .inputs
        .params
        .get("callback_fail_at")
        .ok_or_else(|| "callback_fail_at is required".to_string())?;
    let event_index = fail_at
        .get("event_index")
        .and_then(Value::as_u64)
        .ok_or_else(|| "callback_fail_at.event_index must be an integer".to_string())?;
    let error_name = fail_at
        .get("error")
        .and_then(Value::as_str)
        .ok_or_else(|| "callback_fail_at.error must be a constant name".to_string())?;
    let error_code = if error_name == "FT_Err_Invalid_Argument" {
        // FreeType 2.14.3 fterrdef.h defines Invalid_Argument as 0x06.
        0x06
    } else {
        i32::try_from(rust_constant(error_name)?).map_err(|err| err.to_string())?
    };
    let run = runs
        .into_iter()
        .next()
        .ok_or_else(|| "callback error trace requires one run".to_string())?;
    let events_before_error = run
        .events
        .into_iter()
        .take(usize::try_from(event_index).map_err(|err| err.to_string())?)
        .map(outline_decompose_event_json)
        .collect::<Vec<_>>();
    Ok(error_with_output(
        error_code,
        json!({
            "return": error_code,
            "events_before_error": events_before_error,
        }),
    ))
}

fn outline_funcs_callback_error_output(
    case: &InputCase,
    runs: Vec<FTOutlineDecomposeRun>,
) -> Result<RunOutput, String> {
    let callback_return = case
        .inputs
        .params
        .get("callback_return")
        .and_then(Value::as_i64)
        .ok_or_else(|| "callback_return must be an integer".to_string())?;
    let error_code = i32::try_from(callback_return).map_err(|err| err.to_string())?;
    let failure_points = case
        .inputs
        .params
        .get("callback_failure_points")
        .and_then(Value::as_array)
        .ok_or_else(|| "callback_failure_points must be an array".to_string())?;
    let run = runs
        .into_iter()
        .next()
        .ok_or_else(|| "callback error trace requires one run".to_string())?;
    let events = run.events;
    let rows = failure_points
        .iter()
        .map(|value| {
            let label = value
                .as_str()
                .ok_or_else(|| "callback_failure_points[] must be strings".to_string())?;
            let event_index = outline_callback_failure_event_index(&events, label)?;
            Ok(json!({
                "failure_point": label,
                "events": events
                    .iter()
                    .take(event_index)
                    .cloned()
                    .map(outline_decompose_event_json)
                    .collect::<Vec<_>>(),
            }))
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok(error_with_output(
        error_code,
        json!({
            "status": error_code,
            "error": error_code,
            "events_before_error": rows,
        }),
    ))
}

fn outline_callback_failure_event_index(
    events: &[FTOutlineDecomposeEvent],
    label: &str,
) -> Result<usize, String> {
    let (kind, occurrence) = label
        .split_once('#')
        .ok_or_else(|| format!("invalid callback failure label {label}"))?;
    let target_occurrence = occurrence
        .parse::<usize>()
        .map_err(|err| format!("invalid callback failure occurrence {label}: {err}"))?;
    let mut seen = 0usize;
    for (index, event) in events.iter().enumerate() {
        if event.kind == kind {
            seen += 1;
            if seen == target_occurrence {
                return Ok(index);
            }
        }
    }
    Err(format!(
        "callback failure label {label} did not match an event"
    ))
}

fn outline_decompose_event_json(event: FTOutlineDecomposeEvent) -> Value {
    json!({
        "kind": event.kind,
        "points": event.points.into_iter().map(vector_json).collect::<Vec<_>>(),
    })
}

fn vector_json(vector: FT_Vector) -> Value {
    json!({
        "x": vector.x,
        "y": vector.y,
    })
}

// The legacy direct-span rows are still classified as fallback coverage and
// intentionally remain on their pre-existing shared handler.  The public
// bitmap matrix below must not turn them into apparent C/C-ABI/WASM parity.
fn outline_render_direct_fallback_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    if case.expect_error {
        return Ok(error(FT_Err_Invalid_Argument));
    }
    let outline = outline_render_outline(case)?;
    let (width, height) = outline_render_target_box(case)?;
    let pitch = outline_render_target_pitch(case, width)?;
    let no_contours = outline.points.is_empty() || outline.n_contours == 0;
    let explicit_target_box = case.inputs.params.get("target_box").is_some();
    let clip_box = outline_render_clip_box(&case.inputs.params)?;
    let raster = if explicit_target_box {
        if let Some((x_min, x_max, y_min, y_max)) = clip_box {
            let mut target = vec![0u8; width * height];
            match fontdone::grays::rasterize_shifted_in_box_to(
                &outline,
                0,
                0,
                width,
                height,
                &mut target,
                width,
                1,
                0,
                x_min,
                x_max,
                y_min,
                y_max,
            ) {
                Ok(()) => Ok(fontdone::grays::RasterResult {
                    width,
                    height,
                    pixels: target,
                }),
                Err(err) => Err(err),
            }
        } else {
            fontdone::grays::rasterize_in_box(outline, width, height)
        }
    } else {
        fontdone::grays::rasterize(outline)
    };
    match raster {
        Ok(raster) => {
            let buffer = if no_contours {
                vec![0; width * height]
            } else {
                raster.pixels
            };
            Ok(ok(outline_render_bitmap_payload(
                width,
                height,
                pitch,
                FT_PIXEL_MODE_GRAY,
                &buffer,
                true,
            )))
        }
        Err(fontdone::FontError::InvalidOutline(_)) => Ok(error(FT_Err_Invalid_Outline)),
        Err(err) => Err(err.to_string()),
    }
}

fn rust_outline_render_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    if case.case_id == "ftimage.FT_Raster_Params.clip_box_matches_c" {
        return rust_outline_render_clip_box_cases(case);
    }
    if let Some(flag_sets) = outline_render_flag_matrix(&case.inputs.params)? {
        let mut results = Vec::with_capacity(flag_sets.len());
        for (flags_label, flags) in flag_sets {
            let output = rust_outline_render_once(case, flags, None, true)?;
            results.push(outline_render_result_payload(flags_label, output));
        }
        return Ok(ok(json!({ "results": results })));
    }
    if let Some(flag_sets) = outline_render_outline_flag_matrix(&case.inputs.params)? {
        let mut results = Vec::with_capacity(flag_sets.len());
        for (flags_label, outline_flags) in flag_sets {
            let output = rust_outline_render_once(
                case,
                i32::try_from(FT_RASTER_FLAG_AA).map_err(|err| err.to_string())?,
                Some(outline_flags),
                true,
            )?;
            results.push(outline_render_result_payload(flags_label, output));
        }
        return Ok(ok(json!({ "results": results })));
    }
    if let Some(outline_flags) = outline_render_outline_flags(&case.inputs.params)? {
        return rust_outline_render_once(
            case,
            i32::try_from(FT_RASTER_FLAG_AA).map_err(|err| err.to_string())?,
            Some(outline_flags),
            false,
        );
    }
    let flags = outline_render_flags(&case.inputs.params)?;
    rust_outline_render_once(case, flags, None, false)
}

fn rust_outline_render_once(
    case: &InputCase,
    flags: i32,
    outline_flags: Option<u32>,
    include_error_output: bool,
) -> Result<RunOutput, String> {
    let library = FT_Init_FreeType();
    let mut outline_model = outline_render_outline(case)?;
    if let Some(flags) = outline_flags {
        outline_model.flags = flags;
    }
    let outline = outline_render_snapshot(&outline_model);
    let (width, rows) = outline_render_target_box(case)?;
    let pitch = outline_render_target_pitch(case, width)?;
    let pixel_mode = outline_render_target_pixel_mode(&case.inputs.params)?;
    let buffer_len = usize::try_from(pitch.unsigned_abs())
        .map_err(|err| err.to_string())?
        .checked_mul(rows)
        .ok_or_else(|| "outline target buffer length overflow".to_string())?;
    let mut buffer = vec![
        if case.expectation.compare.compare_error_output {
            0xA5
        } else {
            0
        };
        buffer_len
    ];
    let clip_box = outline_render_ffi_clip_box(&case.inputs.params)?;
    let target = FT_Bitmap_C {
        rows: u32::try_from(rows).map_err(|err| err.to_string())?,
        width: u32::try_from(width).map_err(|err| err.to_string())?,
        pitch,
        buffer: buffer.as_mut_ptr(),
        num_grays: outline_render_num_grays(pixel_mode),
        pixel_mode: pixel_mode as u8,
        palette_mode: 0,
        palette: ptr::null_mut(),
    };
    if flags & i32::try_from(FT_RASTER_FLAG_DIRECT).unwrap_or(0) != 0 {
        let observed_clip_box =
            outline_render_observed_direct_clip_box(&outline_model, flags, Some(clip_box));
        return match FT_Outline_Render_Direct_Spans(
            Some(&library),
            Some(&outline),
            Some(&target),
            flags,
            Some(clip_box),
            outline_render_gray_spans_present(&case.inputs.params),
        ) {
            Ok(spans) => {
                let user_seen =
                    outline_render_gray_spans_present(&case.inputs.params) && !spans.is_empty();
                Ok(ok(outline_render_direct_payload(
                    spans,
                    user_seen,
                    observed_clip_box,
                )))
            }
            Err(err) => Ok(error(err)),
        };
    }
    match FT_Outline_Render(
        Some(&library),
        Some(&outline),
        Some(&target),
        flags,
        clip_box,
    ) {
        Ok(rendered) => Ok(ok(outline_render_bitmap_payload(
            width,
            rows,
            pitch,
            pixel_mode,
            &rendered.buffer,
            true,
        ))),
        Err(err) if include_error_output || case.expectation.compare.compare_error_output => {
            if outline_render_error_output_available(flags, pixel_mode) {
                let output_buffer =
                    FT_Outline_Render_Error_Output(Some(&outline), Some(&target), flags)
                        .map_or_else(|| buffer.clone(), |rendered| rendered.buffer);
                Ok(error_with_output(
                    err,
                    outline_render_bitmap_payload(
                        width,
                        rows,
                        pitch,
                        pixel_mode,
                        &output_buffer,
                        true,
                    ),
                ))
            } else {
                Ok(error(err))
            }
        }
        Err(err) => Ok(error(err)),
    }
}

fn c_outline_render_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    if case.case_id == "ftimage.FT_Raster_Params.clip_box_matches_c" {
        return c_outline_render_clip_box_cases(case);
    }
    if let Some(flag_sets) = outline_render_flag_matrix(&case.inputs.params)? {
        let mut results = Vec::with_capacity(flag_sets.len());
        for (flags_label, flags) in flag_sets {
            let output = c_outline_render_once(case, flags, None, true)?;
            results.push(outline_render_result_payload(flags_label, output));
        }
        return Ok(ok(json!({ "results": results })));
    }
    if let Some(flag_sets) = outline_render_outline_flag_matrix(&case.inputs.params)? {
        let mut results = Vec::with_capacity(flag_sets.len());
        for (flags_label, outline_flags) in flag_sets {
            let output = c_outline_render_once(
                case,
                i32::try_from(FT_RASTER_FLAG_AA).map_err(|err| err.to_string())?,
                Some(outline_flags),
                true,
            )?;
            results.push(outline_render_result_payload(flags_label, output));
        }
        return Ok(ok(json!({ "results": results })));
    }
    if let Some(outline_flags) = outline_render_outline_flags(&case.inputs.params)? {
        return c_outline_render_once(
            case,
            i32::try_from(FT_RASTER_FLAG_AA).map_err(|err| err.to_string())?,
            Some(outline_flags),
            false,
        );
    }
    let flags = outline_render_flags(&case.inputs.params)?;
    c_outline_render_once(case, flags, None, false)
}

fn c_outline_render_once(
    case: &InputCase,
    flags: i32,
    outline_flags: Option<u32>,
    include_error_output: bool,
) -> Result<RunOutput, String> {
    let mut library = ptr::null_mut();
    let init_error = c_abi::FT_Init_FreeType(&mut library);
    if init_error != FT_Err_Ok {
        return Ok(error(init_error));
    }
    let mut outline_model = outline_render_outline(case)?;
    if let Some(flags) = outline_flags {
        outline_model.flags = flags;
    }
    let mut outline = CRenderOutlineStorage::new(&outline_model);
    let outline_ptr = outline.as_ptr();
    let (width, rows) = outline_render_target_box(case)?;
    let pitch = outline_render_target_pitch(case, width)?;
    let pixel_mode = outline_render_target_pixel_mode(&case.inputs.params)?;
    let buffer_len = usize::try_from(pitch.unsigned_abs())
        .map_err(|err| err.to_string())?
        .checked_mul(rows)
        .ok_or_else(|| "outline target buffer length overflow".to_string())?;
    let mut buffer = vec![
        if case.expectation.compare.compare_error_output {
            0xA5
        } else {
            0
        };
        buffer_len
    ];
    let target = c_abi::FT_Bitmap {
        rows: u32::try_from(rows).map_err(|err| err.to_string())?,
        width: u32::try_from(width).map_err(|err| err.to_string())?,
        pitch,
        buffer: buffer.as_mut_ptr(),
        num_grays: outline_render_num_grays(pixel_mode),
        pixel_mode,
        palette_mode: 0,
        palette: ptr::null_mut(),
    };
    let clip_box = outline_render_ffi_clip_box(&case.inputs.params)?;
    let mut params = c_abi::FT_Raster_Params {
        target: &target,
        source: std::ptr::dangling::<c_void>(),
        flags,
        clip_box: c_abi::FT_BBox {
            xMin: clip_box.xMin,
            yMin: clip_box.yMin,
            xMax: clip_box.xMax,
            yMax: clip_box.yMax,
        },
        ..c_abi::FT_Raster_Params::default()
    };
    let direct_render = flags & i32::try_from(FT_RASTER_FLAG_DIRECT).unwrap_or(0) != 0;
    if direct_render {
        let observed_clip_box = outline_render_observed_direct_clip_box(
            &outline_model,
            flags,
            Some(FT_BBox {
                xMin: clip_box.xMin,
                yMin: clip_box.yMin,
                xMax: clip_box.xMax,
                yMax: clip_box.yMax,
            }),
        );
        let (err, spans, user_seen) = c_abi::abi_support_outline_render_direct_spans(
            library,
            outline_ptr,
            &mut params,
            outline_render_gray_spans_present(&case.inputs.params),
            OUTLINE_RENDER_USER_TOKEN as *mut c_void,
        );
        c_done_library(library);
        return if err == FT_Err_Ok {
            Ok(ok(c_outline_render_direct_payload(
                spans,
                user_seen,
                observed_clip_box,
            )))
        } else {
            Ok(error(err))
        };
    }
    let err = c_abi::FT_Outline_Render(library, outline_ptr, &mut params);
    c_done_library(library);
    if err == FT_Err_Ok {
        Ok(ok(outline_render_bitmap_payload(
            width,
            rows,
            pitch,
            pixel_mode,
            &buffer,
            params.source == outline_ptr.cast(),
        )))
    } else if include_error_output || case.expectation.compare.compare_error_output {
        if outline_render_error_output_available(flags, pixel_mode) {
            Ok(error_with_output(
                err,
                outline_render_bitmap_payload(
                    width,
                    rows,
                    pitch,
                    pixel_mode,
                    &buffer,
                    params.source == outline_ptr.cast(),
                ),
            ))
        } else {
            Ok(error(err))
        }
    } else {
        Ok(error(err))
    }
}

fn wasm_outline_render_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    if case.case_id == "ftimage.FT_Raster_Params.clip_box_matches_c" {
        return wasm_outline_render_clip_box_cases(case);
    }
    if let Some(flag_sets) = outline_render_flag_matrix(&case.inputs.params)? {
        let mut results = Vec::with_capacity(flag_sets.len());
        for (flags_label, flags) in flag_sets {
            let output = wasm_outline_render_once(case, flags, None, true)?;
            results.push(outline_render_result_payload(flags_label, output));
        }
        return Ok(ok(json!({ "results": results })));
    }
    if let Some(flag_sets) = outline_render_outline_flag_matrix(&case.inputs.params)? {
        let mut results = Vec::with_capacity(flag_sets.len());
        for (flags_label, outline_flags) in flag_sets {
            let output = wasm_outline_render_once(
                case,
                i32::try_from(FT_RASTER_FLAG_AA).map_err(|err| err.to_string())?,
                Some(outline_flags),
                true,
            )?;
            results.push(outline_render_result_payload(flags_label, output));
        }
        return Ok(ok(json!({ "results": results })));
    }
    if let Some(outline_flags) = outline_render_outline_flags(&case.inputs.params)? {
        return wasm_outline_render_once(
            case,
            i32::try_from(FT_RASTER_FLAG_AA).map_err(|err| err.to_string())?,
            Some(outline_flags),
            false,
        );
    }
    let flags = outline_render_flags(&case.inputs.params)?;
    wasm_outline_render_once(case, flags, None, false)
}

