fn outline_render_snapshot(outline: &fontdone::outline::Outline) -> FT_OutlineSnapshot {
    let tags = if outline.tags.len() == outline.points.len() {
        outline.tags.clone()
    } else {
        outline
            .points
            .iter()
            .map(|point| u8::from(point.on_curve))
            .collect()
    };
    FT_OutlineSnapshot {
        points: outline
            .points
            .iter()
            .map(|point| FT_Vector {
                x: i64::from(point.x),
                y: i64::from(point.y),
            })
            .collect(),
        tags,
        contours: outline
            .contours
            .iter()
            .map(|contour| u16::from_ne_bytes(contour.to_ne_bytes()))
            .collect(),
        flags: i32::try_from(outline.flags).unwrap_or(0),
    }
}

fn outline_render_flags(params: &Value) -> Result<i32, String> {
    let flags = params
        .get("flags")
        .or_else(|| {
            params
                .get("raster_params")
                .and_then(|raster_params| raster_params.get("flags"))
        })
        .and_then(Value::as_array)
        .ok_or_else(|| "flags or raster_params.flags must be an array".to_string())?;
    outline_render_flag_symbols(flags)
}

#[derive(Clone, Copy)]
struct OutlineRenderClipBoxCase {
    flags: i32,
    clip_box: FT_BBox,
}

fn outline_render_clip_box_case_specs(
    params: &Value,
) -> Result<Vec<OutlineRenderClipBoxCase>, String> {
    let cases = params
        .get("cases")
        .and_then(Value::as_array)
        .ok_or_else(|| "params.cases must be an array".to_string())?;
    cases
        .iter()
        .enumerate()
        .map(|(index, case)| {
            let flags = case
                .get("flags")
                .and_then(Value::as_str)
                .ok_or_else(|| format!("params.cases[{index}].flags must be a string"))?;
            let flags = outline_render_raster_flag_expr(flags)?;
            let clip_box = outline_render_clip_box_case_value(
                case.get("clip_box")
                    .ok_or_else(|| format!("params.cases[{index}].clip_box is required"))?,
            )?;
            Ok(OutlineRenderClipBoxCase { flags, clip_box })
        })
        .collect()
}

fn outline_render_raster_flag_expr(symbol: &str) -> Result<i32, String> {
    symbol.split('|').try_fold(0_i32, |combined, part| {
        let value = i32::try_from(rust_constant(part.trim())?).map_err(|err| err.to_string())?;
        Ok(combined | value)
    })
}

fn outline_render_clip_box_case_value(value: &Value) -> Result<FT_BBox, String> {
    if value.as_str().is_some() {
        return Ok(FT_BBox {
            xMin: -999,
            yMin: -999,
            xMax: -998,
            yMax: -998,
        });
    }
    let field = |name: &str| -> Result<i64, String> {
        value
            .get(name)
            .and_then(Value::as_i64)
            .ok_or_else(|| format!("clip_box.{name} must be an integer"))
    };
    Ok(FT_BBox {
        xMin: field("xMin")?,
        yMin: field("yMin")?,
        xMax: field("xMax")?,
        yMax: field("yMax")?,
    })
}

fn outline_render_flag_matrix(params: &Value) -> Result<Option<Vec<(String, i32)>>, String> {
    let Some(flags) = params.get("flags_matrix").and_then(Value::as_array) else {
        return Ok(None);
    };
    flags
        .iter()
        .map(|flag| {
            let symbol = flag
                .as_str()
                .ok_or_else(|| "raster flag matrix entry must be a constant name".to_string())?;
            let value = i32::try_from(rust_constant(symbol)?).map_err(|err| err.to_string())?;
            Ok((symbol.to_string(), value))
        })
        .collect::<Result<Vec<_>, String>>()
        .map(Some)
}

fn outline_render_outline_flag_matrix(
    params: &Value,
) -> Result<Option<Vec<(String, u32)>>, String> {
    let Some(flags) = params.get("outline_flags_matrix").and_then(Value::as_array) else {
        return Ok(None);
    };
    flags
        .iter()
        .map(|flag| {
            let symbol = flag
                .as_str()
                .ok_or_else(|| "outline flag matrix entry must be a constant name".to_string())?;
            let value = if symbol == "FT_OUTLINE_NONE" {
                0
            } else {
                u32::try_from(rust_constant(symbol)?).map_err(|err| err.to_string())?
            };
            Ok((symbol.to_string(), value))
        })
        .collect::<Result<Vec<_>, String>>()
        .map(Some)
}

fn outline_render_outline_flags(params: &Value) -> Result<Option<u32>, String> {
    let Some(flags) = params.get("outline_flags").and_then(Value::as_array) else {
        return Ok(None);
    };
    outline_render_outline_flag_symbols(flags).map(Some)
}

fn outline_render_outline_flag_symbols(flags: &[Value]) -> Result<u32, String> {
    flags.iter().try_fold(0_u32, |combined, flag| {
        let symbol = flag
            .as_str()
            .ok_or_else(|| "outline flag must be a constant name".to_string())?;
        let value = outline_render_outline_flag_expr(symbol)?;
        Ok(combined | value)
    })
}

fn outline_render_outline_flag_expr(symbol: &str) -> Result<u32, String> {
    symbol.split('|').try_fold(0_u32, |combined, part| {
        let part = part.trim();
        let value = if part == "FT_OUTLINE_NONE" {
            0
        } else {
            u32::try_from(rust_constant(part)?).map_err(|err| err.to_string())?
        };
        Ok(combined | value)
    })
}

fn outline_render_flag_symbols(flags: &[Value]) -> Result<i32, String> {
    flags.iter().try_fold(0_i32, |combined, flag| {
        let symbol = flag
            .as_str()
            .ok_or_else(|| "raster flag must be a constant name".to_string())?;
        let value = i32::try_from(rust_constant(symbol)?).map_err(|err| err.to_string())?;
        Ok(combined | value)
    })
}

fn outline_render_target_pixel_mode(params: &Value) -> Result<i32, String> {
    params
        .get("target_bitmap")
        .and_then(|bitmap| bitmap.get("pixel_mode"))
        .and_then(Value::as_str)
        .map(|symbol| i32::try_from(rust_constant(symbol)?).map_err(|err| err.to_string()))
        .transpose()
        .map(|mode| mode.unwrap_or(FT_PIXEL_MODE_GRAY))
}

fn outline_render_num_grays(pixel_mode: i32) -> u16 {
    match pixel_mode {
        FT_PIXEL_MODE_MONO => 2,
        FT_PIXEL_MODE_GRAY2 => 4,
        FT_PIXEL_MODE_GRAY4 => 16,
        _ => 256,
    }
}

fn outline_render_result_payload(flags: String, output: RunOutput) -> Value {
    let mut result = json!({
        "flags": flags,
        "status": output.status.error_code,
    });
    if !output.output.is_null() {
        if let Some(bitmap) = output.output.get("bitmap") {
            result["bitmap"] = bitmap.clone();
        }
        if let Some(value) = output.output.get("params_source_is_outline") {
            result["params_source_is_outline"] = value.clone();
        }
    }
    result
}

fn outline_render_gray_spans_present(params: &Value) -> bool {
    params
        .get("gray_spans")
        .and_then(Value::as_str)
        .is_none_or(|value| value != "NULL")
}

fn outline_render_direct_payload(
    spans: Vec<(i32, FT_Span)>,
    user_seen: bool,
    clip_box: FT_BBox,
) -> Value {
    json!({
        "status": FT_Err_Ok,
        "spans": spans
            .into_iter()
            .map(|(y, span)| {
                json!({
                    "y": y,
                    "x": span.x,
                    "len": span.len,
                    "coverage": span.coverage,
                })
            })
            .collect::<Vec<_>>(),
        "clip_box": ft_bbox_json(clip_box),
        "user_seen": user_seen,
        "target_preserved": true,
    })
}

fn c_outline_render_direct_payload(
    spans: Vec<(i32, c_abi::FT_Span)>,
    user_seen: bool,
    clip_box: FT_BBox,
) -> Value {
    let spans = spans
        .into_iter()
        .map(|(y, span)| {
            json!({
                "y": y,
                "x": u16::from_ne_bytes(span.x.to_ne_bytes()),
                "len": span.len,
                "coverage": span.coverage,
            })
        })
        .collect::<Vec<_>>();
    json!({
        "status": FT_Err_Ok,
        "spans": spans,
        "clip_box": ft_bbox_json(clip_box),
        "user_seen": user_seen,
        "target_preserved": true,
    })
}

fn outline_render_clip_box_case_payload(
    status: FT_Error,
    mutated_clip_box: FT_BBox,
    spans: Vec<(i32, FT_Span)>,
) -> Value {
    json!({
        "status": status,
        "mutated_clip_box": ft_bbox_json(mutated_clip_box),
        "spans": spans
            .into_iter()
            .map(|(y, span)| {
                json!({
                    "y": y,
                    "x": span.x,
                    "len": span.len,
                    "coverage": span.coverage,
                })
            })
            .collect::<Vec<_>>(),
    })
}

fn c_outline_render_clip_box_case_payload(
    status: FT_Error,
    mutated_clip_box: FT_BBox,
    spans: Vec<(i32, c_abi::FT_Span)>,
) -> Value {
    json!({
        "status": status,
        "mutated_clip_box": ft_bbox_json(mutated_clip_box),
        "spans": spans
            .into_iter()
            .map(|(y, span)| {
                json!({
                    "y": y,
                    "x": u16::from_ne_bytes(span.x.to_ne_bytes()),
                    "len": span.len,
                    "coverage": span.coverage,
                })
            })
            .collect::<Vec<_>>(),
    })
}

fn outline_render_observed_direct_clip_box(
    outline: &fontdone::outline::Outline,
    flags: i32,
    supplied_clip_box: Option<FT_BBox>,
) -> FT_BBox {
    if flags & i32::try_from(FT_RASTER_FLAG_CLIP).unwrap_or(0) != 0 {
        return supplied_clip_box.unwrap_or_default();
    }
    FT_BBox {
        xMin: i64::from(outline.cbox_x_min),
        yMin: i64::from(outline.cbox_y_min),
        xMax: i64::from(outline.cbox_x_max),
        yMax: i64::from(outline.cbox_y_max),
    }
}

fn ft_bbox_json(bbox: FT_BBox) -> Value {
    json!({
        "xMin": bbox.xMin,
        "yMin": bbox.yMin,
        "xMax": bbox.xMax,
        "yMax": bbox.yMax,
    })
}

fn outline_render_ffi_clip_box(params: &Value) -> Result<FT_BBox, String> {
    let Some((x_min, x_max, y_min, y_max)) = outline_render_clip_box(params)? else {
        return Ok(FT_BBox::default());
    };
    Ok(FT_BBox {
        xMin: i64::from(x_min),
        yMin: i64::from(y_min),
        xMax: i64::from(x_max),
        yMax: i64::from(y_max),
    })
}

struct CRenderOutlineStorage {
    points: Vec<c_abi::FT_Vector>,
    tags: Vec<u8>,
    contours: Vec<u16>,
    n_contours: u16,
    flags: i32,
    outline: c_abi::FT_Outline,
}

impl CRenderOutlineStorage {
    fn new(model: &fontdone::outline::Outline) -> Self {
        let snapshot = outline_render_snapshot(model);
        let mut storage = Self {
            points: snapshot
                .points
                .iter()
                .map(|point| c_abi::FT_Vector {
                    x: point.x,
                    y: point.y,
                })
                .collect(),
            tags: snapshot.tags,
            contours: snapshot.contours,
            n_contours: u16::try_from(model.n_contours).unwrap_or(0),
            flags: snapshot.flags,
            outline: c_abi::FT_Outline::default(),
        };
        storage.refresh();
        storage
    }

    fn refresh(&mut self) {
        self.outline = c_abi::FT_Outline {
            n_contours: self.n_contours,
            n_points: u16::try_from(self.points.len()).unwrap_or(u16::MAX),
            points: self.points.as_mut_ptr(),
            tags: self.tags.as_mut_ptr(),
            contours: self.contours.as_mut_ptr(),
            flags: self.flags,
        };
    }

    fn as_ptr(&mut self) -> *const c_abi::FT_Outline {
        self.refresh();
        &self.outline
    }
}

