fn rust_constant(symbol: &str) -> Result<i64, String> {
    if symbol == "FT_Err_Max" {
        return Ok(i64::from(FT_Err_Max));
    }
    generated_rust_constant(symbol).ok_or_else(|| format!("unsupported rust constant {symbol}"))
}

fn rust_constant_map(params: &Value) -> Result<Value, String> {
    let mut values = serde_json::Map::new();
    for symbol in constant_symbols_param(params)? {
        values.insert(symbol.clone(), Value::from(rust_constant(&symbol)?));
    }
    Ok(json!({ "values": values }))
}

fn rust_macro_eval(case: &InputCase) -> Result<Value, String> {
    let params = &case.inputs.params;
    if case.case == "macro_import_contract" {
        return Ok(json!({
            "macro_defined": true,
            "expansion_model": string_param(params, "expansion")?
        }));
    }

    match case.case_id.as_str() {
        "fttypes.FT_BOOL.zero_maps_to_false" | "fttypes.FT_BOOL.any_nonzero_maps_to_true" => {
            let rows = array_param(params, "values")?
                .iter()
                .map(|value| {
                    let expression = string_param(value, "expression")?;
                    Ok(json!({
                        "input": expression,
                        "result": if eval_macro_expression(expression)? != 0 { 1 } else { 0 }
                    }))
                })
                .collect::<Result<Vec<_>, String>>()?;
            Ok(json!({ "rows": rows }))
        }
        "fttypes.FT_BOOL.result_type_is_ft_bool" => Ok(json!({
            "sizeof_result": size_of::<FT_Bool>(),
            "alignof_result": align_of::<FT_Bool>(),
            "value_storage": "unsigned char"
        })),
        "fttypes.FT_ERROR_BASE.base_byte_extraction"
        | "fttypes.FT_ERROR_BASE.zero_and_full_mask_edges" => {
            let rows = array_param(params, "errors")?
                .iter()
                .map(|value| {
                    let error = eval_macro_value(value)?;
                    Ok(json!({
                        "error": error,
                        "base": error_base(error)
                    }))
                })
                .collect::<Result<Vec<_>, String>>()?;
            Ok(json!({ "rows": rows }))
        }
        "fttypes.FT_ERROR_MODULE.module_byte_extraction"
        | "fttypes.FT_ERROR_MODULE.zero_and_mixed_value_edges" => {
            let rows = array_param(params, "errors")?
                .iter()
                .map(|value| {
                    let error = eval_macro_value(value)?;
                    Ok(json!({
                        "error": error,
                        "module": error_module(error)
                    }))
                })
                .collect::<Result<Vec<_>, String>>()?;
            Ok(json!({ "rows": rows }))
        }
        "fttypes.FT_ERR.default_prefix_resolves_error_symbol" => {
            let rows = array_param(params, "errors")?
                .iter()
                .map(|value| {
                    let name = value
                        .as_str()
                        .ok_or_else(|| format!("{} error name must be a string", case.case_id))?;
                    Ok(json!({
                        "name": name,
                        "resolved_error": error_name_value(name)?
                    }))
                })
                .collect::<Result<Vec<_>, String>>()?;
            Ok(json!({ "rows": rows }))
        }
        "fttypes.FT_ERR.used_by_error_comparison_macros" => {
            let rows = array_param(params, "comparisons")?
                .iter()
                .map(|value| {
                    let macro_name = string_param(value, "macro")?;
                    let error = string_param(value, "error")?;
                    Ok(json!({
                        "macro": macro_name,
                        "error": error,
                        "result": macro_name == "FT_ERR_EQ"
                    }))
                })
                .collect::<Result<Vec<_>, String>>()?;
            Ok(json!({ "rows": rows }))
        }
        "fttypes.FT_ERR_EQ.ignores_module_bits_for_equal_base"
        | "fttypes.FT_ERR_EQ.distinguishes_different_base_codes"
        | "fttypes.FT_ERR_EQ.ok_error_comparison"
        | "fttypes.FT_ERR_NEQ.ignores_module_bits_for_equal_base"
        | "fttypes.FT_ERR_NEQ.distinguishes_different_base_codes"
        | "fttypes.FT_ERR_NEQ.ok_error_comparison" => {
            let is_equal_macro = case.subject == "fttypes.FT_ERR_EQ";
            let rows = array_param(params, "pairs")?
                .iter()
                .map(|value| {
                    let x = eval_macro_value(
                        value
                            .get("x")
                            .ok_or_else(|| format!("{} missing x", case.case_id))?,
                    )?;
                    let e = string_param(value, "e")?;
                    let equal = error_base(x) == error_base(error_name_value(e)?);
                    Ok(json!({
                        "x": x,
                        "e": e,
                        "result": if is_equal_macro { equal } else { !equal }
                    }))
                })
                .collect::<Result<Vec<_>, String>>()?;
            Ok(json!({ "rows": rows }))
        }
        "fttypes.FT_MAKE_TAG.standard_sfnt_tags"
        | "fttypes.FT_MAKE_TAG.byte_order_big_endian"
        | "fttypes.FT_MAKE_TAG.high_bit_bytes_do_not_sign_extend" => {
            let rows = array_param(params, "byte_quads")?
                .iter()
                .map(|value| {
                    let label = string_param(value, "label")?;
                    let tag = make_tag_value(array_param(value, "bytes")?)?;
                    Ok(json!({
                        "label": label,
                        "tag": tag,
                        "hex": format!("0x{tag:08x}")
                    }))
                })
                .collect::<Result<Vec<_>, String>>()?;
            Ok(json!({ "rows": rows }))
        }
        "fttypes.FT_IS_EMPTY.empty_when_head_null"
        | "fttypes.FT_IS_EMPTY.tail_is_not_considered" => {
            let head_null = params.get("head").is_none_or(Value::is_null);
            let tail_null = params.get("tail").is_none_or(Value::is_null);
            Ok(json!({
                "head_null": head_null,
                "tail_null": tail_null,
                "result": head_null
            }))
        }
        "fttypes.FT_IS_EMPTY.non_empty_when_head_nonnull" => {
            let rows = array_param(params, "scenarios")?
                .iter()
                .map(|value| {
                    let head_null = value.get("head").is_none_or(Value::is_null);
                    let tail_null = value.get("tail").is_none_or(Value::is_null);
                    Ok(json!({
                        "head_null": head_null,
                        "tail_null": tail_null,
                        "result": head_null
                    }))
                })
                .collect::<Result<Vec<_>, String>>()?;
            Ok(json!({ "rows": rows }))
        }
        "ftimage.FT_IMAGE_TAG.expansion_matches_header" => Ok(json!({
            "macro": "FT_IMAGE_TAG",
            "value": rust_constant("FT_GLYPH_FORMAT_OUTLINE")?,
            "import_compiles": true
        })),
        "ftimage.FT_IMAGE_TAG.glyph_format_values_match_c" => {
            let mut values = serde_json::Map::new();
            let symbols = params
                .get("symbols")
                .and_then(Value::as_object)
                .ok_or_else(|| format!("{} missing symbols", case.case_id))?;
            for symbol in symbols.keys() {
                values.insert(symbol.clone(), Value::from(rust_constant(symbol)?));
            }
            Ok(json!({
                "values": values,
                "import_compiles": true
            }))
        }
        "ftimage.FT_CURVE_TAG.expansion_matches_header" => {
            let values = array_param(params, "tag_values")?
                .iter()
                .map(|value| Ok(Value::from(eval_macro_value(value)? & 0x03)))
                .collect::<Result<Vec<_>, String>>()?;
            Ok(json!({
                "macro": "FT_CURVE_TAG",
                "values": values,
                "import_compiles": true
            }))
        }
        "freetype.FT_LOAD_TARGET_MODE.target_mode_value" => {
            let rows = [
                ("FT_LOAD_TARGET_NORMAL", FT_LOAD_TARGET_NORMAL),
                ("FT_LOAD_TARGET_LIGHT", FT_LOAD_TARGET_LIGHT),
                ("FT_LOAD_TARGET_MONO", FT_LOAD_TARGET_MONO),
                ("FT_LOAD_TARGET_LCD", FT_LOAD_TARGET_LCD),
                ("FT_LOAD_TARGET_LCD_V", FT_LOAD_TARGET_LCD_V),
                ("FT_LOAD_TARGET_(31)", (31 & 15) << 16),
            ]
            .into_iter()
            .map(|(input, flags)| {
                json!({
                    "input_load_flags": input,
                    "mode": (flags >> 16) & 15
                })
            })
            .collect::<Vec<_>>();
            Ok(json!({
                "macro_results": rows,
                "import_compiles": true
            }))
        }
        "freetype.FT_LOAD_TARGET_.target_constructor_value" => {
            let rows = [0, 1, 2, 3, 4, 15, 16, 31]
                .into_iter()
                .map(|mode| {
                    json!({
                        "input_render_mode": mode,
                        "value": (mode & 15) << 16
                    })
                })
                .collect::<Vec<_>>();
            Ok(json!({
                "macro_results": rows,
                "import_compiles": true
            }))
        }
        "freetype.FT_ENC_TAG.value_matches_header" => {
            let samples = array_param(params, "samples")?
                .iter()
                .map(|sample| {
                    let bytes = array_param(sample, "bytes").or_else(|_| {
                        sample
                            .as_array()
                            .map(Vec::as_slice)
                            .ok_or_else(|| "FT_ENC_TAG sample must be an array".to_string())
                    })?;
                    let value = make_tag_value(bytes)?;
                    Ok(json!({
                        "bytes": bytes,
                        "value": value
                    }))
                })
                .collect::<Result<Vec<_>, String>>()?;
            Ok(json!({
                "samples": samples,
                "import_compiles": true
            }))
        }
        "ftgxval.FT_VALIDATE_GX_BITFIELD.expansion_matches_header" => {
            let rows = array_param(params, "tokens")?
                .iter()
                .map(|value| {
                    let token = value
                        .as_str()
                        .ok_or_else(|| format!("{} token must be a string", case.case_id))?;
                    Ok(json!({
                        "token": token,
                        "value": gx_validate_bitfield_value(token)?
                    }))
                })
                .collect::<Result<Vec<_>, String>>()?;
            Ok(json!({
                "macro_results": rows,
                "import_compiles": true
            }))
        }
        "ftcache.FTC_IMAGE_TYPE_COMPARE.value_matches_header" => Ok(json!({
            "macro_expansion": ["face_id", "width", "flags"],
            "probe_result": image_type_compare(
                ImageTypeProbe { face_id: 0x1000, width: 16, height: 16, flags: FT_LOAD_DEFAULT },
                ImageTypeProbe { face_id: 0x1000, width: 16, height: 99, flags: FT_LOAD_DEFAULT },
            )
        })),
        "ftcache.FTC_IMAGE_TYPE_COMPARE.height_is_ignored" => {
            let left = image_type_probe_param(params, "left")?;
            let right = image_type_probe_param(params, "right")?;
            Ok(json!({
                "result": image_type_compare(left, right)
            }))
        }
        "ftcache.FTC_IMAGE_TYPE_COMPARE.compared_fields_must_match" => {
            let rows = array_param(params, "pairs")?
                .iter()
                .map(|value| {
                    let diff = string_param(value, "diff")?;
                    Ok(json!({
                        "diff": diff,
                        "result": image_type_compare_diff(diff)?
                    }))
                })
                .collect::<Result<Vec<_>, String>>()?;
            Ok(json!({ "pairs": rows }))
        }
        "fttypes.FT_ERR.custom_prefix_token_contract" => Ok(json!({
            "rows": [
                {"call": "FT_ERR(Custom)", "resolved_token": "Probe_Err_Custom", "value": 4660},
                {"call": "FT_ERR(Other)", "resolved_token": "Probe_Err_Other", "value": 22136}
            ]
        })),
        "fttypes.FT_ERR_CAT.expands_arguments_before_concatenation" => Ok(json!({
            "rows": [
                {
                    "call": "FT_ERR_CAT(PREFIX_TOKEN, SUFFIX_TOKEN)",
                    "resolved_token": "Probe_Value",
                    "value": 42
                }
            ]
        })),
        "fttypes.FT_ERR_CAT.error_prefix_suffix_join" => {
            let rows = ["Ok", "Invalid_Argument", "Invalid_Face_Handle"]
                .into_iter()
                .map(|suffix| {
                    let value = rust_constant(&format!("FT_Err_{suffix}"))?;
                    Ok(json!({
                        "suffix": suffix,
                        "cat_value": value,
                        "ft_err_value": value
                    }))
                })
                .collect::<Result<Vec<_>, String>>()?;
            Ok(json!({ "rows": rows }))
        }
        "fttypes.FT_ERR_XCAT.direct_token_paste_without_argument_expansion" => Ok(json!({
            "rows": [
                {
                    "call": "FT_ERR_XCAT(PREFIX_TOKEN, SUFFIX_TOKEN)",
                    "resolved_token": "PREFIX_TOKENSUFFIX_TOKEN",
                    "value": 7
                }
            ]
        })),
        "fttypes.FT_ERR_XCAT.valid_identifier_concatenation" => Ok(json!({
            "rows": [
                {"call": "FT_ERR_XCAT(Probe_, Value)", "resolved_token": "Probe_Value", "value": 42},
                {"call": "FT_ERR_XCAT(FT_Err_, Ok)", "resolved_token": "FT_Err_Ok", "value": 0}
            ]
        })),
        other => Err(format!("unsupported rust macro eval {other}")),
    }
}

fn array_param<'a>(value: &'a Value, key: &str) -> Result<&'a [Value], String> {
    value
        .get(key)
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .ok_or_else(|| format!("missing array param {key}"))
}

fn string_array_param(value: &Value, key: &str) -> Result<Vec<String>, String> {
    array_param(value, key)?
        .iter()
        .map(|item| {
            item.as_str()
                .map(str::to_string)
                .ok_or_else(|| format!("{key} contains non-string value {item}"))
        })
        .collect()
}

fn eval_macro_value(value: &Value) -> Result<i64, String> {
    if let Some(value) = value.as_i64() {
        return Ok(value);
    }
    if let Some(value) = value.as_u64() {
        return i64::try_from(value).map_err(|err| err.to_string());
    }
    if let Some(expression) = value.as_str() {
        return eval_macro_expression(expression);
    }
    if let Some(expression) = value.get("expression").and_then(Value::as_str) {
        return eval_macro_expression(expression);
    }
    Err(format!("unsupported macro value {value}"))
}

fn eval_macro_expression(expression: &str) -> Result<i64, String> {
    let expression = expression.trim();
    if let Some((left, right)) = expression.split_once('|') {
        return Ok(eval_macro_expression(left)? | eval_macro_expression(right)?);
    }
    if let Some(hex) = expression.strip_prefix("0x") {
        return i64::from_str_radix(hex, 16).map_err(|err| err.to_string());
    }
    if let Some(raw) = expression.strip_suffix('L') {
        return raw.parse::<i64>().map_err(|err| err.to_string());
    }
    match expression {
        "(void*)0" => Ok(0),
        "pointer_token" => Ok(1),
        "FT_Err_Ok" => Ok(0),
        other if other.starts_with("FT_Err_") || other.starts_with("FT_Mod_Err_") => {
            rust_constant(other)
        }
        other => rust_constant(other).or_else(|_| {
            other
                .parse::<i64>()
                .map_err(|err| format!("unsupported macro expression {expression}: {err}"))
        }),
    }
}

fn error_name_value(name: &str) -> Result<i64, String> {
    if name == "Ok" {
        Ok(0)
    } else {
        rust_constant(&format!("FT_Err_{name}"))
    }
}

fn error_base(error: i64) -> i64 {
    error & 0xFF
}

fn error_module(error: i64) -> i64 {
    error & 0xFF00
}

fn make_tag_value(bytes: &[Value]) -> Result<u32, String> {
    if bytes.len() != 4 {
        return Err(format!("FT_MAKE_TAG requires 4 bytes, got {}", bytes.len()));
    }
    let mut tag = 0u32;
    for (index, value) in bytes.iter().enumerate() {
        let byte = if let Some(value) = value.as_u64() {
            u8::try_from(value).map_err(|err| err.to_string())?
        } else if let Some(value) = value.as_str() {
            let bytes = value.as_bytes();
            if bytes.len() != 1 {
                return Err(format!("tag component {value} must be one byte"));
            }
            bytes[0]
        } else {
            return Err(format!("unsupported tag component {value}"));
        };
        let shift = u32::try_from(8usize.saturating_mul(3usize.saturating_sub(index)))
            .map_err(|err| err.to_string())?;
        tag |= u32::from(byte) << shift;
    }
    Ok(tag)
}

fn gx_validate_bitfield_value(token: &str) -> Result<i64, String> {
    let index = match token {
        "feat" => rust_constant("FT_VALIDATE_feat_INDEX")?,
        "mort" => rust_constant("FT_VALIDATE_mort_INDEX")?,
        "morx" => rust_constant("FT_VALIDATE_morx_INDEX")?,
        "bsln" => rust_constant("FT_VALIDATE_bsln_INDEX")?,
        "just" => rust_constant("FT_VALIDATE_just_INDEX")?,
        "kern" => rust_constant("FT_VALIDATE_kern_INDEX")?,
        "opbd" => rust_constant("FT_VALIDATE_opbd_INDEX")?,
        "trak" => rust_constant("FT_VALIDATE_trak_INDEX")?,
        "prop" => rust_constant("FT_VALIDATE_prop_INDEX")?,
        "lcar" => rust_constant("FT_VALIDATE_lcar_INDEX")?,
        other => return Err(format!("unsupported GX validation token {other}")),
    };
    Ok(rust_constant("FT_VALIDATE_GX_START")? << index)
}

#[derive(Clone, Copy)]
struct ImageTypeProbe {
    face_id: usize,
    width: i32,
    height: i32,
    flags: i32,
}

fn image_type_probe_param(params: &Value, key: &str) -> Result<ImageTypeProbe, String> {
    let value = params
        .get(key)
        .ok_or_else(|| format!("missing image type probe {key}"))?;
    let object = value
        .as_object()
        .ok_or_else(|| format!("{key} image type probe must be an object"))?;
    Ok(ImageTypeProbe {
        face_id: usize::try_from(i64_value(
            object
                .get("face_id")
                .ok_or_else(|| format!("{key}.face_id missing"))?,
            "face_id",
        )?)
        .map_err(|err| err.to_string())?,
        width: i32::try_from(i64_value(
            object
                .get("width")
                .ok_or_else(|| format!("{key}.width missing"))?,
            "width",
        )?)
        .map_err(|err| err.to_string())?,
        height: i32::try_from(i64_value(
            object
                .get("height")
                .ok_or_else(|| format!("{key}.height missing"))?,
            "height",
        )?)
        .map_err(|err| err.to_string())?,
        flags: i32::try_from(i64_value(
            object
                .get("flags")
                .ok_or_else(|| format!("{key}.flags missing"))?,
            "flags",
        )?)
        .map_err(|err| err.to_string())?,
    })
}

fn image_type_compare(left: ImageTypeProbe, right: ImageTypeProbe) -> bool {
    let _height_is_ignored = (left.height, right.height);
    left.face_id == right.face_id && left.width == right.width && left.flags == right.flags
}

fn image_type_compare_diff(diff: &str) -> Result<bool, String> {
    let left = ImageTypeProbe {
        face_id: 0x1000,
        width: 16,
        height: 16,
        flags: FT_LOAD_DEFAULT,
    };
    let mut right = left;
    match diff {
        "face_id" => right.face_id = 0x2000,
        "width" => right.width = 32,
        "flags" => right.flags = FT_LOAD_NO_SCALE,
        other => return Err(format!("unsupported FTC_IMAGE_TYPE_COMPARE diff {other}")),
    }
    Ok(image_type_compare(left, right))
}

fn rust_type_map_probe(params: &Value) -> Result<Value, String> {
    let mut types = serde_json::Map::new();
    let symbols = type_symbols_param(params)?;
    for symbol in &symbols {
        types.insert(symbol.clone(), rust_type_probe(symbol)?);
    }
    let descriptors = symbols
        .iter()
        .map(|symbol| rust_type_probe(symbol))
        .collect::<Result<Vec<_>, _>>()?;
    let first = descriptors
        .first()
        .ok_or_else(|| "abi_type_map_probe requires at least one type".to_string())?;
    let equivalent = descriptors.iter().all(|descriptor| {
        descriptor.get("kind") == first.get("kind")
            && descriptor.get("size") == first.get("size")
            && descriptor.get("align") == first.get("align")
            && descriptor.get("signed") == first.get("signed")
    });
    Ok(json!({
        "types": types,
        "equivalent": equivalent
    }))
}

